pub fn build_gateway_formal_backend_run_artifact_metadata(
    run_id: impl Into<String>,
    adapter_request: &GatewayFormalBackendAdapterRequest,
    adapter_report: &GatewayFormalBackendAdapterReport,
) -> GatewayFormalBackendRunArtifactMetadata {
    GatewayFormalBackendRunArtifactMetadata {
        schema_version: GATEWAY_FORMAL_BACKEND_RUN_ARTIFACT_SCHEMA_VERSION.to_owned(),
        run_id: run_id.into(),
        state_slice: GATEWAY_FORMAL_BACKEND_RUN_ARTIFACT_STATE_SLICE.to_owned(),
        adapter_request_digest: adapter_request.digest(),
        adapter_report_digest: adapter_report.digest(),
        correspondence_certificate_digest: adapter_report.correspondence_certificate_digest,
        output_manifest_digest: adapter_report.output_manifest_digest,
        backend_kind: adapter_report.backend_kind.clone(),
        tool_name: adapter_request.tool_status.tool_name.clone(),
        tool_version: adapter_request.tool_status.tool_version.clone(),
        toolchain_lock_digest: adapter_request.tool_status.toolchain_lock_digest,
        execution_mode: GatewayFormalBackendRunExecutionMode::NotRun,
        started_at_unix: None,
        finished_at_unix: None,
        exit_status: GatewayFormalBackendRunExitStatus::NotRun,
        checker_status: GatewayFormalBackendRunCheckerStatus::NotRun,
        proof_obligations_requested: adapter_request.proof_obligations.clone(),
        proof_obligations_discharged: BTreeSet::new(),
        proof_obligations_not_discharged: BTreeSet::new(),
        modeled_assumptions_digest: gateway_formal_backend_run_model_assumptions_digest(
            adapter_request,
        ),
        unsupported_rust_features_digest: gateway_formal_backend_run_unsupported_features_digest(
            adapter_request,
        ),
        candidate_proof_artifact_ref: None,
        candidate_checker_transcript_ref: None,
        candidate_tool_log_summary_digest: None,
        claim_boundary: gateway_formal_backend_run_artifact_claim_boundary(),
        creates_accepted_evidence: false,
        creates_level2_evidence: false,
        populates_score_axes: false,
        grants_authority: false,
        semantic_correctness_claimed: false,
        production_readiness_claimed: false,
        sota_claimed: false,
        full_security_claimed: false,
        claim_text: Vec::new(),
        nonclaims: gateway_formal_backend_run_artifact_required_nonclaims(),
    }
}

pub fn validate_gateway_formal_backend_run_artifact_metadata(
    metadata: &GatewayFormalBackendRunArtifactMetadata,
    adapter_request: &GatewayFormalBackendAdapterRequest,
    adapter_report: &GatewayFormalBackendAdapterReport,
) -> GatewayFormalBackendRunArtifactValidation {
    let mut issues = Vec::new();

    if metadata.schema_version != GATEWAY_FORMAL_BACKEND_RUN_ARTIFACT_SCHEMA_VERSION {
        issues.push(GatewayFormalBackendRunArtifactIssue::InvalidSchemaVersion);
    }
    if metadata.run_id.trim().is_empty()
        || !is_safe_relative_path(&metadata.run_id)
        || metadata.run_id.contains(['/', '\\'])
    {
        issues.push(GatewayFormalBackendRunArtifactIssue::InvalidRunId);
    }
    if metadata.state_slice != GATEWAY_FORMAL_BACKEND_RUN_ARTIFACT_STATE_SLICE {
        issues.push(GatewayFormalBackendRunArtifactIssue::StateSliceMismatch);
    }
    if !adapter_report.validation.valid
        || adapter_report.status != GatewayFormalBackendAdapterStatus::LocalMetadataOnly
        || adapter_report.maturity != GatewayFormalBackendAdapterMaturity::NotRun
    {
        issues.push(GatewayFormalBackendRunArtifactIssue::AdapterReportRejected);
    }
    if metadata.adapter_request_digest != adapter_request.digest() {
        issues.push(GatewayFormalBackendRunArtifactIssue::AdapterRequestDigestMismatch);
    }
    if adapter_report.request_digest != adapter_request.digest() {
        issues.push(GatewayFormalBackendRunArtifactIssue::AdapterRequestDigestMismatch);
    }
    if metadata.adapter_report_digest != adapter_report.digest() {
        issues.push(GatewayFormalBackendRunArtifactIssue::AdapterReportDigestMismatch);
    }
    if metadata.correspondence_certificate_digest
        != adapter_report.correspondence_certificate_digest
        || adapter_request.correspondence_certificate_digest
            != adapter_report.correspondence_certificate_digest
    {
        issues.push(GatewayFormalBackendRunArtifactIssue::CorrespondenceCertificateDigestMismatch);
    }
    if metadata.output_manifest_digest != adapter_report.output_manifest_digest
        || adapter_request.output_manifest_digest != adapter_report.output_manifest_digest
    {
        issues.push(GatewayFormalBackendRunArtifactIssue::OutputManifestDigestMismatch);
    }
    if metadata.backend_kind != adapter_report.backend_kind
        || adapter_request.backend_kind != adapter_report.backend_kind
    {
        issues.push(GatewayFormalBackendRunArtifactIssue::BackendKindMismatch);
    }
    if metadata.tool_name != adapter_request.tool_status.tool_name {
        issues.push(GatewayFormalBackendRunArtifactIssue::ToolNameMismatch);
    }
    if metadata.tool_version != adapter_request.tool_status.tool_version {
        issues.push(GatewayFormalBackendRunArtifactIssue::ToolVersionMismatch);
    }
    if metadata.toolchain_lock_digest != adapter_request.tool_status.toolchain_lock_digest
        || metadata.toolchain_lock_digest == Hash([0; 32])
    {
        issues.push(GatewayFormalBackendRunArtifactIssue::ToolchainLockDigestMismatch);
    }
    if metadata.execution_mode != GatewayFormalBackendRunExecutionMode::NotRun {
        issues.push(GatewayFormalBackendRunArtifactIssue::ExecutionModeNotRunMismatch);
    }
    if metadata.started_at_unix.is_some() || metadata.finished_at_unix.is_some() {
        issues.push(GatewayFormalBackendRunArtifactIssue::TimestampSubmitted);
    }
    if metadata.exit_status != GatewayFormalBackendRunExitStatus::NotRun {
        issues.push(GatewayFormalBackendRunArtifactIssue::ExitStatusNotRunMismatch);
    }
    if metadata.checker_status != GatewayFormalBackendRunCheckerStatus::NotRun {
        issues.push(GatewayFormalBackendRunArtifactIssue::CheckerStatusNotRunMismatch);
    }
    if metadata.proof_obligations_requested != adapter_request.proof_obligations {
        issues.push(GatewayFormalBackendRunArtifactIssue::ProofObligationsRequestedMismatch);
    }
    if !metadata.proof_obligations_discharged.is_empty() {
        issues.push(GatewayFormalBackendRunArtifactIssue::ProofObligationsDischargedBeforeRun);
    }
    if !metadata.proof_obligations_not_discharged.is_empty() {
        issues.push(GatewayFormalBackendRunArtifactIssue::ProofObligationsNotDischargedBeforeRun);
    }
    if metadata.modeled_assumptions_digest
        != gateway_formal_backend_run_model_assumptions_digest(adapter_request)
    {
        issues.push(GatewayFormalBackendRunArtifactIssue::ModeledAssumptionsDigestMismatch);
    }
    if metadata.unsupported_rust_features_digest
        != gateway_formal_backend_run_unsupported_features_digest(adapter_request)
    {
        issues.push(GatewayFormalBackendRunArtifactIssue::UnsupportedRustFeaturesDigestMismatch);
    }
    if let Some(reference) = &metadata.candidate_proof_artifact_ref {
        validate_gateway_formal_backend_run_artifact_reference(reference, &mut issues);
        issues.push(GatewayFormalBackendRunArtifactIssue::ProofArtifactReferenceSubmitted);
    }
    if let Some(reference) = &metadata.candidate_checker_transcript_ref {
        validate_gateway_formal_backend_run_artifact_reference(reference, &mut issues);
        issues.push(GatewayFormalBackendRunArtifactIssue::CheckerTranscriptReferenceSubmitted);
    }
    if metadata.candidate_tool_log_summary_digest.is_some() {
        issues.push(GatewayFormalBackendRunArtifactIssue::ToolLogSummarySubmitted);
    }
    if metadata.claim_boundary != gateway_formal_backend_run_artifact_claim_boundary() {
        issues.push(GatewayFormalBackendRunArtifactIssue::ClaimBoundaryMismatch);
    }
    if metadata.creates_accepted_evidence {
        issues.push(GatewayFormalBackendRunArtifactIssue::AcceptedEvidenceCreated);
    }
    if metadata.creates_level2_evidence {
        issues.push(GatewayFormalBackendRunArtifactIssue::Level2EvidenceCreated);
    }
    if metadata.populates_score_axes {
        issues.push(GatewayFormalBackendRunArtifactIssue::ScoreAxesPopulated);
    }
    if metadata.grants_authority {
        issues.push(GatewayFormalBackendRunArtifactIssue::AuthorityGranted);
    }
    if metadata.semantic_correctness_claimed {
        issues.push(GatewayFormalBackendRunArtifactIssue::SemanticCorrectnessClaimed);
    }
    if metadata.production_readiness_claimed {
        issues.push(GatewayFormalBackendRunArtifactIssue::ProductionReadinessClaimed);
    }
    if metadata.sota_claimed {
        issues.push(GatewayFormalBackendRunArtifactIssue::SotaClaimed);
    }
    if metadata.full_security_claimed {
        issues.push(GatewayFormalBackendRunArtifactIssue::FullSecurityClaimed);
    }
    for forbidden in gateway_formal_evidence_forbidden_claim_fragments() {
        if metadata
            .claim_text
            .iter()
            .any(|text| text.to_ascii_lowercase().contains(forbidden))
        {
            issues.push(GatewayFormalBackendRunArtifactIssue::ForbiddenClaimText(
                (*forbidden).to_owned(),
            ));
        }
    }
    for required in gateway_formal_backend_run_artifact_required_nonclaims() {
        if !metadata.nonclaims.contains(&required) {
            issues.push(GatewayFormalBackendRunArtifactIssue::MissingRequiredNonclaim(required.0));
        }
    }

    GatewayFormalBackendRunArtifactValidation {
        valid: issues.is_empty(),
        issues,
    }
}

fn validate_gateway_formal_backend_run_artifact_reference(
    reference: &GatewayFormalBackendRunArtifactReference,
    issues: &mut Vec<GatewayFormalBackendRunArtifactIssue>,
) {
    if !is_safe_relative_path(&reference.logical_path)
        || !reference
            .logical_path
            .starts_with("gateway-formal-backend-run/")
    {
        issues.push(
            GatewayFormalBackendRunArtifactIssue::InvalidArtifactReference(
                reference.logical_path.clone(),
            ),
        );
    }
    if reference.digest == Hash([0; 32]) || !reference.redacted {
        issues.push(
            GatewayFormalBackendRunArtifactIssue::ArtifactReferenceMissingDigest(
                reference.logical_path.clone(),
            ),
        );
    }
    if reference.retains_raw_content {
        issues.push(
            GatewayFormalBackendRunArtifactIssue::ArtifactReferenceRetainsRawContent(
                reference.logical_path.clone(),
            ),
        );
    }
}

pub fn gateway_formal_backend_run_declared_files() -> Vec<String> {
    GATEWAY_FORMAL_BACKEND_RUN_DECLARED_FILES
        .iter()
        .map(|value| (*value).to_owned())
        .collect()
}

pub fn materialize_gateway_formal_backend_run_bundle(
    output_root: &Path,
    adapter_request: &GatewayFormalBackendAdapterRequest,
    adapter_report: &GatewayFormalBackendAdapterReport,
    run_metadata: &GatewayFormalBackendRunArtifactMetadata,
    request: &GatewayFormalBackendRunOutputRequest,
) -> Result<GatewayFormalBackendRunOutputManifest, GatewayFormalBackendRunOutputError> {
    validate_gateway_formal_backend_run_output_request(
        output_root,
        adapter_request,
        adapter_report,
        run_metadata,
        request,
    )?;
    let staging_root =
        gateway_formal_backend_run_staging_root_for(output_root, &request.bundle_id)?;
    if staging_root.exists() {
        remove_gateway_formal_backend_run_dir_all_checked(&staging_root)?;
    }
    fs::create_dir_all(staging_root.join("gateway-formal-backend-run"))
        .map_err(gateway_formal_backend_run_io_error)?;

    let files = build_gateway_formal_backend_run_bundle_files(
        adapter_request,
        adapter_report,
        run_metadata,
        request,
    )?;
    for (logical_path, bytes) in &files {
        let target = staging_root.join(logical_path);
        if let Some(parent) = target.parent() {
            fs::create_dir_all(parent).map_err(gateway_formal_backend_run_io_error)?;
        }
        fs::write(&target, bytes).map_err(gateway_formal_backend_run_io_error)?;
        fs::write(
            sidecar_path(&target),
            hash_hex(hash_bytes(bytes)).into_bytes(),
        )
        .map_err(gateway_formal_backend_run_io_error)?;
    }

    if output_root.exists() {
        if !request.overwrite {
            remove_gateway_formal_backend_run_dir_all_checked(&staging_root)?;
            return Err(GatewayFormalBackendRunOutputError::OutputRootExistsWithoutOverwrite);
        }
        remove_gateway_formal_backend_run_dir_all_checked(output_root)?;
    }
    fs::rename(&staging_root, output_root).map_err(gateway_formal_backend_run_io_error)?;
    read_gateway_formal_backend_run_bundle(output_root)
}

pub fn read_gateway_formal_backend_run_bundle(
    output_root: &Path,
) -> Result<GatewayFormalBackendRunOutputManifest, GatewayFormalBackendRunOutputError> {
    let output_metadata =
        fs::symlink_metadata(output_root).map_err(gateway_formal_backend_run_io_error)?;
    if output_metadata.file_type().is_symlink() {
        return Err(GatewayFormalBackendRunOutputError::OutputRootIsSymlink);
    }
    if !output_metadata.is_dir() {
        return Err(GatewayFormalBackendRunOutputError::OutputRootIsFile);
    }
    let bundle_dir = output_root.join("gateway-formal-backend-run");
    let bundle_metadata =
        fs::symlink_metadata(&bundle_dir).map_err(gateway_formal_backend_run_io_error)?;
    if bundle_metadata.file_type().is_symlink() {
        return Err(GatewayFormalBackendRunOutputError::BundleFileIsSymlink(
            "gateway-formal-backend-run".to_owned(),
        ));
    }
    if !bundle_metadata.is_dir() {
        return Err(
            GatewayFormalBackendRunOutputError::DeclaredFileTypeMismatch(
                "gateway-formal-backend-run".to_owned(),
            ),
        );
    }

    reject_undeclared_gateway_formal_backend_run_files(output_root)?;
    let mut file_bytes = BTreeMap::new();
    for logical_path in GATEWAY_FORMAL_BACKEND_RUN_DECLARED_FILES {
        let path = output_root.join(logical_path);
        let metadata = fs::symlink_metadata(&path).map_err(gateway_formal_backend_run_io_error)?;
        if metadata.file_type().is_symlink() {
            return Err(GatewayFormalBackendRunOutputError::BundleFileIsSymlink(
                (*logical_path).to_owned(),
            ));
        }
        if !metadata.is_file() {
            return Err(
                GatewayFormalBackendRunOutputError::DeclaredFileTypeMismatch(
                    (*logical_path).to_owned(),
                ),
            );
        }
        let sidecar = sidecar_path(&path);
        let sidecar_metadata =
            fs::symlink_metadata(&sidecar).map_err(gateway_formal_backend_run_io_error)?;
        if sidecar_metadata.file_type().is_symlink() {
            return Err(GatewayFormalBackendRunOutputError::BundleFileIsSymlink(
                format!("{logical_path}.sha256"),
            ));
        }
        if !sidecar_metadata.is_file() {
            return Err(
                GatewayFormalBackendRunOutputError::DeclaredFileTypeMismatch(format!(
                    "{logical_path}.sha256"
                )),
            );
        }
        let bytes = fs::read(&path).map_err(gateway_formal_backend_run_io_error)?;
        let expected = fs::read_to_string(sidecar).map_err(gateway_formal_backend_run_io_error)?;
        if expected != hash_hex(hash_bytes(&bytes)) {
            return Err(GatewayFormalBackendRunOutputError::DigestMismatch(
                (*logical_path).to_owned(),
            ));
        }
        file_bytes.insert((*logical_path).to_owned(), bytes);
    }

    validate_gateway_formal_backend_run_bundle_semantics(&file_bytes)
}

fn validate_gateway_formal_backend_run_output_request(
    output_root: &Path,
    adapter_request: &GatewayFormalBackendAdapterRequest,
    adapter_report: &GatewayFormalBackendAdapterReport,
    run_metadata: &GatewayFormalBackendRunArtifactMetadata,
    request: &GatewayFormalBackendRunOutputRequest,
) -> Result<(), GatewayFormalBackendRunOutputError> {
    if request.bundle_id.trim().is_empty()
        || !is_safe_relative_path(&request.bundle_id)
        || request.bundle_id.contains(['/', '\\'])
    {
        return Err(GatewayFormalBackendRunOutputError::EmptyBundleId);
    }
    let validation = validate_gateway_formal_backend_run_artifact_metadata(
        run_metadata,
        adapter_request,
        adapter_report,
    );
    if !validation.valid {
        return Err(GatewayFormalBackendRunOutputError::InvalidRunArtifact(
            validation.issues,
        ));
    }
    validate_gateway_formal_backend_run_output_root(
        output_root,
        &request.protected_roots,
        request.overwrite,
    )
}

fn build_gateway_formal_backend_run_bundle_files(
    adapter_request: &GatewayFormalBackendAdapterRequest,
    adapter_report: &GatewayFormalBackendAdapterReport,
    run_metadata: &GatewayFormalBackendRunArtifactMetadata,
    request: &GatewayFormalBackendRunOutputRequest,
) -> Result<BTreeMap<String, Vec<u8>>, GatewayFormalBackendRunOutputError> {
    let validation = validate_gateway_formal_backend_run_artifact_metadata(
        run_metadata,
        adapter_request,
        adapter_report,
    );
    if !validation.valid {
        return Err(GatewayFormalBackendRunOutputError::InvalidRunArtifact(
            validation.issues,
        ));
    }

    let redaction_report = gateway_formal_backend_run_redaction_report();
    let toolchain_lock = gateway_formal_backend_run_toolchain_lock(adapter_request);
    let nonclaims = render_gateway_formal_backend_run_nonclaims(&run_metadata.nonclaims);
    let mut files = BTreeMap::from([
        (
            "gateway-formal-backend-run/adapter-request.json".to_owned(),
            serde_json::to_vec_pretty(adapter_request)
                .map_err(gateway_formal_backend_run_serde_error)?,
        ),
        (
            "gateway-formal-backend-run/adapter-report.json".to_owned(),
            serde_json::to_vec_pretty(adapter_report)
                .map_err(gateway_formal_backend_run_serde_error)?,
        ),
        (
            "gateway-formal-backend-run/run-summary.json".to_owned(),
            serde_json::to_vec_pretty(run_metadata)
                .map_err(gateway_formal_backend_run_serde_error)?,
        ),
        (
            "gateway-formal-backend-run/correspondence-certificate-digest.json".to_owned(),
            serde_json::to_vec_pretty(&adapter_report.correspondence_certificate_digest)
                .map_err(gateway_formal_backend_run_serde_error)?,
        ),
        (
            "gateway-formal-backend-run/correspondence-output-manifest-digest.json".to_owned(),
            serde_json::to_vec_pretty(&adapter_report.output_manifest_digest)
                .map_err(gateway_formal_backend_run_serde_error)?,
        ),
        (
            "gateway-formal-backend-run/source-digests.json".to_owned(),
            serde_json::to_vec_pretty(&adapter_request.source_files)
                .map_err(gateway_formal_backend_run_serde_error)?,
        ),
        (
            "gateway-formal-backend-run/toolchain-lock.json".to_owned(),
            serde_json::to_vec_pretty(&toolchain_lock)
                .map_err(gateway_formal_backend_run_serde_error)?,
        ),
        (
            "gateway-formal-backend-run/model-assumptions.json".to_owned(),
            serde_json::to_vec_pretty(&adapter_request.model_assumptions)
                .map_err(gateway_formal_backend_run_serde_error)?,
        ),
        (
            "gateway-formal-backend-run/unsupported-rust-features.json".to_owned(),
            serde_json::to_vec_pretty(&adapter_request.unsupported_rust_features)
                .map_err(gateway_formal_backend_run_serde_error)?,
        ),
        (
            "gateway-formal-backend-run/proof-obligations.json".to_owned(),
            serde_json::to_vec_pretty(&adapter_request.proof_obligations)
                .map_err(gateway_formal_backend_run_serde_error)?,
        ),
        (
            "gateway-formal-backend-run/redaction-report.json".to_owned(),
            serde_json::to_vec_pretty(&redaction_report)
                .map_err(gateway_formal_backend_run_serde_error)?,
        ),
        (
            "gateway-formal-backend-run/nonclaims.md".to_owned(),
            nonclaims.into_bytes(),
        ),
    ]);
    let manifest = gateway_formal_backend_run_output_manifest_for_files(
        adapter_request,
        adapter_report,
        run_metadata,
        request,
        &files,
    );
    files.insert(
        "gateway-formal-backend-run/manifest.json".to_owned(),
        serde_json::to_vec_pretty(&manifest).map_err(gateway_formal_backend_run_serde_error)?,
    );
    Ok(files)
}

fn gateway_formal_backend_run_output_manifest_for_files(
    adapter_request: &GatewayFormalBackendAdapterRequest,
    adapter_report: &GatewayFormalBackendAdapterReport,
    run_metadata: &GatewayFormalBackendRunArtifactMetadata,
    request: &GatewayFormalBackendRunOutputRequest,
    files: &BTreeMap<String, Vec<u8>>,
) -> GatewayFormalBackendRunOutputManifest {
    let mut declared_file_digests = BTreeMap::new();
    for (logical_path, bytes) in files {
        declared_file_digests.insert(logical_path.clone(), hash_bytes(bytes));
    }
    GatewayFormalBackendRunOutputManifest {
        schema_version: GATEWAY_FORMAL_BACKEND_RUN_OUTPUT_SCHEMA_VERSION.to_owned(),
        bundle_id: request.bundle_id.clone(),
        state_slice: GATEWAY_FORMAL_BACKEND_RUN_ARTIFACT_STATE_SLICE.to_owned(),
        created_at_unix: request.created_at_unix,
        adapter_request_digest: adapter_request.digest(),
        adapter_report_digest: adapter_report.digest(),
        run_summary_digest: run_metadata.digest(),
        correspondence_certificate_digest: adapter_report.correspondence_certificate_digest,
        correspondence_output_manifest_digest: adapter_report.output_manifest_digest,
        source_digests_digest: hash_bytes(
            files
                .get("gateway-formal-backend-run/source-digests.json")
                .map(Vec::as_slice)
                .unwrap_or_default(),
        ),
        toolchain_lock_file_digest: hash_bytes(
            files
                .get("gateway-formal-backend-run/toolchain-lock.json")
                .map(Vec::as_slice)
                .unwrap_or_default(),
        ),
        model_assumptions_digest: hash_bytes(
            files
                .get("gateway-formal-backend-run/model-assumptions.json")
                .map(Vec::as_slice)
                .unwrap_or_default(),
        ),
        unsupported_rust_features_digest: hash_bytes(
            files
                .get("gateway-formal-backend-run/unsupported-rust-features.json")
                .map(Vec::as_slice)
                .unwrap_or_default(),
        ),
        proof_obligations_digest: hash_bytes(
            files
                .get("gateway-formal-backend-run/proof-obligations.json")
                .map(Vec::as_slice)
                .unwrap_or_default(),
        ),
        redaction_report_digest: hash_bytes(
            files
                .get("gateway-formal-backend-run/redaction-report.json")
                .map(Vec::as_slice)
                .unwrap_or_default(),
        ),
        nonclaims_digest: hash_bytes(
            files
                .get("gateway-formal-backend-run/nonclaims.md")
                .map(Vec::as_slice)
                .unwrap_or_default(),
        ),
        declared_files: gateway_formal_backend_run_declared_files(),
        declared_file_digests,
        claim_boundary: gateway_formal_backend_run_artifact_claim_boundary(),
        creates_accepted_evidence: false,
        creates_level2_evidence: false,
        populates_score_axes: false,
        grants_authority: false,
        nonclaims: run_metadata.nonclaims.clone(),
    }
}

fn validate_gateway_formal_backend_run_bundle_semantics(
    files: &BTreeMap<String, Vec<u8>>,
) -> Result<GatewayFormalBackendRunOutputManifest, GatewayFormalBackendRunOutputError> {
    let manifest: GatewayFormalBackendRunOutputManifest =
        parse_gateway_formal_backend_run_declared_json(
            files,
            "gateway-formal-backend-run/manifest.json",
        )?;
    let adapter_request: GatewayFormalBackendAdapterRequest =
        parse_gateway_formal_backend_run_declared_json(
            files,
            "gateway-formal-backend-run/adapter-request.json",
        )?;
    let adapter_report: GatewayFormalBackendAdapterReport =
        parse_gateway_formal_backend_run_declared_json(
            files,
            "gateway-formal-backend-run/adapter-report.json",
        )?;
    let run_metadata: GatewayFormalBackendRunArtifactMetadata =
        parse_gateway_formal_backend_run_declared_json(
            files,
            "gateway-formal-backend-run/run-summary.json",
        )?;

    let validation = validate_gateway_formal_backend_run_artifact_metadata(
        &run_metadata,
        &adapter_request,
        &adapter_report,
    );
    if !validation.valid {
        return Err(GatewayFormalBackendRunOutputError::InvalidRunArtifact(
            validation.issues,
        ));
    }

    let certificate_digest: Hash = parse_gateway_formal_backend_run_declared_json(
        files,
        "gateway-formal-backend-run/correspondence-certificate-digest.json",
    )?;
    if certificate_digest != adapter_report.correspondence_certificate_digest {
        return Err(GatewayFormalBackendRunOutputError::ManifestSemanticMismatch);
    }
    let output_manifest_digest: Hash = parse_gateway_formal_backend_run_declared_json(
        files,
        "gateway-formal-backend-run/correspondence-output-manifest-digest.json",
    )?;
    if output_manifest_digest != adapter_report.output_manifest_digest {
        return Err(GatewayFormalBackendRunOutputError::ManifestSemanticMismatch);
    }
    let source_files: Vec<GatewayFormalSourceFileDigest> =
        parse_gateway_formal_backend_run_declared_json(
            files,
            "gateway-formal-backend-run/source-digests.json",
        )?;
    if source_files != adapter_request.source_files {
        return Err(GatewayFormalBackendRunOutputError::ManifestSemanticMismatch);
    }
    let toolchain_lock: GatewayFormalBackendRunToolchainLock =
        parse_gateway_formal_backend_run_declared_json(
            files,
            "gateway-formal-backend-run/toolchain-lock.json",
        )?;
    if toolchain_lock != gateway_formal_backend_run_toolchain_lock(&adapter_request) {
        return Err(GatewayFormalBackendRunOutputError::ManifestSemanticMismatch);
    }
    let model_assumptions: BTreeSet<String> = parse_gateway_formal_backend_run_declared_json(
        files,
        "gateway-formal-backend-run/model-assumptions.json",
    )?;
    if model_assumptions != adapter_request.model_assumptions {
        return Err(GatewayFormalBackendRunOutputError::ManifestSemanticMismatch);
    }
    let unsupported_features: BTreeSet<String> = parse_gateway_formal_backend_run_declared_json(
        files,
        "gateway-formal-backend-run/unsupported-rust-features.json",
    )?;
    if unsupported_features != adapter_request.unsupported_rust_features {
        return Err(GatewayFormalBackendRunOutputError::ManifestSemanticMismatch);
    }
    let proof_obligations: BTreeSet<GatewayFormalProofObligationId> =
        parse_gateway_formal_backend_run_declared_json(
            files,
            "gateway-formal-backend-run/proof-obligations.json",
        )?;
    if proof_obligations != adapter_request.proof_obligations {
        return Err(GatewayFormalBackendRunOutputError::ManifestSemanticMismatch);
    }
    let redaction_report: GatewayFormalBackendRunRedactionReport =
        parse_gateway_formal_backend_run_declared_json(
            files,
            "gateway-formal-backend-run/redaction-report.json",
        )?;
    if redaction_report != gateway_formal_backend_run_redaction_report() {
        return Err(GatewayFormalBackendRunOutputError::RedactionReportMismatch);
    }
    if declared_gateway_formal_backend_run_bytes(files, "gateway-formal-backend-run/nonclaims.md")?
        != render_gateway_formal_backend_run_nonclaims(&run_metadata.nonclaims).as_bytes()
    {
        return Err(GatewayFormalBackendRunOutputError::NonclaimMismatch);
    }

    let expected_request = GatewayFormalBackendRunOutputRequest {
        bundle_id: manifest.bundle_id.clone(),
        created_at_unix: manifest.created_at_unix,
        overwrite: false,
        protected_roots: Vec::new(),
    };
    validate_gateway_formal_backend_run_manifest_semantics(
        &manifest,
        &adapter_request,
        &adapter_report,
        &run_metadata,
        &expected_request,
        files,
    )?;
    Ok(manifest)
}

fn validate_gateway_formal_backend_run_manifest_semantics(
    manifest: &GatewayFormalBackendRunOutputManifest,
    adapter_request: &GatewayFormalBackendAdapterRequest,
    adapter_report: &GatewayFormalBackendAdapterReport,
    run_metadata: &GatewayFormalBackendRunArtifactMetadata,
    request: &GatewayFormalBackendRunOutputRequest,
    files: &BTreeMap<String, Vec<u8>>,
) -> Result<(), GatewayFormalBackendRunOutputError> {
    let expected_digest_paths: BTreeSet<String> = GATEWAY_FORMAL_BACKEND_RUN_DECLARED_FILES
        .iter()
        .filter(|path| **path != "gateway-formal-backend-run/manifest.json")
        .map(|path| (*path).to_owned())
        .collect();
    let actual_digest_paths: BTreeSet<String> =
        manifest.declared_file_digests.keys().cloned().collect();
    if manifest.schema_version != GATEWAY_FORMAL_BACKEND_RUN_OUTPUT_SCHEMA_VERSION
        || manifest.bundle_id != request.bundle_id
        || manifest.state_slice != GATEWAY_FORMAL_BACKEND_RUN_ARTIFACT_STATE_SLICE
        || manifest.created_at_unix != request.created_at_unix
        || manifest.adapter_request_digest != adapter_request.digest()
        || manifest.adapter_report_digest != adapter_report.digest()
        || manifest.run_summary_digest != run_metadata.digest()
        || manifest.correspondence_certificate_digest
            != adapter_report.correspondence_certificate_digest
        || manifest.correspondence_output_manifest_digest != adapter_report.output_manifest_digest
        || manifest.source_digests_digest
            != hash_bytes(declared_gateway_formal_backend_run_bytes(
                files,
                "gateway-formal-backend-run/source-digests.json",
            )?)
        || manifest.toolchain_lock_file_digest
            != hash_bytes(declared_gateway_formal_backend_run_bytes(
                files,
                "gateway-formal-backend-run/toolchain-lock.json",
            )?)
        || manifest.model_assumptions_digest
            != hash_bytes(declared_gateway_formal_backend_run_bytes(
                files,
                "gateway-formal-backend-run/model-assumptions.json",
            )?)
        || manifest.unsupported_rust_features_digest
            != hash_bytes(declared_gateway_formal_backend_run_bytes(
                files,
                "gateway-formal-backend-run/unsupported-rust-features.json",
            )?)
        || manifest.proof_obligations_digest
            != hash_bytes(declared_gateway_formal_backend_run_bytes(
                files,
                "gateway-formal-backend-run/proof-obligations.json",
            )?)
        || manifest.redaction_report_digest
            != hash_bytes(declared_gateway_formal_backend_run_bytes(
                files,
                "gateway-formal-backend-run/redaction-report.json",
            )?)
        || manifest.nonclaims_digest
            != hash_bytes(declared_gateway_formal_backend_run_bytes(
                files,
                "gateway-formal-backend-run/nonclaims.md",
            )?)
        || manifest.declared_files != gateway_formal_backend_run_declared_files()
        || actual_digest_paths != expected_digest_paths
        || manifest
            .declared_file_digests
            .values()
            .any(|digest| *digest == Hash([0; 32]))
        || manifest.claim_boundary != gateway_formal_backend_run_artifact_claim_boundary()
        || manifest.creates_accepted_evidence
        || manifest.creates_level2_evidence
        || manifest.populates_score_axes
        || manifest.grants_authority
        || manifest.nonclaims != run_metadata.nonclaims
    {
        return Err(GatewayFormalBackendRunOutputError::ManifestSemanticMismatch);
    }
    for (logical_path, expected_digest) in &manifest.declared_file_digests {
        if hash_bytes(declared_gateway_formal_backend_run_bytes(
            files,
            logical_path,
        )?) != *expected_digest
        {
            return Err(GatewayFormalBackendRunOutputError::DigestMismatch(
                logical_path.clone(),
            ));
        }
    }
    Ok(())
}

fn gateway_formal_backend_run_toolchain_lock(
    adapter_request: &GatewayFormalBackendAdapterRequest,
) -> GatewayFormalBackendRunToolchainLock {
    GatewayFormalBackendRunToolchainLock {
        backend_kind: adapter_request.tool_status.backend_kind.clone(),
        tool_name: adapter_request.tool_status.tool_name.clone(),
        tool_version: adapter_request.tool_status.tool_version.clone(),
        toolchain_lock_digest: adapter_request.tool_status.toolchain_lock_digest,
    }
}

fn gateway_formal_backend_run_redaction_report() -> GatewayFormalBackendRunRedactionReport {
    GatewayFormalBackendRunRedactionReport {
        retains_credentials_or_secrets: false,
        retains_proof_assistant_cache: false,
        retains_raw_prover_logs: false,
        retains_raw_checker_transcripts: false,
        retains_raw_smt_solver_traces: false,
        retains_raw_external_repo_source: false,
        retains_accepted_evidence_ledger_json: false,
        retains_benchmark_outputs: false,
        retains_live_provider_responses: false,
        retains_generated_proof_artifacts: false,
        retains_generated_checker_artifacts: false,
        materializes_optional_attachments: false,
    }
}

fn render_gateway_formal_backend_run_nonclaims(nonclaims: &BTreeSet<NonClaimLabel>) -> String {
    let mut out = String::from("# Gateway Formal Backend Run Nonclaims\n\n");
    for nonclaim in nonclaims {
        out.push_str("- ");
        out.push_str(&nonclaim.0);
        out.push('\n');
    }
    out
}

fn declared_gateway_formal_backend_run_bytes<'a>(
    files: &'a BTreeMap<String, Vec<u8>>,
    logical_path: &str,
) -> Result<&'a [u8], GatewayFormalBackendRunOutputError> {
    files.get(logical_path).map(Vec::as_slice).ok_or_else(|| {
        GatewayFormalBackendRunOutputError::Io(format!("declared file missing: {logical_path}"))
    })
}

fn parse_gateway_formal_backend_run_declared_json<T: for<'de> Deserialize<'de>>(
    files: &BTreeMap<String, Vec<u8>>,
    logical_path: &str,
) -> Result<T, GatewayFormalBackendRunOutputError> {
    let bytes = declared_gateway_formal_backend_run_bytes(files, logical_path)?;
    let text = std::str::from_utf8(bytes).map_err(|_| {
        GatewayFormalBackendRunOutputError::MalformedDeclaredFile(logical_path.to_owned())
    })?;
    serde_json::from_str(text).map_err(|_| {
        GatewayFormalBackendRunOutputError::MalformedDeclaredFile(logical_path.to_owned())
    })
}

fn reject_undeclared_gateway_formal_backend_run_files(
    output_root: &Path,
) -> Result<(), GatewayFormalBackendRunOutputError> {
    let mut declared: BTreeSet<String> = GATEWAY_FORMAL_BACKEND_RUN_DECLARED_FILES
        .iter()
        .chain(GATEWAY_FORMAL_BACKEND_RUN_DECLARED_SIDECARS.iter())
        .map(|value| (*value).to_owned())
        .collect();
    let bundle_dir = output_root.join("gateway-formal-backend-run");
    for entry in fs::read_dir(&bundle_dir).map_err(gateway_formal_backend_run_io_error)? {
        let entry = entry.map_err(gateway_formal_backend_run_io_error)?;
        let logical_path = entry
            .path()
            .strip_prefix(output_root)
            .map_err(|error| GatewayFormalBackendRunOutputError::Io(error.to_string()))?
            .to_string_lossy()
            .replace('\\', "/");
        if !declared.remove(&logical_path) {
            return Err(GatewayFormalBackendRunOutputError::UndeclaredFile(
                logical_path,
            ));
        }
    }
    if let Some(missing) = declared.into_iter().next() {
        return Err(GatewayFormalBackendRunOutputError::Io(format!(
            "declared file missing: {missing}"
        )));
    }
    Ok(())
}

fn validate_gateway_formal_backend_run_output_root(
    output_root: &Path,
    protected_roots: &[PathBuf],
    overwrite: bool,
) -> Result<(), GatewayFormalBackendRunOutputError> {
    match validate_output_root(output_root, protected_roots, overwrite) {
        Ok(()) => Ok(()),
        Err(AdmissionJournalMaterializationError::EmptyOutputRoot) => {
            Err(GatewayFormalBackendRunOutputError::EmptyOutputRoot)
        }
        Err(AdmissionJournalMaterializationError::ProtectedOutputRoot) => {
            Err(GatewayFormalBackendRunOutputError::ProtectedOutputRoot)
        }
        Err(AdmissionJournalMaterializationError::OutputRootExistsWithoutOverwrite) => {
            Err(GatewayFormalBackendRunOutputError::OutputRootExistsWithoutOverwrite)
        }
        Err(AdmissionJournalMaterializationError::OutputRootIsFile) => {
            Err(GatewayFormalBackendRunOutputError::OutputRootIsFile)
        }
        Err(AdmissionJournalMaterializationError::OutputRootIsSymlink) => {
            Err(GatewayFormalBackendRunOutputError::OutputRootIsSymlink)
        }
        Err(AdmissionJournalMaterializationError::Io(error)) => {
            Err(GatewayFormalBackendRunOutputError::Io(error))
        }
        Err(other) => Err(GatewayFormalBackendRunOutputError::Io(format!("{other:?}"))),
    }
}

fn gateway_formal_backend_run_staging_root_for(
    output_root: &Path,
    bundle_id: &str,
) -> Result<PathBuf, GatewayFormalBackendRunOutputError> {
    let parent = output_root
        .parent()
        .ok_or(GatewayFormalBackendRunOutputError::EmptyOutputRoot)?;
    let name = output_root
        .file_name()
        .map(|value| value.to_string_lossy().into_owned())
        .ok_or(GatewayFormalBackendRunOutputError::EmptyOutputRoot)?;
    Ok(parent.join(format!(".{name}.{bundle_id}.staging")))
}

fn remove_gateway_formal_backend_run_dir_all_checked(
    path: &Path,
) -> Result<(), GatewayFormalBackendRunOutputError> {
    if !path.exists() {
        return Ok(());
    }
    if fs::symlink_metadata(path)
        .map_err(gateway_formal_backend_run_io_error)?
        .file_type()
        .is_symlink()
    {
        return Err(GatewayFormalBackendRunOutputError::OutputRootIsSymlink);
    }
    fs::remove_dir_all(path).map_err(gateway_formal_backend_run_io_error)
}

fn gateway_formal_backend_run_io_error(error: io::Error) -> GatewayFormalBackendRunOutputError {
    GatewayFormalBackendRunOutputError::Io(error.to_string())
}

fn gateway_formal_backend_run_serde_error(
    error: serde_json::Error,
) -> GatewayFormalBackendRunOutputError {
    GatewayFormalBackendRunOutputError::Serialization(error.to_string())
}

pub fn gateway_formal_backend_preflight_declared_files() -> Vec<String> {
    GATEWAY_FORMAL_BACKEND_PREFLIGHT_DECLARED_FILES
        .iter()
        .map(|value| (*value).to_owned())
        .collect()
}

#[allow(clippy::too_many_arguments)]
pub fn materialize_gateway_formal_backend_preflight_bundle(
    output_root: &Path,
    preflight_request: &GatewayFormalBackendExecutionPreflightRequest,
    preflight_report: &GatewayFormalBackendExecutionPreflightReport,
    adapter_request: &GatewayFormalBackendAdapterRequest,
    adapter_report: &GatewayFormalBackendAdapterReport,
    run_metadata: &GatewayFormalBackendRunArtifactMetadata,
    run_bundle_manifest: &GatewayFormalBackendRunOutputManifest,
    request: &GatewayFormalBackendPreflightOutputRequest,
) -> Result<GatewayFormalBackendPreflightOutputManifest, GatewayFormalBackendPreflightOutputError> {
    validate_gateway_formal_backend_preflight_output_request(
        output_root,
        preflight_request,
        preflight_report,
        adapter_request,
        adapter_report,
        run_metadata,
        run_bundle_manifest,
        request,
    )?;
    let staging_root =
        gateway_formal_backend_preflight_staging_root_for(output_root, &request.bundle_id)?;
    if staging_root.exists() {
        remove_gateway_formal_backend_preflight_dir_all_checked(&staging_root)?;
    }
    fs::create_dir_all(staging_root.join("gateway-formal-backend-preflight"))
        .map_err(gateway_formal_backend_preflight_io_error)?;

    let files = build_gateway_formal_backend_preflight_bundle_files(
        preflight_request,
        preflight_report,
        request,
    )?;
    for (logical_path, bytes) in &files {
        let target = staging_root.join(logical_path);
        if let Some(parent) = target.parent() {
            fs::create_dir_all(parent).map_err(gateway_formal_backend_preflight_io_error)?;
        }
        fs::write(&target, bytes).map_err(gateway_formal_backend_preflight_io_error)?;
        fs::write(
            sidecar_path(&target),
            hash_hex(hash_bytes(bytes)).into_bytes(),
        )
        .map_err(gateway_formal_backend_preflight_io_error)?;
    }

    if output_root.exists() {
        if !request.overwrite {
            remove_gateway_formal_backend_preflight_dir_all_checked(&staging_root)?;
            return Err(GatewayFormalBackendPreflightOutputError::OutputRootExistsWithoutOverwrite);
        }
        remove_gateway_formal_backend_preflight_dir_all_checked(output_root)?;
    }
    fs::rename(&staging_root, output_root).map_err(gateway_formal_backend_preflight_io_error)?;
    read_gateway_formal_backend_preflight_bundle(output_root)
}

pub fn read_gateway_formal_backend_preflight_bundle(
    output_root: &Path,
) -> Result<GatewayFormalBackendPreflightOutputManifest, GatewayFormalBackendPreflightOutputError> {
    let output_metadata =
        fs::symlink_metadata(output_root).map_err(gateway_formal_backend_preflight_io_error)?;
    if output_metadata.file_type().is_symlink() {
        return Err(GatewayFormalBackendPreflightOutputError::OutputRootIsSymlink);
    }
    if !output_metadata.is_dir() {
        return Err(GatewayFormalBackendPreflightOutputError::OutputRootIsFile);
    }
    let bundle_dir = output_root.join("gateway-formal-backend-preflight");
    let bundle_metadata =
        fs::symlink_metadata(&bundle_dir).map_err(gateway_formal_backend_preflight_io_error)?;
    if bundle_metadata.file_type().is_symlink() {
        return Err(
            GatewayFormalBackendPreflightOutputError::BundleFileIsSymlink(
                "gateway-formal-backend-preflight".to_owned(),
            ),
        );
    }
    if !bundle_metadata.is_dir() {
        return Err(
            GatewayFormalBackendPreflightOutputError::DeclaredFileTypeMismatch(
                "gateway-formal-backend-preflight".to_owned(),
            ),
        );
    }

    reject_undeclared_gateway_formal_backend_preflight_files(output_root)?;
    let mut file_bytes = BTreeMap::new();
    for logical_path in GATEWAY_FORMAL_BACKEND_PREFLIGHT_DECLARED_FILES {
        let path = output_root.join(logical_path);
        let metadata =
            fs::symlink_metadata(&path).map_err(gateway_formal_backend_preflight_io_error)?;
        if metadata.file_type().is_symlink() {
            return Err(
                GatewayFormalBackendPreflightOutputError::BundleFileIsSymlink(
                    (*logical_path).to_owned(),
                ),
            );
        }
        if !metadata.is_file() {
            return Err(
                GatewayFormalBackendPreflightOutputError::DeclaredFileTypeMismatch(
                    (*logical_path).to_owned(),
                ),
            );
        }
        let sidecar = sidecar_path(&path);
        let sidecar_metadata =
            fs::symlink_metadata(&sidecar).map_err(gateway_formal_backend_preflight_io_error)?;
        if sidecar_metadata.file_type().is_symlink() {
            return Err(
                GatewayFormalBackendPreflightOutputError::BundleFileIsSymlink(format!(
                    "{logical_path}.sha256"
                )),
            );
        }
        if !sidecar_metadata.is_file() {
            return Err(
                GatewayFormalBackendPreflightOutputError::DeclaredFileTypeMismatch(format!(
                    "{logical_path}.sha256"
                )),
            );
        }
        let bytes = fs::read(&path).map_err(gateway_formal_backend_preflight_io_error)?;
        let expected =
            fs::read_to_string(sidecar).map_err(gateway_formal_backend_preflight_io_error)?;
        if expected != hash_hex(hash_bytes(&bytes)) {
            return Err(GatewayFormalBackendPreflightOutputError::DigestMismatch(
                (*logical_path).to_owned(),
            ));
        }
        file_bytes.insert((*logical_path).to_owned(), bytes);
    }

    validate_gateway_formal_backend_preflight_bundle_semantics(&file_bytes)
}

#[allow(clippy::too_many_arguments)]
fn validate_gateway_formal_backend_preflight_output_request(
    output_root: &Path,
    preflight_request: &GatewayFormalBackendExecutionPreflightRequest,
    preflight_report: &GatewayFormalBackendExecutionPreflightReport,
    adapter_request: &GatewayFormalBackendAdapterRequest,
    adapter_report: &GatewayFormalBackendAdapterReport,
    run_metadata: &GatewayFormalBackendRunArtifactMetadata,
    run_bundle_manifest: &GatewayFormalBackendRunOutputManifest,
    request: &GatewayFormalBackendPreflightOutputRequest,
) -> Result<(), GatewayFormalBackendPreflightOutputError> {
    if request.bundle_id.trim().is_empty()
        || !is_safe_relative_path(&request.bundle_id)
        || request.bundle_id.contains(['/', '\\'])
    {
        return Err(GatewayFormalBackendPreflightOutputError::EmptyBundleId);
    }
    let validation = validate_gateway_formal_backend_execution_preflight_request(
        preflight_request,
        adapter_request,
        adapter_report,
        run_metadata,
        run_bundle_manifest,
    );
    if !validation.valid {
        return Err(GatewayFormalBackendPreflightOutputError::InvalidPreflight(
            validation.issues,
        ));
    }
    let expected_report = build_gateway_formal_backend_execution_preflight_report(
        preflight_request,
        adapter_request,
        adapter_report,
        run_metadata,
        run_bundle_manifest,
    );
    if preflight_report != &expected_report
        || preflight_report.readiness_status
            != GatewayFormalBackendPreflightReadinessStatus::ReadyCandidateOnly
        || !preflight_report.validation.valid
        || preflight_report.backend_executed
        || preflight_report.proof_artifact_created
        || preflight_report.checker_transcript_created
        || preflight_report.creates_accepted_evidence
        || preflight_report.creates_level2_evidence
        || preflight_report.populates_score_axes
        || preflight_report.grants_authority
    {
        return Err(GatewayFormalBackendPreflightOutputError::PreflightReportMismatch);
    }
    validate_gateway_formal_backend_preflight_output_root(
        output_root,
        &request.protected_roots,
        request.overwrite,
    )
}

fn build_gateway_formal_backend_preflight_bundle_files(
    preflight_request: &GatewayFormalBackendExecutionPreflightRequest,
    preflight_report: &GatewayFormalBackendExecutionPreflightReport,
    request: &GatewayFormalBackendPreflightOutputRequest,
) -> Result<BTreeMap<String, Vec<u8>>, GatewayFormalBackendPreflightOutputError> {
    let nonclaims = render_gateway_formal_backend_preflight_nonclaims(&preflight_report.nonclaims);
    let mut files = BTreeMap::from([
        (
            "gateway-formal-backend-preflight/preflight-request.json".to_owned(),
            serde_json::to_vec_pretty(preflight_request)
                .map_err(gateway_formal_backend_preflight_serde_error)?,
        ),
        (
            "gateway-formal-backend-preflight/preflight-report.json".to_owned(),
            serde_json::to_vec_pretty(preflight_report)
                .map_err(gateway_formal_backend_preflight_serde_error)?,
        ),
        (
            "gateway-formal-backend-preflight/command-descriptor.json".to_owned(),
            serde_json::to_vec_pretty(&preflight_request.command_descriptor)
                .map_err(gateway_formal_backend_preflight_serde_error)?,
        ),
        (
            "gateway-formal-backend-preflight/environment-descriptor.json".to_owned(),
            serde_json::to_vec_pretty(&preflight_request.environment_descriptor)
                .map_err(gateway_formal_backend_preflight_serde_error)?,
        ),
        (
            "gateway-formal-backend-preflight/artifact-root-descriptor.json".to_owned(),
            serde_json::to_vec_pretty(&preflight_request.artifact_root_descriptor)
                .map_err(gateway_formal_backend_preflight_serde_error)?,
        ),
        (
            "gateway-formal-backend-preflight/operator-acknowledgement.json".to_owned(),
            serde_json::to_vec_pretty(&preflight_request.operator_acknowledgement)
                .map_err(gateway_formal_backend_preflight_serde_error)?,
        ),
        (
            "gateway-formal-backend-preflight/redaction-policy.json".to_owned(),
            serde_json::to_vec_pretty(&preflight_request.redaction_policy)
                .map_err(gateway_formal_backend_preflight_serde_error)?,
        ),
        (
            "gateway-formal-backend-preflight/nonclaims.md".to_owned(),
            nonclaims.into_bytes(),
        ),
    ]);
    let manifest = gateway_formal_backend_preflight_output_manifest_for_files(
        preflight_request,
        preflight_report,
        request,
        &files,
    );
    files.insert(
        "gateway-formal-backend-preflight/manifest.json".to_owned(),
        serde_json::to_vec_pretty(&manifest)
            .map_err(gateway_formal_backend_preflight_serde_error)?,
    );
    Ok(files)
}

fn gateway_formal_backend_preflight_output_manifest_for_files(
    preflight_request: &GatewayFormalBackendExecutionPreflightRequest,
    preflight_report: &GatewayFormalBackendExecutionPreflightReport,
    request: &GatewayFormalBackendPreflightOutputRequest,
    files: &BTreeMap<String, Vec<u8>>,
) -> GatewayFormalBackendPreflightOutputManifest {
    let mut declared_file_digests = BTreeMap::new();
    for (logical_path, bytes) in files {
        declared_file_digests.insert(logical_path.clone(), hash_bytes(bytes));
    }
    GatewayFormalBackendPreflightOutputManifest {
        schema_version: GATEWAY_FORMAL_BACKEND_PREFLIGHT_OUTPUT_SCHEMA_VERSION.to_owned(),
        bundle_id: request.bundle_id.clone(),
        state_slice: GATEWAY_FORMAL_BACKEND_PREFLIGHT_STATE_SLICE.to_owned(),
        created_at_unix: request.created_at_unix,
        preflight_request_digest: preflight_request.digest(),
        preflight_report_digest: preflight_report.digest(),
        input_backend_run_bundle_digest: preflight_report.input_bundle_digest,
        command_descriptor_digest: hash_bytes(
            files
                .get("gateway-formal-backend-preflight/command-descriptor.json")
                .map(Vec::as_slice)
                .unwrap_or_default(),
        ),
        environment_descriptor_digest: hash_bytes(
            files
                .get("gateway-formal-backend-preflight/environment-descriptor.json")
                .map(Vec::as_slice)
                .unwrap_or_default(),
        ),
        artifact_root_descriptor_digest: hash_bytes(
            files
                .get("gateway-formal-backend-preflight/artifact-root-descriptor.json")
                .map(Vec::as_slice)
                .unwrap_or_default(),
        ),
        operator_acknowledgement_digest: hash_bytes(
            files
                .get("gateway-formal-backend-preflight/operator-acknowledgement.json")
                .map(Vec::as_slice)
                .unwrap_or_default(),
        ),
        redaction_policy_digest: hash_bytes(
            files
                .get("gateway-formal-backend-preflight/redaction-policy.json")
                .map(Vec::as_slice)
                .unwrap_or_default(),
        ),
        nonclaims_digest: hash_bytes(
            files
                .get("gateway-formal-backend-preflight/nonclaims.md")
                .map(Vec::as_slice)
                .unwrap_or_default(),
        ),
        declared_files: gateway_formal_backend_preflight_declared_files(),
        declared_file_digests,
        claim_boundary: gateway_formal_backend_preflight_claim_boundary(),
        backend_executed: false,
        proof_artifact_created: false,
        checker_transcript_created: false,
        creates_accepted_evidence: false,
        creates_level2_evidence: false,
        populates_score_axes: false,
        grants_authority: false,
        nonclaims: preflight_report.nonclaims.clone(),
    }
}

fn validate_gateway_formal_backend_preflight_bundle_semantics(
    files: &BTreeMap<String, Vec<u8>>,
) -> Result<GatewayFormalBackendPreflightOutputManifest, GatewayFormalBackendPreflightOutputError> {
    let manifest: GatewayFormalBackendPreflightOutputManifest =
        parse_gateway_formal_backend_preflight_declared_json(
            files,
            "gateway-formal-backend-preflight/manifest.json",
        )?;
    let preflight_request: GatewayFormalBackendExecutionPreflightRequest =
        parse_gateway_formal_backend_preflight_declared_json(
            files,
            "gateway-formal-backend-preflight/preflight-request.json",
        )?;
    let preflight_report: GatewayFormalBackendExecutionPreflightReport =
        parse_gateway_formal_backend_preflight_declared_json(
            files,
            "gateway-formal-backend-preflight/preflight-report.json",
        )?;
    let command_descriptor: GatewayFormalBackendPreflightCommandDescriptor =
        parse_gateway_formal_backend_preflight_declared_json(
            files,
            "gateway-formal-backend-preflight/command-descriptor.json",
        )?;
    let environment_descriptor: GatewayFormalBackendPreflightEnvironmentDescriptor =
        parse_gateway_formal_backend_preflight_declared_json(
            files,
            "gateway-formal-backend-preflight/environment-descriptor.json",
        )?;
    let artifact_root_descriptor: GatewayFormalBackendPreflightArtifactRootDescriptor =
        parse_gateway_formal_backend_preflight_declared_json(
            files,
            "gateway-formal-backend-preflight/artifact-root-descriptor.json",
        )?;
    let operator_acknowledgement: GatewayFormalBackendPreflightOperatorAcknowledgement =
        parse_gateway_formal_backend_preflight_declared_json(
            files,
            "gateway-formal-backend-preflight/operator-acknowledgement.json",
        )?;
    let redaction_policy: GatewayFormalBackendPreflightRedactionPolicy =
        parse_gateway_formal_backend_preflight_declared_json(
            files,
            "gateway-formal-backend-preflight/redaction-policy.json",
        )?;

    if preflight_request.command_descriptor != command_descriptor
        || preflight_request.environment_descriptor != environment_descriptor
        || preflight_request.artifact_root_descriptor != artifact_root_descriptor
        || preflight_request.operator_acknowledgement != operator_acknowledgement
    {
        return Err(GatewayFormalBackendPreflightOutputError::ManifestSemanticMismatch);
    }
    if preflight_request.redaction_policy != redaction_policy
        || redaction_policy != gateway_formal_backend_preflight_redaction_policy()
    {
        return Err(GatewayFormalBackendPreflightOutputError::RedactionPolicyMismatch);
    }
    if preflight_report.request_digest != preflight_request.digest()
        || preflight_report.input_bundle_digest != preflight_request.run_bundle_manifest_digest
        || preflight_report.command_descriptor_digest
            != preflight_request.command_descriptor.digest()
        || preflight_report.environment_descriptor_digest
            != preflight_request.environment_descriptor.digest()
        || preflight_report.artifact_root_descriptor_digest
            != preflight_request.artifact_root_descriptor.digest()
        || preflight_report.operator_acknowledgement_digest
            != preflight_request.operator_acknowledgement.digest()
        || preflight_report.redaction_policy_digest != preflight_request.redaction_policy.digest()
        || preflight_report.readiness_status
            != GatewayFormalBackendPreflightReadinessStatus::ReadyCandidateOnly
        || !preflight_report.validation.valid
        || preflight_report.claim_boundary != gateway_formal_backend_preflight_claim_boundary()
        || preflight_report.backend_executed
        || preflight_report.proof_artifact_created
        || preflight_report.checker_transcript_created
        || preflight_report.creates_accepted_evidence
        || preflight_report.creates_level2_evidence
        || preflight_report.populates_score_axes
        || preflight_report.grants_authority
    {
        return Err(GatewayFormalBackendPreflightOutputError::PreflightReportMismatch);
    }
    if declared_gateway_formal_backend_preflight_bytes(
        files,
        "gateway-formal-backend-preflight/nonclaims.md",
    )? != render_gateway_formal_backend_preflight_nonclaims(&preflight_report.nonclaims)
        .as_bytes()
    {
        return Err(GatewayFormalBackendPreflightOutputError::NonclaimMismatch);
    }

    let expected_request = GatewayFormalBackendPreflightOutputRequest {
        bundle_id: manifest.bundle_id.clone(),
        created_at_unix: manifest.created_at_unix,
        overwrite: false,
        protected_roots: Vec::new(),
    };
    validate_gateway_formal_backend_preflight_manifest_semantics(
        &manifest,
        &preflight_request,
        &preflight_report,
        &expected_request,
        files,
    )?;
    Ok(manifest)
}

fn validate_gateway_formal_backend_preflight_manifest_semantics(
    manifest: &GatewayFormalBackendPreflightOutputManifest,
    preflight_request: &GatewayFormalBackendExecutionPreflightRequest,
    preflight_report: &GatewayFormalBackendExecutionPreflightReport,
    request: &GatewayFormalBackendPreflightOutputRequest,
    files: &BTreeMap<String, Vec<u8>>,
) -> Result<(), GatewayFormalBackendPreflightOutputError> {
    let expected_digest_paths: BTreeSet<String> = GATEWAY_FORMAL_BACKEND_PREFLIGHT_DECLARED_FILES
        .iter()
        .filter(|path| **path != "gateway-formal-backend-preflight/manifest.json")
        .map(|path| (*path).to_owned())
        .collect();
    let actual_digest_paths: BTreeSet<String> =
        manifest.declared_file_digests.keys().cloned().collect();
    if manifest.schema_version != GATEWAY_FORMAL_BACKEND_PREFLIGHT_OUTPUT_SCHEMA_VERSION
        || manifest.bundle_id != request.bundle_id
        || manifest.state_slice != GATEWAY_FORMAL_BACKEND_PREFLIGHT_STATE_SLICE
        || manifest.created_at_unix != request.created_at_unix
        || manifest.preflight_request_digest != preflight_request.digest()
        || manifest.preflight_report_digest != preflight_report.digest()
        || manifest.input_backend_run_bundle_digest != preflight_report.input_bundle_digest
        || manifest.command_descriptor_digest
            != hash_bytes(declared_gateway_formal_backend_preflight_bytes(
                files,
                "gateway-formal-backend-preflight/command-descriptor.json",
            )?)
        || manifest.environment_descriptor_digest
            != hash_bytes(declared_gateway_formal_backend_preflight_bytes(
                files,
                "gateway-formal-backend-preflight/environment-descriptor.json",
            )?)
        || manifest.artifact_root_descriptor_digest
            != hash_bytes(declared_gateway_formal_backend_preflight_bytes(
                files,
                "gateway-formal-backend-preflight/artifact-root-descriptor.json",
            )?)
        || manifest.operator_acknowledgement_digest
            != hash_bytes(declared_gateway_formal_backend_preflight_bytes(
                files,
                "gateway-formal-backend-preflight/operator-acknowledgement.json",
            )?)
        || manifest.redaction_policy_digest
            != hash_bytes(declared_gateway_formal_backend_preflight_bytes(
                files,
                "gateway-formal-backend-preflight/redaction-policy.json",
            )?)
        || manifest.nonclaims_digest
            != hash_bytes(declared_gateway_formal_backend_preflight_bytes(
                files,
                "gateway-formal-backend-preflight/nonclaims.md",
            )?)
        || manifest.declared_files != gateway_formal_backend_preflight_declared_files()
        || actual_digest_paths != expected_digest_paths
        || manifest
            .declared_file_digests
            .values()
            .any(|digest| *digest == Hash([0; 32]))
        || manifest.claim_boundary != gateway_formal_backend_preflight_claim_boundary()
        || manifest.backend_executed
        || manifest.proof_artifact_created
        || manifest.checker_transcript_created
        || manifest.creates_accepted_evidence
        || manifest.creates_level2_evidence
        || manifest.populates_score_axes
        || manifest.grants_authority
        || manifest.nonclaims != preflight_report.nonclaims
    {
        return Err(GatewayFormalBackendPreflightOutputError::ManifestSemanticMismatch);
    }
    for (logical_path, expected_digest) in &manifest.declared_file_digests {
        if hash_bytes(declared_gateway_formal_backend_preflight_bytes(
            files,
            logical_path,
        )?) != *expected_digest
        {
            return Err(GatewayFormalBackendPreflightOutputError::DigestMismatch(
                logical_path.clone(),
            ));
        }
    }
    Ok(())
}

fn render_gateway_formal_backend_preflight_nonclaims(
    nonclaims: &BTreeSet<NonClaimLabel>,
) -> String {
    let mut out = String::from("# Gateway Formal Backend Preflight Nonclaims\n\n");
    for nonclaim in nonclaims {
        out.push_str("- ");
        out.push_str(&nonclaim.0);
        out.push('\n');
    }
    out
}

fn declared_gateway_formal_backend_preflight_bytes<'a>(
    files: &'a BTreeMap<String, Vec<u8>>,
    logical_path: &str,
) -> Result<&'a [u8], GatewayFormalBackendPreflightOutputError> {
    files.get(logical_path).map(Vec::as_slice).ok_or_else(|| {
        GatewayFormalBackendPreflightOutputError::Io(format!(
            "declared file missing: {logical_path}"
        ))
    })
}

fn parse_gateway_formal_backend_preflight_declared_json<T: for<'de> Deserialize<'de>>(
    files: &BTreeMap<String, Vec<u8>>,
    logical_path: &str,
) -> Result<T, GatewayFormalBackendPreflightOutputError> {
    let bytes = declared_gateway_formal_backend_preflight_bytes(files, logical_path)?;
    let text = std::str::from_utf8(bytes).map_err(|_| {
        GatewayFormalBackendPreflightOutputError::MalformedDeclaredFile(logical_path.to_owned())
    })?;
    serde_json::from_str(text).map_err(|_| {
        GatewayFormalBackendPreflightOutputError::MalformedDeclaredFile(logical_path.to_owned())
    })
}

fn reject_undeclared_gateway_formal_backend_preflight_files(
    output_root: &Path,
) -> Result<(), GatewayFormalBackendPreflightOutputError> {
    let mut declared: BTreeSet<String> = GATEWAY_FORMAL_BACKEND_PREFLIGHT_DECLARED_FILES
        .iter()
        .chain(GATEWAY_FORMAL_BACKEND_PREFLIGHT_DECLARED_SIDECARS.iter())
        .map(|value| (*value).to_owned())
        .collect();
    let bundle_dir = output_root.join("gateway-formal-backend-preflight");
    for entry in fs::read_dir(&bundle_dir).map_err(gateway_formal_backend_preflight_io_error)? {
        let entry = entry.map_err(gateway_formal_backend_preflight_io_error)?;
        let logical_path = entry
            .path()
            .strip_prefix(output_root)
            .map_err(|error| GatewayFormalBackendPreflightOutputError::Io(error.to_string()))?
            .to_string_lossy()
            .replace('\\', "/");
        if !declared.remove(&logical_path) {
            return Err(GatewayFormalBackendPreflightOutputError::UndeclaredFile(
                logical_path,
            ));
        }
    }
    if let Some(missing) = declared.into_iter().next() {
        return Err(GatewayFormalBackendPreflightOutputError::Io(format!(
            "declared file missing: {missing}"
        )));
    }
    Ok(())
}

fn validate_gateway_formal_backend_preflight_output_root(
    output_root: &Path,
    protected_roots: &[PathBuf],
    overwrite: bool,
) -> Result<(), GatewayFormalBackendPreflightOutputError> {
    match validate_output_root(output_root, protected_roots, overwrite) {
        Ok(()) => Ok(()),
        Err(AdmissionJournalMaterializationError::EmptyOutputRoot) => {
            Err(GatewayFormalBackendPreflightOutputError::EmptyOutputRoot)
        }
        Err(AdmissionJournalMaterializationError::ProtectedOutputRoot) => {
            Err(GatewayFormalBackendPreflightOutputError::ProtectedOutputRoot)
        }
        Err(AdmissionJournalMaterializationError::OutputRootExistsWithoutOverwrite) => {
            Err(GatewayFormalBackendPreflightOutputError::OutputRootExistsWithoutOverwrite)
        }
        Err(AdmissionJournalMaterializationError::OutputRootIsFile) => {
            Err(GatewayFormalBackendPreflightOutputError::OutputRootIsFile)
        }
        Err(AdmissionJournalMaterializationError::OutputRootIsSymlink) => {
            Err(GatewayFormalBackendPreflightOutputError::OutputRootIsSymlink)
        }
        Err(AdmissionJournalMaterializationError::Io(error)) => {
            Err(GatewayFormalBackendPreflightOutputError::Io(error))
        }
        Err(other) => Err(GatewayFormalBackendPreflightOutputError::Io(format!(
            "{other:?}"
        ))),
    }
}

fn gateway_formal_backend_preflight_staging_root_for(
    output_root: &Path,
    bundle_id: &str,
) -> Result<PathBuf, GatewayFormalBackendPreflightOutputError> {
    let parent = output_root
        .parent()
        .ok_or(GatewayFormalBackendPreflightOutputError::EmptyOutputRoot)?;
    let name = output_root
        .file_name()
        .map(|value| value.to_string_lossy().into_owned())
        .ok_or(GatewayFormalBackendPreflightOutputError::EmptyOutputRoot)?;
    Ok(parent.join(format!(".{name}.{bundle_id}.staging")))
}

fn remove_gateway_formal_backend_preflight_dir_all_checked(
    path: &Path,
) -> Result<(), GatewayFormalBackendPreflightOutputError> {
    if !path.exists() {
        return Ok(());
    }
    if fs::symlink_metadata(path)
        .map_err(gateway_formal_backend_preflight_io_error)?
        .file_type()
        .is_symlink()
    {
        return Err(GatewayFormalBackendPreflightOutputError::OutputRootIsSymlink);
    }
    fs::remove_dir_all(path).map_err(gateway_formal_backend_preflight_io_error)
}

fn gateway_formal_backend_preflight_io_error(
    error: io::Error,
) -> GatewayFormalBackendPreflightOutputError {
    GatewayFormalBackendPreflightOutputError::Io(error.to_string())
}

fn gateway_formal_backend_preflight_serde_error(
    error: serde_json::Error,
) -> GatewayFormalBackendPreflightOutputError {
    GatewayFormalBackendPreflightOutputError::Serialization(error.to_string())
}

pub fn gateway_formal_backend_transcript_required_nonclaims() -> BTreeSet<NonClaimLabel> {
    let mut nonclaims = gateway_formal_backend_preflight_required_nonclaims();
    nonclaims.extend([
        NonClaimLabel("transcript metadata only".to_owned()),
        NonClaimLabel("not executed transcript".to_owned()),
        NonClaimLabel("no stdout summary retained".to_owned()),
        NonClaimLabel("no stderr summary retained".to_owned()),
        NonClaimLabel("no proof artifact reference".to_owned()),
        NonClaimLabel("no checker transcript reference".to_owned()),
        NonClaimLabel("checker success is not semantic correctness".to_owned()),
    ]);
    nonclaims
}

