pub fn build_gateway_formal_backend_execution_transcript_metadata(
    transcript_id: impl Into<String>,
    preflight_request: &GatewayFormalBackendExecutionPreflightRequest,
    preflight_report: &GatewayFormalBackendExecutionPreflightReport,
    preflight_manifest: &GatewayFormalBackendPreflightOutputManifest,
) -> GatewayFormalBackendExecutionTranscriptMetadata {
    GatewayFormalBackendExecutionTranscriptMetadata {
        schema_version: GATEWAY_FORMAL_BACKEND_TRANSCRIPT_SCHEMA_VERSION.to_owned(),
        transcript_id: transcript_id.into(),
        state_slice: GATEWAY_FORMAL_BACKEND_TRANSCRIPT_STATE_SLICE.to_owned(),
        preflight_bundle_manifest_digest: preflight_manifest.digest(),
        preflight_request_digest: preflight_request.digest(),
        preflight_report_digest: preflight_report.digest(),
        command_descriptor_digest: preflight_request.command_descriptor.digest(),
        backend_kind: preflight_request.command_descriptor.backend_kind.clone(),
        tool_name: preflight_request.command_descriptor.tool_name.clone(),
        tool_version: preflight_request.command_descriptor.tool_version.clone(),
        toolchain_lock_digest: preflight_request.command_descriptor.toolchain_lock_digest,
        execution_status: GatewayFormalBackendTranscriptExecutionStatus::NotExecuted,
        started_at_unix: None,
        finished_at_unix: None,
        exit_status: GatewayFormalBackendRunExitStatus::NotRun,
        checker_status: GatewayFormalBackendTranscriptCheckerStatus::NotChecked,
        redacted_stdout_summary_digest: None,
        redacted_stderr_summary_digest: None,
        proof_artifact_ref: None,
        checker_transcript_ref: None,
        proof_obligations_requested: BTreeSet::new(),
        proof_obligations_discharged: BTreeSet::new(),
        proof_obligations_not_discharged: BTreeSet::new(),
        verifier_trust_roots: BTreeSet::new(),
        redaction_report: gateway_formal_backend_transcript_redaction_report(),
        claim_boundary: gateway_formal_backend_transcript_claim_boundary(),
        backend_executed: false,
        proof_artifact_created: false,
        checker_transcript_created: false,
        checker_succeeded: false,
        creates_accepted_evidence: false,
        creates_level2_evidence: false,
        populates_score_axes: false,
        grants_authority: false,
        semantic_correctness_claimed: false,
        production_readiness_claimed: false,
        sota_claimed: false,
        full_security_claimed: false,
        claim_text: Vec::new(),
        nonclaims: gateway_formal_backend_transcript_required_nonclaims(),
    }
}

pub fn validate_gateway_formal_backend_execution_transcript_metadata(
    metadata: &GatewayFormalBackendExecutionTranscriptMetadata,
    preflight_request: &GatewayFormalBackendExecutionPreflightRequest,
    preflight_report: &GatewayFormalBackendExecutionPreflightReport,
    preflight_manifest: &GatewayFormalBackendPreflightOutputManifest,
) -> GatewayFormalBackendTranscriptValidation {
    let mut issues = Vec::new();

    if metadata.schema_version != GATEWAY_FORMAL_BACKEND_TRANSCRIPT_SCHEMA_VERSION {
        issues.push(GatewayFormalBackendTranscriptIssue::InvalidSchemaVersion);
    }
    if metadata.transcript_id.trim().is_empty()
        || !is_safe_relative_path(&metadata.transcript_id)
        || metadata.transcript_id.contains(['/', '\\'])
    {
        issues.push(GatewayFormalBackendTranscriptIssue::InvalidTranscriptId);
    }
    if metadata.state_slice != GATEWAY_FORMAL_BACKEND_TRANSCRIPT_STATE_SLICE {
        issues.push(GatewayFormalBackendTranscriptIssue::StateSliceMismatch);
    }
    if preflight_manifest.backend_executed
        || preflight_manifest.proof_artifact_created
        || preflight_manifest.checker_transcript_created
        || preflight_manifest.creates_accepted_evidence
        || preflight_manifest.creates_level2_evidence
        || preflight_manifest.populates_score_axes
        || preflight_manifest.grants_authority
        || preflight_manifest.claim_boundary != gateway_formal_backend_preflight_claim_boundary()
    {
        issues.push(GatewayFormalBackendTranscriptIssue::PreflightManifestEscalated);
    }
    if metadata.preflight_bundle_manifest_digest != preflight_manifest.digest() {
        issues.push(GatewayFormalBackendTranscriptIssue::PreflightManifestDigestMismatch);
    }
    if metadata.preflight_request_digest != preflight_request.digest()
        || preflight_manifest.preflight_request_digest != preflight_request.digest()
    {
        issues.push(GatewayFormalBackendTranscriptIssue::PreflightRequestDigestMismatch);
    }
    if metadata.preflight_report_digest != preflight_report.digest()
        || preflight_manifest.preflight_report_digest != preflight_report.digest()
    {
        issues.push(GatewayFormalBackendTranscriptIssue::PreflightReportDigestMismatch);
    }
    if metadata.command_descriptor_digest != preflight_request.command_descriptor.digest()
        || preflight_report.command_descriptor_digest
            != preflight_request.command_descriptor.digest()
        || preflight_manifest.command_descriptor_digest == Hash([0; 32])
    {
        issues.push(GatewayFormalBackendTranscriptIssue::CommandDescriptorDigestMismatch);
    }
    if metadata.backend_kind != preflight_request.command_descriptor.backend_kind {
        issues.push(GatewayFormalBackendTranscriptIssue::BackendKindMismatch);
    }
    if metadata.tool_name != preflight_request.command_descriptor.tool_name {
        issues.push(GatewayFormalBackendTranscriptIssue::ToolNameMismatch);
    }
    if metadata.tool_version != preflight_request.command_descriptor.tool_version {
        issues.push(GatewayFormalBackendTranscriptIssue::ToolVersionMismatch);
    }
    if metadata.toolchain_lock_digest != preflight_request.command_descriptor.toolchain_lock_digest
        || metadata.toolchain_lock_digest == Hash([0; 32])
    {
        issues.push(GatewayFormalBackendTranscriptIssue::ToolchainLockDigestMismatch);
    }
    if metadata.execution_status != GatewayFormalBackendTranscriptExecutionStatus::NotExecuted {
        issues.push(GatewayFormalBackendTranscriptIssue::ExecutionStatusEscalated);
    }
    if metadata.started_at_unix.is_some() || metadata.finished_at_unix.is_some() {
        issues.push(GatewayFormalBackendTranscriptIssue::TimestampSubmitted);
    }
    if metadata.exit_status != GatewayFormalBackendRunExitStatus::NotRun {
        issues.push(GatewayFormalBackendTranscriptIssue::ExitStatusEscalated);
    }
    if metadata.checker_status != GatewayFormalBackendTranscriptCheckerStatus::NotChecked {
        issues.push(GatewayFormalBackendTranscriptIssue::CheckerStatusEscalated);
    }
    if metadata.redacted_stdout_summary_digest.is_some() {
        issues.push(GatewayFormalBackendTranscriptIssue::StdoutSummarySubmitted);
    }
    if metadata.redacted_stderr_summary_digest.is_some() {
        issues.push(GatewayFormalBackendTranscriptIssue::StderrSummarySubmitted);
    }
    if let Some(reference) = &metadata.proof_artifact_ref {
        validate_gateway_formal_backend_transcript_reference(reference, &mut issues);
        issues.push(GatewayFormalBackendTranscriptIssue::ProofArtifactReferenceSubmitted);
    }
    if let Some(reference) = &metadata.checker_transcript_ref {
        validate_gateway_formal_backend_transcript_reference(reference, &mut issues);
        issues.push(GatewayFormalBackendTranscriptIssue::CheckerTranscriptReferenceSubmitted);
    }
    if !metadata.proof_obligations_requested.is_empty() {
        issues.push(GatewayFormalBackendTranscriptIssue::ProofObligationsRequestedMismatch);
    }
    if !metadata.proof_obligations_discharged.is_empty() {
        issues.push(GatewayFormalBackendTranscriptIssue::ProofObligationsDischargedBeforeExecution);
    }
    if !metadata.proof_obligations_not_discharged.is_empty() {
        issues.push(
            GatewayFormalBackendTranscriptIssue::ProofObligationsNotDischargedBeforeExecution,
        );
    }
    if !metadata.verifier_trust_roots.is_empty() {
        issues.push(GatewayFormalBackendTranscriptIssue::VerifierTrustRootSubmitted);
    }
    if transcript_redaction_retains_forbidden_material(&metadata.redaction_report) {
        issues.push(GatewayFormalBackendTranscriptIssue::RedactionReportRetainsForbiddenMaterial);
    }
    if metadata.claim_boundary != gateway_formal_backend_transcript_claim_boundary() {
        issues.push(GatewayFormalBackendTranscriptIssue::ClaimBoundaryMismatch);
    }
    if metadata.backend_executed {
        issues.push(GatewayFormalBackendTranscriptIssue::BackendExecuted);
    }
    if metadata.proof_artifact_created {
        issues.push(GatewayFormalBackendTranscriptIssue::ProofArtifactCreated);
    }
    if metadata.checker_transcript_created {
        issues.push(GatewayFormalBackendTranscriptIssue::CheckerTranscriptCreated);
    }
    if metadata.checker_succeeded {
        issues.push(GatewayFormalBackendTranscriptIssue::CheckerSucceeded);
    }
    if metadata.creates_accepted_evidence {
        issues.push(GatewayFormalBackendTranscriptIssue::AcceptedEvidenceCreated);
    }
    if metadata.creates_level2_evidence {
        issues.push(GatewayFormalBackendTranscriptIssue::Level2EvidenceCreated);
    }
    if metadata.populates_score_axes {
        issues.push(GatewayFormalBackendTranscriptIssue::ScoreAxesPopulated);
    }
    if metadata.grants_authority {
        issues.push(GatewayFormalBackendTranscriptIssue::AuthorityGranted);
    }
    if metadata.semantic_correctness_claimed {
        issues.push(GatewayFormalBackendTranscriptIssue::SemanticCorrectnessClaimed);
    }
    if metadata.production_readiness_claimed {
        issues.push(GatewayFormalBackendTranscriptIssue::ProductionReadinessClaimed);
    }
    if metadata.sota_claimed {
        issues.push(GatewayFormalBackendTranscriptIssue::SotaClaimed);
    }
    if metadata.full_security_claimed {
        issues.push(GatewayFormalBackendTranscriptIssue::FullSecurityClaimed);
    }
    for forbidden in gateway_formal_evidence_forbidden_claim_fragments() {
        if metadata
            .claim_text
            .iter()
            .any(|text| text.to_ascii_lowercase().contains(forbidden))
        {
            issues.push(GatewayFormalBackendTranscriptIssue::ForbiddenClaimText(
                (*forbidden).to_owned(),
            ));
        }
    }
    for required in gateway_formal_backend_transcript_required_nonclaims() {
        if !metadata.nonclaims.contains(&required) {
            issues.push(GatewayFormalBackendTranscriptIssue::MissingRequiredNonclaim(required.0));
        }
    }

    GatewayFormalBackendTranscriptValidation {
        valid: issues.is_empty(),
        issues,
    }
}

fn validate_gateway_formal_backend_transcript_reference(
    reference: &GatewayFormalBackendTranscriptReference,
    issues: &mut Vec<GatewayFormalBackendTranscriptIssue>,
) {
    if !is_safe_relative_path(&reference.logical_path)
        || path_label_is_protected(&reference.logical_path)
        || !reference
            .logical_path
            .starts_with("gateway-formal-backend-transcript/")
    {
        issues.push(
            GatewayFormalBackendTranscriptIssue::InvalidTranscriptReference(
                reference.logical_path.clone(),
            ),
        );
    }
    if reference.digest == Hash([0; 32]) || !reference.redacted {
        issues.push(
            GatewayFormalBackendTranscriptIssue::TranscriptReferenceMissingDigest(
                reference.logical_path.clone(),
            ),
        );
    }
    if reference.retains_raw_content {
        issues.push(
            GatewayFormalBackendTranscriptIssue::TranscriptReferenceRetainsRawContent(
                reference.logical_path.clone(),
            ),
        );
    }
}

fn transcript_redaction_retains_forbidden_material(
    redaction_report: &GatewayFormalBackendTranscriptRedactionReport,
) -> bool {
    redaction_report.retains_credentials_or_secrets
        || redaction_report.retains_raw_prover_logs
        || redaction_report.retains_raw_checker_logs
        || redaction_report.retains_raw_solver_traces
        || redaction_report.retains_proof_assistant_cache
        || redaction_report.retains_accepted_evidence_ledger_json
        || redaction_report.retains_benchmark_outputs
        || redaction_report.retains_external_repo_source
}

pub fn gateway_formal_backend_transcript_output_declared_files() -> Vec<String> {
    GATEWAY_FORMAL_BACKEND_TRANSCRIPT_DECLARED_FILES
        .iter()
        .map(|value| (*value).to_owned())
        .collect()
}

pub fn gateway_formal_backend_transcript_output_claim_boundary() -> String {
    GATEWAY_FORMAL_BACKEND_TRANSCRIPT_OUTPUT_CLAIM_BOUNDARY.to_owned()
}

pub fn materialize_gateway_formal_backend_transcript_output_bundle(
    output_root: &Path,
    metadata: &GatewayFormalBackendExecutionTranscriptMetadata,
    preflight_request: &GatewayFormalBackendExecutionPreflightRequest,
    preflight_report: &GatewayFormalBackendExecutionPreflightReport,
    preflight_manifest: &GatewayFormalBackendPreflightOutputManifest,
    request: &GatewayFormalBackendTranscriptOutputRequest,
) -> Result<GatewayFormalBackendTranscriptOutputManifest, GatewayFormalBackendTranscriptOutputError>
{
    validate_gateway_formal_backend_transcript_output_request(
        output_root,
        metadata,
        preflight_request,
        preflight_report,
        preflight_manifest,
        request,
    )?;
    let staging_root =
        gateway_formal_backend_transcript_staging_root_for(output_root, &request.bundle_id)?;
    if staging_root.exists() {
        remove_gateway_formal_backend_transcript_dir_all_checked(&staging_root)?;
    }
    fs::create_dir_all(staging_root.join("gateway-formal-backend-transcript"))
        .map_err(gateway_formal_backend_transcript_io_error)?;

    let files = build_gateway_formal_backend_transcript_bundle_files(metadata, request)?;
    for (logical_path, bytes) in &files {
        let target = staging_root.join(logical_path);
        if let Some(parent) = target.parent() {
            fs::create_dir_all(parent).map_err(gateway_formal_backend_transcript_io_error)?;
        }
        fs::write(&target, bytes).map_err(gateway_formal_backend_transcript_io_error)?;
        fs::write(
            sidecar_path(&target),
            hash_hex(hash_bytes(bytes)).into_bytes(),
        )
        .map_err(gateway_formal_backend_transcript_io_error)?;
    }

    if output_root.exists() {
        if !request.overwrite {
            remove_gateway_formal_backend_transcript_dir_all_checked(&staging_root)?;
            return Err(
                GatewayFormalBackendTranscriptOutputError::OutputRootExistsWithoutOverwrite,
            );
        }
        remove_gateway_formal_backend_transcript_dir_all_checked(output_root)?;
    }
    fs::rename(&staging_root, output_root).map_err(gateway_formal_backend_transcript_io_error)?;
    read_gateway_formal_backend_transcript_output_bundle(output_root)
}

pub fn read_gateway_formal_backend_transcript_output_bundle(
    output_root: &Path,
) -> Result<GatewayFormalBackendTranscriptOutputManifest, GatewayFormalBackendTranscriptOutputError>
{
    let output_metadata =
        fs::symlink_metadata(output_root).map_err(gateway_formal_backend_transcript_io_error)?;
    if output_metadata.file_type().is_symlink() {
        return Err(GatewayFormalBackendTranscriptOutputError::OutputRootIsSymlink);
    }
    if !output_metadata.is_dir() {
        return Err(GatewayFormalBackendTranscriptOutputError::OutputRootIsFile);
    }
    let bundle_dir = output_root.join("gateway-formal-backend-transcript");
    let bundle_metadata =
        fs::symlink_metadata(&bundle_dir).map_err(gateway_formal_backend_transcript_io_error)?;
    if bundle_metadata.file_type().is_symlink() {
        return Err(
            GatewayFormalBackendTranscriptOutputError::BundleFileIsSymlink(
                "gateway-formal-backend-transcript".to_owned(),
            ),
        );
    }
    if !bundle_metadata.is_dir() {
        return Err(
            GatewayFormalBackendTranscriptOutputError::DeclaredFileTypeMismatch(
                "gateway-formal-backend-transcript".to_owned(),
            ),
        );
    }

    reject_undeclared_gateway_formal_backend_transcript_files(output_root)?;
    let mut file_bytes = BTreeMap::new();
    for logical_path in GATEWAY_FORMAL_BACKEND_TRANSCRIPT_DECLARED_FILES {
        let path = output_root.join(logical_path);
        let metadata =
            fs::symlink_metadata(&path).map_err(gateway_formal_backend_transcript_io_error)?;
        if metadata.file_type().is_symlink() {
            return Err(
                GatewayFormalBackendTranscriptOutputError::BundleFileIsSymlink(
                    (*logical_path).to_owned(),
                ),
            );
        }
        if !metadata.is_file() {
            return Err(
                GatewayFormalBackendTranscriptOutputError::DeclaredFileTypeMismatch(
                    (*logical_path).to_owned(),
                ),
            );
        }
        let sidecar = sidecar_path(&path);
        let sidecar_metadata =
            fs::symlink_metadata(&sidecar).map_err(gateway_formal_backend_transcript_io_error)?;
        if sidecar_metadata.file_type().is_symlink() {
            return Err(
                GatewayFormalBackendTranscriptOutputError::BundleFileIsSymlink(format!(
                    "{logical_path}.sha256"
                )),
            );
        }
        if !sidecar_metadata.is_file() {
            return Err(
                GatewayFormalBackendTranscriptOutputError::DeclaredFileTypeMismatch(format!(
                    "{logical_path}.sha256"
                )),
            );
        }
        let bytes = fs::read(&path).map_err(gateway_formal_backend_transcript_io_error)?;
        let expected =
            fs::read_to_string(sidecar).map_err(gateway_formal_backend_transcript_io_error)?;
        if expected != hash_hex(hash_bytes(&bytes)) {
            return Err(GatewayFormalBackendTranscriptOutputError::DigestMismatch(
                (*logical_path).to_owned(),
            ));
        }
        file_bytes.insert((*logical_path).to_owned(), bytes);
    }

    validate_gateway_formal_backend_transcript_bundle_semantics(&file_bytes)
}

fn validate_gateway_formal_backend_transcript_output_request(
    output_root: &Path,
    metadata: &GatewayFormalBackendExecutionTranscriptMetadata,
    preflight_request: &GatewayFormalBackendExecutionPreflightRequest,
    preflight_report: &GatewayFormalBackendExecutionPreflightReport,
    preflight_manifest: &GatewayFormalBackendPreflightOutputManifest,
    request: &GatewayFormalBackendTranscriptOutputRequest,
) -> Result<(), GatewayFormalBackendTranscriptOutputError> {
    if request.bundle_id.trim().is_empty()
        || !is_safe_relative_path(&request.bundle_id)
        || request.bundle_id.contains(['/', '\\'])
    {
        return Err(GatewayFormalBackendTranscriptOutputError::EmptyBundleId);
    }
    let validation = validate_gateway_formal_backend_execution_transcript_metadata(
        metadata,
        preflight_request,
        preflight_report,
        preflight_manifest,
    );
    if !validation.valid {
        return Err(
            GatewayFormalBackendTranscriptOutputError::InvalidTranscript(validation.issues),
        );
    }
    let expected_metadata = build_gateway_formal_backend_execution_transcript_metadata(
        metadata.transcript_id.clone(),
        preflight_request,
        preflight_report,
        preflight_manifest,
    );
    if metadata != &expected_metadata {
        return Err(GatewayFormalBackendTranscriptOutputError::TranscriptMetadataMismatch);
    }
    validate_gateway_formal_backend_transcript_output_root(
        output_root,
        &request.protected_roots,
        request.overwrite,
    )
}

fn build_gateway_formal_backend_transcript_bundle_files(
    metadata: &GatewayFormalBackendExecutionTranscriptMetadata,
    request: &GatewayFormalBackendTranscriptOutputRequest,
) -> Result<BTreeMap<String, Vec<u8>>, GatewayFormalBackendTranscriptOutputError> {
    let nonclaims = render_gateway_formal_backend_transcript_nonclaims(&metadata.nonclaims);
    let preflight_binding = gateway_formal_backend_transcript_preflight_binding(metadata);
    let toolchain_binding = gateway_formal_backend_transcript_toolchain_binding(metadata);
    let execution_status = gateway_formal_backend_transcript_execution_status(metadata);
    let checker_status = gateway_formal_backend_transcript_checker_status(metadata);
    let proof_obligations = gateway_formal_backend_transcript_proof_obligations(metadata);
    let mut files = BTreeMap::from([
        (
            "gateway-formal-backend-transcript/transcript-metadata.json".to_owned(),
            serde_json::to_vec_pretty(metadata)
                .map_err(gateway_formal_backend_transcript_serde_error)?,
        ),
        (
            "gateway-formal-backend-transcript/preflight-binding.json".to_owned(),
            serde_json::to_vec_pretty(&preflight_binding)
                .map_err(gateway_formal_backend_transcript_serde_error)?,
        ),
        (
            "gateway-formal-backend-transcript/toolchain-binding.json".to_owned(),
            serde_json::to_vec_pretty(&toolchain_binding)
                .map_err(gateway_formal_backend_transcript_serde_error)?,
        ),
        (
            "gateway-formal-backend-transcript/execution-status.json".to_owned(),
            serde_json::to_vec_pretty(&execution_status)
                .map_err(gateway_formal_backend_transcript_serde_error)?,
        ),
        (
            "gateway-formal-backend-transcript/checker-status.json".to_owned(),
            serde_json::to_vec_pretty(&checker_status)
                .map_err(gateway_formal_backend_transcript_serde_error)?,
        ),
        (
            "gateway-formal-backend-transcript/redaction-report.json".to_owned(),
            serde_json::to_vec_pretty(&metadata.redaction_report)
                .map_err(gateway_formal_backend_transcript_serde_error)?,
        ),
        (
            "gateway-formal-backend-transcript/proof-obligations.json".to_owned(),
            serde_json::to_vec_pretty(&proof_obligations)
                .map_err(gateway_formal_backend_transcript_serde_error)?,
        ),
        (
            "gateway-formal-backend-transcript/nonclaims.md".to_owned(),
            nonclaims.into_bytes(),
        ),
    ]);
    let manifest =
        gateway_formal_backend_transcript_output_manifest_for_files(metadata, request, &files);
    files.insert(
        "gateway-formal-backend-transcript/manifest.json".to_owned(),
        serde_json::to_vec_pretty(&manifest)
            .map_err(gateway_formal_backend_transcript_serde_error)?,
    );
    Ok(files)
}

fn gateway_formal_backend_transcript_output_manifest_for_files(
    metadata: &GatewayFormalBackendExecutionTranscriptMetadata,
    request: &GatewayFormalBackendTranscriptOutputRequest,
    files: &BTreeMap<String, Vec<u8>>,
) -> GatewayFormalBackendTranscriptOutputManifest {
    let mut declared_file_digests = BTreeMap::new();
    for (logical_path, bytes) in files {
        declared_file_digests.insert(logical_path.clone(), hash_bytes(bytes));
    }
    GatewayFormalBackendTranscriptOutputManifest {
        schema_version: GATEWAY_FORMAL_BACKEND_TRANSCRIPT_OUTPUT_SCHEMA_VERSION.to_owned(),
        bundle_id: request.bundle_id.clone(),
        state_slice: GATEWAY_FORMAL_BACKEND_TRANSCRIPT_OUTPUT_STATE_SLICE.to_owned(),
        created_at_unix: request.created_at_unix,
        transcript_metadata_digest: metadata.digest(),
        preflight_bundle_manifest_digest: metadata.preflight_bundle_manifest_digest,
        preflight_request_digest: metadata.preflight_request_digest,
        preflight_report_digest: metadata.preflight_report_digest,
        command_descriptor_digest: metadata.command_descriptor_digest,
        backend_kind: metadata.backend_kind.clone(),
        tool_name: metadata.tool_name.clone(),
        tool_version: metadata.tool_version.clone(),
        toolchain_lock_digest: metadata.toolchain_lock_digest,
        execution_status: metadata.execution_status.clone(),
        checker_status: metadata.checker_status.clone(),
        redaction_report_digest: hash_bytes(
            files
                .get("gateway-formal-backend-transcript/redaction-report.json")
                .map(Vec::as_slice)
                .unwrap_or_default(),
        ),
        proof_obligations_digest: hash_bytes(
            files
                .get("gateway-formal-backend-transcript/proof-obligations.json")
                .map(Vec::as_slice)
                .unwrap_or_default(),
        ),
        nonclaims_digest: hash_bytes(
            files
                .get("gateway-formal-backend-transcript/nonclaims.md")
                .map(Vec::as_slice)
                .unwrap_or_default(),
        ),
        declared_files: gateway_formal_backend_transcript_output_declared_files(),
        declared_file_digests,
        claim_boundary: gateway_formal_backend_transcript_output_claim_boundary(),
        backend_executed: false,
        proof_artifact_created: false,
        checker_transcript_created: false,
        checker_succeeded: false,
        creates_accepted_evidence: false,
        creates_level2_evidence: false,
        populates_score_axes: false,
        grants_authority: false,
        nonclaims: metadata.nonclaims.clone(),
    }
}

fn validate_gateway_formal_backend_transcript_bundle_semantics(
    files: &BTreeMap<String, Vec<u8>>,
) -> Result<GatewayFormalBackendTranscriptOutputManifest, GatewayFormalBackendTranscriptOutputError>
{
    let manifest: GatewayFormalBackendTranscriptOutputManifest =
        parse_gateway_formal_backend_transcript_declared_json(
            files,
            "gateway-formal-backend-transcript/manifest.json",
        )?;
    let metadata: GatewayFormalBackendExecutionTranscriptMetadata =
        parse_gateway_formal_backend_transcript_declared_json(
            files,
            "gateway-formal-backend-transcript/transcript-metadata.json",
        )?;
    let preflight_binding: GatewayFormalBackendTranscriptPreflightBinding =
        parse_gateway_formal_backend_transcript_declared_json(
            files,
            "gateway-formal-backend-transcript/preflight-binding.json",
        )?;
    let toolchain_binding: GatewayFormalBackendTranscriptToolchainBinding =
        parse_gateway_formal_backend_transcript_declared_json(
            files,
            "gateway-formal-backend-transcript/toolchain-binding.json",
        )?;
    let execution_status: GatewayFormalBackendTranscriptExecutionStatusRecord =
        parse_gateway_formal_backend_transcript_declared_json(
            files,
            "gateway-formal-backend-transcript/execution-status.json",
        )?;
    let checker_status: GatewayFormalBackendTranscriptCheckerStatusRecord =
        parse_gateway_formal_backend_transcript_declared_json(
            files,
            "gateway-formal-backend-transcript/checker-status.json",
        )?;
    let redaction_report: GatewayFormalBackendTranscriptRedactionReport =
        parse_gateway_formal_backend_transcript_declared_json(
            files,
            "gateway-formal-backend-transcript/redaction-report.json",
        )?;
    let proof_obligations: GatewayFormalBackendTranscriptProofObligationsRecord =
        parse_gateway_formal_backend_transcript_declared_json(
            files,
            "gateway-formal-backend-transcript/proof-obligations.json",
        )?;

    let metadata_validation = validate_gateway_formal_backend_transcript_metadata_shape(&metadata);
    if !metadata_validation.valid {
        return Err(
            GatewayFormalBackendTranscriptOutputError::InvalidTranscript(
                metadata_validation.issues,
            ),
        );
    }
    if preflight_binding != gateway_formal_backend_transcript_preflight_binding(&metadata) {
        return Err(GatewayFormalBackendTranscriptOutputError::PreflightBindingMismatch);
    }
    if toolchain_binding != gateway_formal_backend_transcript_toolchain_binding(&metadata) {
        return Err(GatewayFormalBackendTranscriptOutputError::ToolchainBindingMismatch);
    }
    if execution_status != gateway_formal_backend_transcript_execution_status(&metadata) {
        return Err(GatewayFormalBackendTranscriptOutputError::ExecutionStatusMismatch);
    }
    if checker_status != gateway_formal_backend_transcript_checker_status(&metadata) {
        return Err(GatewayFormalBackendTranscriptOutputError::CheckerStatusMismatch);
    }
    if redaction_report != metadata.redaction_report
        || transcript_redaction_retains_forbidden_material(&redaction_report)
    {
        return Err(GatewayFormalBackendTranscriptOutputError::RedactionReportMismatch);
    }
    if proof_obligations != gateway_formal_backend_transcript_proof_obligations(&metadata) {
        return Err(GatewayFormalBackendTranscriptOutputError::ProofObligationsMismatch);
    }
    if declared_gateway_formal_backend_transcript_bytes(
        files,
        "gateway-formal-backend-transcript/nonclaims.md",
    )? != render_gateway_formal_backend_transcript_nonclaims(&metadata.nonclaims).as_bytes()
    {
        return Err(GatewayFormalBackendTranscriptOutputError::NonclaimMismatch);
    }

    let expected_request = GatewayFormalBackendTranscriptOutputRequest {
        bundle_id: manifest.bundle_id.clone(),
        created_at_unix: manifest.created_at_unix,
        overwrite: false,
        protected_roots: Vec::new(),
    };
    validate_gateway_formal_backend_transcript_manifest_semantics(
        &manifest,
        &metadata,
        &expected_request,
        files,
    )?;
    Ok(manifest)
}

fn validate_gateway_formal_backend_transcript_metadata_shape(
    metadata: &GatewayFormalBackendExecutionTranscriptMetadata,
) -> GatewayFormalBackendTranscriptValidation {
    let mut issues = Vec::new();
    if metadata.schema_version != GATEWAY_FORMAL_BACKEND_TRANSCRIPT_SCHEMA_VERSION {
        issues.push(GatewayFormalBackendTranscriptIssue::InvalidSchemaVersion);
    }
    if metadata.transcript_id.trim().is_empty()
        || !is_safe_relative_path(&metadata.transcript_id)
        || metadata.transcript_id.contains(['/', '\\'])
    {
        issues.push(GatewayFormalBackendTranscriptIssue::InvalidTranscriptId);
    }
    if metadata.state_slice != GATEWAY_FORMAL_BACKEND_TRANSCRIPT_STATE_SLICE {
        issues.push(GatewayFormalBackendTranscriptIssue::StateSliceMismatch);
    }
    if metadata.preflight_bundle_manifest_digest == Hash([0; 32]) {
        issues.push(GatewayFormalBackendTranscriptIssue::PreflightManifestDigestMismatch);
    }
    if metadata.preflight_request_digest == Hash([0; 32]) {
        issues.push(GatewayFormalBackendTranscriptIssue::PreflightRequestDigestMismatch);
    }
    if metadata.preflight_report_digest == Hash([0; 32]) {
        issues.push(GatewayFormalBackendTranscriptIssue::PreflightReportDigestMismatch);
    }
    if metadata.command_descriptor_digest == Hash([0; 32]) {
        issues.push(GatewayFormalBackendTranscriptIssue::CommandDescriptorDigestMismatch);
    }
    if metadata.tool_name.trim().is_empty() {
        issues.push(GatewayFormalBackendTranscriptIssue::ToolNameMismatch);
    }
    if metadata.tool_version.trim().is_empty() {
        issues.push(GatewayFormalBackendTranscriptIssue::ToolVersionMismatch);
    }
    if metadata.toolchain_lock_digest == Hash([0; 32]) {
        issues.push(GatewayFormalBackendTranscriptIssue::ToolchainLockDigestMismatch);
    }
    if metadata.execution_status != GatewayFormalBackendTranscriptExecutionStatus::NotExecuted {
        issues.push(GatewayFormalBackendTranscriptIssue::ExecutionStatusEscalated);
    }
    if metadata.started_at_unix.is_some() || metadata.finished_at_unix.is_some() {
        issues.push(GatewayFormalBackendTranscriptIssue::TimestampSubmitted);
    }
    if metadata.exit_status != GatewayFormalBackendRunExitStatus::NotRun {
        issues.push(GatewayFormalBackendTranscriptIssue::ExitStatusEscalated);
    }
    if metadata.checker_status != GatewayFormalBackendTranscriptCheckerStatus::NotChecked {
        issues.push(GatewayFormalBackendTranscriptIssue::CheckerStatusEscalated);
    }
    if metadata.redacted_stdout_summary_digest.is_some() {
        issues.push(GatewayFormalBackendTranscriptIssue::StdoutSummarySubmitted);
    }
    if metadata.redacted_stderr_summary_digest.is_some() {
        issues.push(GatewayFormalBackendTranscriptIssue::StderrSummarySubmitted);
    }
    if metadata.proof_artifact_ref.is_some() {
        issues.push(GatewayFormalBackendTranscriptIssue::ProofArtifactReferenceSubmitted);
    }
    if metadata.checker_transcript_ref.is_some() {
        issues.push(GatewayFormalBackendTranscriptIssue::CheckerTranscriptReferenceSubmitted);
    }
    if !metadata.proof_obligations_requested.is_empty() {
        issues.push(GatewayFormalBackendTranscriptIssue::ProofObligationsRequestedMismatch);
    }
    if !metadata.proof_obligations_discharged.is_empty() {
        issues.push(GatewayFormalBackendTranscriptIssue::ProofObligationsDischargedBeforeExecution);
    }
    if !metadata.proof_obligations_not_discharged.is_empty() {
        issues.push(
            GatewayFormalBackendTranscriptIssue::ProofObligationsNotDischargedBeforeExecution,
        );
    }
    if !metadata.verifier_trust_roots.is_empty() {
        issues.push(GatewayFormalBackendTranscriptIssue::VerifierTrustRootSubmitted);
    }
    if transcript_redaction_retains_forbidden_material(&metadata.redaction_report) {
        issues.push(GatewayFormalBackendTranscriptIssue::RedactionReportRetainsForbiddenMaterial);
    }
    if metadata.claim_boundary != gateway_formal_backend_transcript_claim_boundary() {
        issues.push(GatewayFormalBackendTranscriptIssue::ClaimBoundaryMismatch);
    }
    if metadata.backend_executed {
        issues.push(GatewayFormalBackendTranscriptIssue::BackendExecuted);
    }
    if metadata.proof_artifact_created {
        issues.push(GatewayFormalBackendTranscriptIssue::ProofArtifactCreated);
    }
    if metadata.checker_transcript_created {
        issues.push(GatewayFormalBackendTranscriptIssue::CheckerTranscriptCreated);
    }
    if metadata.checker_succeeded {
        issues.push(GatewayFormalBackendTranscriptIssue::CheckerSucceeded);
    }
    if metadata.creates_accepted_evidence {
        issues.push(GatewayFormalBackendTranscriptIssue::AcceptedEvidenceCreated);
    }
    if metadata.creates_level2_evidence {
        issues.push(GatewayFormalBackendTranscriptIssue::Level2EvidenceCreated);
    }
    if metadata.populates_score_axes {
        issues.push(GatewayFormalBackendTranscriptIssue::ScoreAxesPopulated);
    }
    if metadata.grants_authority {
        issues.push(GatewayFormalBackendTranscriptIssue::AuthorityGranted);
    }
    if metadata.semantic_correctness_claimed {
        issues.push(GatewayFormalBackendTranscriptIssue::SemanticCorrectnessClaimed);
    }
    if metadata.production_readiness_claimed {
        issues.push(GatewayFormalBackendTranscriptIssue::ProductionReadinessClaimed);
    }
    if metadata.sota_claimed {
        issues.push(GatewayFormalBackendTranscriptIssue::SotaClaimed);
    }
    if metadata.full_security_claimed {
        issues.push(GatewayFormalBackendTranscriptIssue::FullSecurityClaimed);
    }
    for forbidden in gateway_formal_evidence_forbidden_claim_fragments() {
        if metadata
            .claim_text
            .iter()
            .any(|text| text.to_ascii_lowercase().contains(forbidden))
        {
            issues.push(GatewayFormalBackendTranscriptIssue::ForbiddenClaimText(
                (*forbidden).to_owned(),
            ));
        }
    }
    for required in gateway_formal_backend_transcript_required_nonclaims() {
        if !metadata.nonclaims.contains(&required) {
            issues.push(GatewayFormalBackendTranscriptIssue::MissingRequiredNonclaim(required.0));
        }
    }

    GatewayFormalBackendTranscriptValidation {
        valid: issues.is_empty(),
        issues,
    }
}

fn validate_gateway_formal_backend_transcript_manifest_semantics(
    manifest: &GatewayFormalBackendTranscriptOutputManifest,
    metadata: &GatewayFormalBackendExecutionTranscriptMetadata,
    request: &GatewayFormalBackendTranscriptOutputRequest,
    files: &BTreeMap<String, Vec<u8>>,
) -> Result<(), GatewayFormalBackendTranscriptOutputError> {
    let expected_digest_paths: BTreeSet<String> = GATEWAY_FORMAL_BACKEND_TRANSCRIPT_DECLARED_FILES
        .iter()
        .filter(|path| **path != "gateway-formal-backend-transcript/manifest.json")
        .map(|path| (*path).to_owned())
        .collect();
    let actual_digest_paths: BTreeSet<String> =
        manifest.declared_file_digests.keys().cloned().collect();
    if manifest.schema_version != GATEWAY_FORMAL_BACKEND_TRANSCRIPT_OUTPUT_SCHEMA_VERSION
        || manifest.bundle_id != request.bundle_id
        || manifest.state_slice != GATEWAY_FORMAL_BACKEND_TRANSCRIPT_OUTPUT_STATE_SLICE
        || manifest.created_at_unix != request.created_at_unix
        || manifest.transcript_metadata_digest != metadata.digest()
        || manifest.preflight_bundle_manifest_digest != metadata.preflight_bundle_manifest_digest
        || manifest.preflight_request_digest != metadata.preflight_request_digest
        || manifest.preflight_report_digest != metadata.preflight_report_digest
        || manifest.command_descriptor_digest != metadata.command_descriptor_digest
        || manifest.backend_kind != metadata.backend_kind
        || manifest.tool_name != metadata.tool_name
        || manifest.tool_version != metadata.tool_version
        || manifest.toolchain_lock_digest != metadata.toolchain_lock_digest
        || manifest.execution_status != metadata.execution_status
        || manifest.checker_status != metadata.checker_status
        || manifest.redaction_report_digest
            != hash_bytes(declared_gateway_formal_backend_transcript_bytes(
                files,
                "gateway-formal-backend-transcript/redaction-report.json",
            )?)
        || manifest.proof_obligations_digest
            != hash_bytes(declared_gateway_formal_backend_transcript_bytes(
                files,
                "gateway-formal-backend-transcript/proof-obligations.json",
            )?)
        || manifest.nonclaims_digest
            != hash_bytes(declared_gateway_formal_backend_transcript_bytes(
                files,
                "gateway-formal-backend-transcript/nonclaims.md",
            )?)
        || manifest.declared_files != gateway_formal_backend_transcript_output_declared_files()
        || actual_digest_paths != expected_digest_paths
        || manifest
            .declared_file_digests
            .values()
            .any(|digest| *digest == Hash([0; 32]))
        || manifest.claim_boundary != gateway_formal_backend_transcript_output_claim_boundary()
        || manifest.backend_executed
        || manifest.proof_artifact_created
        || manifest.checker_transcript_created
        || manifest.checker_succeeded
        || manifest.creates_accepted_evidence
        || manifest.creates_level2_evidence
        || manifest.populates_score_axes
        || manifest.grants_authority
        || manifest.nonclaims != metadata.nonclaims
    {
        return Err(GatewayFormalBackendTranscriptOutputError::ManifestSemanticMismatch);
    }
    for (logical_path, expected_digest) in &manifest.declared_file_digests {
        if hash_bytes(declared_gateway_formal_backend_transcript_bytes(
            files,
            logical_path,
        )?) != *expected_digest
        {
            return Err(GatewayFormalBackendTranscriptOutputError::DigestMismatch(
                logical_path.clone(),
            ));
        }
    }
    Ok(())
}

pub fn gateway_formal_backend_execution_authorization_required_nonclaims() -> BTreeSet<NonClaimLabel>
{
    let mut nonclaims = gateway_formal_backend_transcript_required_nonclaims();
    nonclaims.extend([
        NonClaimLabel("execution authorization metadata only".to_owned()),
        NonClaimLabel("no process spawned".to_owned()),
        NonClaimLabel("quarantine output only".to_owned()),
        NonClaimLabel("authorization is not accepted evidence".to_owned()),
        NonClaimLabel("authorization does not grant execution authority".to_owned()),
        NonClaimLabel("proof checker artifacts are not accepted evidence".to_owned()),
    ]);
    nonclaims
}

pub fn gateway_formal_backend_execution_authorization_claim_boundary() -> String {
    GATEWAY_FORMAL_BACKEND_EXECUTION_AUTHORIZATION_CLAIM_BOUNDARY.to_owned()
}

