pub fn gateway_formal_backend_execution_authorization_operator_acknowledgement(
    authorization_id: impl Into<String>,
    operator_id: impl Into<String>,
    preflight_request: &GatewayFormalBackendExecutionPreflightRequest,
    preflight_manifest: &GatewayFormalBackendPreflightOutputManifest,
    transcript_output_manifest: &GatewayFormalBackendTranscriptOutputManifest,
    quarantine_descriptor: &GatewayFormalBackendExecutionAuthorizationQuarantineDescriptor,
) -> GatewayFormalBackendExecutionAuthorizationOperatorAcknowledgement {
    let authorization_id = authorization_id.into();
    GatewayFormalBackendExecutionAuthorizationOperatorAcknowledgement {
        operator_id: operator_id.into(),
        acknowledgement_id: format!("{authorization_id}-operator-ack"),
        acknowledged_at_unix: 1_800_000_820,
        authorization_id_acknowledged: authorization_id,
        backend_kind_acknowledged: preflight_request.command_descriptor.backend_kind.clone(),
        command_descriptor_digest_acknowledged: preflight_request.command_descriptor.digest(),
        preflight_bundle_manifest_digest_acknowledged: preflight_manifest.digest(),
        transcript_output_manifest_digest_acknowledged: transcript_output_manifest.digest(),
        quarantine_descriptor_digest_acknowledged: quarantine_descriptor.digest(),
        no_process_spawn_acknowledged: true,
        no_network_policy_acknowledged: true,
        no_secret_policy_acknowledged: true,
        quarantine_only_acknowledged: true,
        nonpromotion_policy_acknowledged: true,
        checker_success_not_semantic_correctness_acknowledged: true,
        proof_checker_artifacts_not_accepted_evidence_acknowledged: true,
        grants_authority: false,
    }
}

