pub fn build_gateway_formal_backend_execution_quarantine_validation_summary(
    summary_id: impl Into<String>,
    created_at_unix: u64,
    manifest: &GatewayFormalBackendExecutionQuarantineOutputManifest,
) -> GatewayFormalBackendExecutionQuarantineValidationSummary {
    GatewayFormalBackendExecutionQuarantineValidationSummary {
        schema_version: GATEWAY_FORMAL_BACKEND_QUARANTINE_VALIDATION_SUMMARY_SCHEMA_VERSION
            .to_owned(),
        state_slice:
            GATEWAY_FORMAL_BACKEND_EXECUTION_QUARANTINE_VALIDATION_SUMMARY_STATE_SLICE.to_owned(),
        summary_id: summary_id.into(),
        created_at_unix,
        quarantine_output_manifest_digest: manifest.digest(),
        quarantine_artifact_digest: manifest.quarantine_artifact_digest,
        declared_files_checked: manifest.declared_files.clone(),
        sidecars_checked: manifest
            .declared_files
            .iter()
            .map(|path| format!("{path}.sha256"))
            .collect(),
        readback_validation_passed: true,
        drift_coverage_labels:
            gateway_formal_backend_execution_quarantine_validation_summary_required_drift_labels(),
        undeclared_file_coverage_labels:
            gateway_formal_backend_execution_quarantine_validation_summary_required_undeclared_labels(
            ),
        symlink_coverage_labels:
            gateway_formal_backend_execution_quarantine_validation_summary_required_symlink_labels(),
        nonpromotion_coverage_labels:
            gateway_formal_backend_execution_quarantine_validation_summary_required_nonpromotion_labels(),
        claim_boundary_coverage_labels:
            gateway_formal_backend_execution_quarantine_validation_summary_required_claim_boundary_labels(
            ),
        validation_command_labels:
            gateway_formal_backend_execution_quarantine_validation_summary_required_command_labels(),
        local_regression_only: true,
        no_backend_executed: true,
        proof_artifact_promoted: false,
        checker_transcript_promoted: false,
        accepted_evidence_mutation: false,
        creates_level2_evidence: false,
        populates_score_axes: false,
        semantic_correctness_claimed: false,
        production_readiness_claimed: false,
        sota_claimed: false,
        breakthrough_claimed: false,
        full_security_claimed: false,
        grants_authority: false,
        claim_boundary:
            gateway_formal_backend_execution_quarantine_validation_summary_claim_boundary(),
        nonclaims:
            gateway_formal_backend_execution_quarantine_validation_summary_required_nonclaims(),
    }
}

pub fn validate_gateway_formal_backend_execution_quarantine_validation_summary(
    summary: &GatewayFormalBackendExecutionQuarantineValidationSummary,
    manifest: &GatewayFormalBackendExecutionQuarantineOutputManifest,
) -> GatewayFormalBackendExecutionQuarantineValidationSummaryValidation {
    let mut issues = Vec::new();

    if summary.schema_version != GATEWAY_FORMAL_BACKEND_QUARANTINE_VALIDATION_SUMMARY_SCHEMA_VERSION
    {
        issues.push(
            GatewayFormalBackendExecutionQuarantineValidationSummaryIssue::InvalidSchemaVersion,
        );
    }
    if summary.state_slice
        != GATEWAY_FORMAL_BACKEND_EXECUTION_QUARANTINE_VALIDATION_SUMMARY_STATE_SLICE
    {
        issues.push(
            GatewayFormalBackendExecutionQuarantineValidationSummaryIssue::StateSliceMismatch,
        );
    }
    if summary.summary_id.trim().is_empty()
        || !is_safe_relative_path(&summary.summary_id)
        || summary.summary_id.contains(['/', '\\'])
    {
        issues
            .push(GatewayFormalBackendExecutionQuarantineValidationSummaryIssue::InvalidSummaryId);
    }
    if summary.quarantine_output_manifest_digest == Hash([0; 32])
        || summary.quarantine_output_manifest_digest != manifest.digest()
    {
        issues.push(
            GatewayFormalBackendExecutionQuarantineValidationSummaryIssue::ManifestDigestMismatch,
        );
    }
    if summary.quarantine_artifact_digest == Hash([0; 32])
        || summary.quarantine_artifact_digest != manifest.quarantine_artifact_digest
    {
        issues.push(
            GatewayFormalBackendExecutionQuarantineValidationSummaryIssue::QuarantineArtifactDigestMismatch,
        );
    }
    if summary.declared_files_checked != manifest.declared_files {
        issues.push(
            GatewayFormalBackendExecutionQuarantineValidationSummaryIssue::DeclaredFilesMismatch,
        );
    }
    let expected_sidecars = manifest
        .declared_files
        .iter()
        .map(|path| format!("{path}.sha256"))
        .collect::<Vec<_>>();
    if summary.sidecars_checked != expected_sidecars {
        issues
            .push(GatewayFormalBackendExecutionQuarantineValidationSummaryIssue::SidecarsMismatch);
    }
    if !summary.readback_validation_passed {
        issues.push(
            GatewayFormalBackendExecutionQuarantineValidationSummaryIssue::ReadbackValidationFailed,
        );
    }

    validate_gateway_formal_backend_quarantine_summary_label_set(
        &summary.drift_coverage_labels,
        &gateway_formal_backend_execution_quarantine_validation_summary_required_drift_labels(),
        &mut issues,
    );
    validate_gateway_formal_backend_quarantine_summary_label_set(
        &summary.undeclared_file_coverage_labels,
        &gateway_formal_backend_execution_quarantine_validation_summary_required_undeclared_labels(
        ),
        &mut issues,
    );
    validate_gateway_formal_backend_quarantine_summary_label_set(
        &summary.symlink_coverage_labels,
        &gateway_formal_backend_execution_quarantine_validation_summary_required_symlink_labels(),
        &mut issues,
    );
    validate_gateway_formal_backend_quarantine_summary_label_set(
        &summary.nonpromotion_coverage_labels,
        &gateway_formal_backend_execution_quarantine_validation_summary_required_nonpromotion_labels(
        ),
        &mut issues,
    );
    validate_gateway_formal_backend_quarantine_summary_label_set(
        &summary.claim_boundary_coverage_labels,
        &gateway_formal_backend_execution_quarantine_validation_summary_required_claim_boundary_labels(
        ),
        &mut issues,
    );

    let required_commands =
        gateway_formal_backend_execution_quarantine_validation_summary_required_command_labels();
    for required in &required_commands {
        if !summary.validation_command_labels.contains(required) {
            issues.push(
                GatewayFormalBackendExecutionQuarantineValidationSummaryIssue::MissingValidationCommandLabel(
                    required.clone(),
                ),
            );
        }
    }
    for actual in &summary.validation_command_labels {
        if !required_commands.contains(actual) {
            issues.push(
                GatewayFormalBackendExecutionQuarantineValidationSummaryIssue::UnknownValidationCommandLabel(
                    actual.clone(),
                ),
            );
        }
    }

    if !summary.local_regression_only {
        issues.push(
            GatewayFormalBackendExecutionQuarantineValidationSummaryIssue::LocalRegressionOnlyFalse,
        );
    }
    if !summary.no_backend_executed {
        issues.push(GatewayFormalBackendExecutionQuarantineValidationSummaryIssue::BackendExecuted);
    }
    if summary.proof_artifact_promoted {
        issues.push(
            GatewayFormalBackendExecutionQuarantineValidationSummaryIssue::ProofArtifactPromoted,
        );
    }
    if summary.checker_transcript_promoted {
        issues.push(
            GatewayFormalBackendExecutionQuarantineValidationSummaryIssue::CheckerTranscriptPromoted,
        );
    }
    if summary.accepted_evidence_mutation {
        issues.push(
            GatewayFormalBackendExecutionQuarantineValidationSummaryIssue::AcceptedEvidenceMutation,
        );
    }
    if summary.creates_level2_evidence {
        issues.push(
            GatewayFormalBackendExecutionQuarantineValidationSummaryIssue::Level2EvidenceCreated,
        );
    }
    if summary.populates_score_axes {
        issues.push(
            GatewayFormalBackendExecutionQuarantineValidationSummaryIssue::ScoreAxesPopulated,
        );
    }
    if summary.semantic_correctness_claimed {
        issues.push(
            GatewayFormalBackendExecutionQuarantineValidationSummaryIssue::SemanticCorrectnessClaimed,
        );
    }
    if summary.production_readiness_claimed {
        issues.push(
            GatewayFormalBackendExecutionQuarantineValidationSummaryIssue::ProductionReadinessClaimed,
        );
    }
    if summary.sota_claimed {
        issues.push(GatewayFormalBackendExecutionQuarantineValidationSummaryIssue::SotaClaimed);
    }
    if summary.breakthrough_claimed {
        issues.push(
            GatewayFormalBackendExecutionQuarantineValidationSummaryIssue::BreakthroughClaimed,
        );
    }
    if summary.full_security_claimed {
        issues.push(
            GatewayFormalBackendExecutionQuarantineValidationSummaryIssue::FullSecurityClaimed,
        );
    }
    if summary.grants_authority {
        issues
            .push(GatewayFormalBackendExecutionQuarantineValidationSummaryIssue::AuthorityGranted);
    }
    if summary.claim_boundary
        != gateway_formal_backend_execution_quarantine_validation_summary_claim_boundary()
    {
        issues.push(
            GatewayFormalBackendExecutionQuarantineValidationSummaryIssue::ClaimBoundaryMismatch,
        );
    }
    for required in
        gateway_formal_backend_execution_quarantine_validation_summary_required_nonclaims()
    {
        if !summary.nonclaims.contains(&required) {
            issues.push(
                GatewayFormalBackendExecutionQuarantineValidationSummaryIssue::MissingRequiredNonclaim(
                    required.0,
                ),
            );
        }
    }

    GatewayFormalBackendExecutionQuarantineValidationSummaryValidation {
        valid: issues.is_empty(),
        issues,
    }
}

