pub fn materialize_gateway_formal_backend_execution_quarantine_validation_summary_output_bundle(
    output_root: &Path,
    summary: &GatewayFormalBackendExecutionQuarantineValidationSummary,
    source_manifest: &GatewayFormalBackendExecutionQuarantineOutputManifest,
    request: &GatewayFormalBackendExecutionQuarantineValidationSummaryOutputRequest,
) -> Result<
    GatewayFormalBackendExecutionQuarantineValidationSummaryOutputManifest,
    GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError,
> {
    validate_gateway_formal_backend_execution_quarantine_validation_summary_output_request(
        output_root,
        summary,
        source_manifest,
        request,
    )?;
    let staging_root = gateway_formal_backend_quarantine_validation_summary_staging_root_for(
        output_root,
        &request.bundle_id,
    )?;
    if staging_root.exists() {
        remove_gateway_formal_backend_quarantine_validation_summary_dir_all_checked(&staging_root)?;
    }
    fs::create_dir_all(staging_root.join("gateway-formal-backend-quarantine-validation-summary"))
        .map_err(gateway_formal_backend_quarantine_validation_summary_io_error)?;

    let files = build_gateway_formal_backend_quarantine_validation_summary_bundle_files(
        summary,
        source_manifest,
        request,
    )?;
    for (logical_path, bytes) in &files {
        let target = staging_root.join(logical_path);
        if let Some(parent) = target.parent() {
            fs::create_dir_all(parent)
                .map_err(gateway_formal_backend_quarantine_validation_summary_io_error)?;
        }
        fs::write(&target, bytes)
            .map_err(gateway_formal_backend_quarantine_validation_summary_io_error)?;
        fs::write(
            sidecar_path(&target),
            hash_hex(hash_bytes(bytes)).into_bytes(),
        )
        .map_err(gateway_formal_backend_quarantine_validation_summary_io_error)?;
    }

    if output_root.exists() {
        if !request.overwrite {
            remove_gateway_formal_backend_quarantine_validation_summary_dir_all_checked(
                &staging_root,
            )?;
            return Err(
                GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError::OutputRootExistsWithoutOverwrite,
            );
        }
        remove_gateway_formal_backend_quarantine_validation_summary_dir_all_checked(output_root)?;
    }
    fs::rename(&staging_root, output_root)
        .map_err(gateway_formal_backend_quarantine_validation_summary_io_error)?;
    read_gateway_formal_backend_execution_quarantine_validation_summary_output_bundle(output_root)
}

pub fn read_gateway_formal_backend_execution_quarantine_validation_summary_output_bundle(
    output_root: &Path,
) -> Result<
    GatewayFormalBackendExecutionQuarantineValidationSummaryOutputManifest,
    GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError,
> {
    let output_metadata = fs::symlink_metadata(output_root)
        .map_err(gateway_formal_backend_quarantine_validation_summary_io_error)?;
    if output_metadata.file_type().is_symlink() {
        return Err(
            GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError::OutputRootIsSymlink,
        );
    }
    if !output_metadata.is_dir() {
        return Err(
            GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError::OutputRootIsFile,
        );
    }
    let bundle_dir = output_root.join("gateway-formal-backend-quarantine-validation-summary");
    let bundle_metadata = fs::symlink_metadata(&bundle_dir)
        .map_err(gateway_formal_backend_quarantine_validation_summary_io_error)?;
    if bundle_metadata.file_type().is_symlink() {
        return Err(
            GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError::BundleFileIsSymlink(
                "gateway-formal-backend-quarantine-validation-summary".to_owned(),
            ),
        );
    }
    if !bundle_metadata.is_dir() {
        return Err(
            GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError::DeclaredFileTypeMismatch(
                "gateway-formal-backend-quarantine-validation-summary".to_owned(),
            ),
        );
    }

    reject_undeclared_gateway_formal_backend_quarantine_validation_summary_files(output_root)?;
    let mut file_bytes = BTreeMap::new();
    for logical_path in GATEWAY_FORMAL_BACKEND_QUARANTINE_VALIDATION_SUMMARY_DECLARED_FILES {
        let path = output_root.join(logical_path);
        let metadata = fs::symlink_metadata(&path)
            .map_err(gateway_formal_backend_quarantine_validation_summary_io_error)?;
        if metadata.file_type().is_symlink() {
            return Err(
                GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError::BundleFileIsSymlink(
                    (*logical_path).to_owned(),
                ),
            );
        }
        if !metadata.is_file() {
            return Err(
                GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError::DeclaredFileTypeMismatch(
                    (*logical_path).to_owned(),
                ),
            );
        }
        let sidecar = sidecar_path(&path);
        let sidecar_metadata = fs::symlink_metadata(&sidecar)
            .map_err(gateway_formal_backend_quarantine_validation_summary_io_error)?;
        if sidecar_metadata.file_type().is_symlink() {
            return Err(
                GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError::BundleFileIsSymlink(
                    format!("{logical_path}.sha256"),
                ),
            );
        }
        if !sidecar_metadata.is_file() {
            return Err(
                GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError::DeclaredFileTypeMismatch(
                    format!("{logical_path}.sha256"),
                ),
            );
        }
        let bytes = fs::read(&path)
            .map_err(gateway_formal_backend_quarantine_validation_summary_io_error)?;
        let expected = fs::read_to_string(sidecar)
            .map_err(gateway_formal_backend_quarantine_validation_summary_io_error)?;
        if expected != hash_hex(hash_bytes(&bytes)) {
            return Err(
                GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError::DigestMismatch(
                    (*logical_path).to_owned(),
                ),
            );
        }
        file_bytes.insert((*logical_path).to_owned(), bytes);
    }

    validate_gateway_formal_backend_quarantine_validation_summary_bundle_semantics(&file_bytes)
}

fn validate_gateway_formal_backend_execution_quarantine_validation_summary_output_request(
    output_root: &Path,
    summary: &GatewayFormalBackendExecutionQuarantineValidationSummary,
    source_manifest: &GatewayFormalBackendExecutionQuarantineOutputManifest,
    request: &GatewayFormalBackendExecutionQuarantineValidationSummaryOutputRequest,
) -> Result<(), GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError> {
    if request.bundle_id.trim().is_empty()
        || !is_safe_relative_path(&request.bundle_id)
        || request.bundle_id.contains(['/', '\\'])
    {
        return Err(
            GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError::EmptyBundleId,
        );
    }
    let validation = validate_gateway_formal_backend_execution_quarantine_validation_summary(
        summary,
        source_manifest,
    );
    if !validation.valid {
        return Err(
            GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError::InvalidSummary(
                validation.issues,
            ),
        );
    }
    let expected_summary = build_gateway_formal_backend_execution_quarantine_validation_summary(
        summary.summary_id.clone(),
        summary.created_at_unix,
        source_manifest,
    );
    if summary != &expected_summary {
        return Err(
            GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError::SummaryMismatch,
        );
    }
    validate_gateway_formal_backend_quarantine_validation_summary_output_root(
        output_root,
        &request.protected_roots,
        request.overwrite,
    )
}

fn build_gateway_formal_backend_quarantine_validation_summary_bundle_files(
    summary: &GatewayFormalBackendExecutionQuarantineValidationSummary,
    source_manifest: &GatewayFormalBackendExecutionQuarantineOutputManifest,
    request: &GatewayFormalBackendExecutionQuarantineValidationSummaryOutputRequest,
) -> Result<
    BTreeMap<String, Vec<u8>>,
    GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError,
> {
    let coverage_labels =
        gateway_formal_backend_quarantine_validation_summary_coverage_labels(summary);
    let validation_report =
        gateway_formal_backend_quarantine_validation_summary_validation_report(summary, request);
    let nonclaims =
        render_gateway_formal_backend_quarantine_validation_summary_nonclaims(&summary.nonclaims);
    let mut files = BTreeMap::from([
        (
            "gateway-formal-backend-quarantine-validation-summary/summary.json".to_owned(),
            serde_json::to_vec_pretty(summary)
                .map_err(gateway_formal_backend_quarantine_validation_summary_serde_error)?,
        ),
        (
            "gateway-formal-backend-quarantine-validation-summary/source-manifest.json".to_owned(),
            serde_json::to_vec_pretty(source_manifest)
                .map_err(gateway_formal_backend_quarantine_validation_summary_serde_error)?,
        ),
        (
            "gateway-formal-backend-quarantine-validation-summary/coverage-labels.json".to_owned(),
            serde_json::to_vec_pretty(&coverage_labels)
                .map_err(gateway_formal_backend_quarantine_validation_summary_serde_error)?,
        ),
        (
            "gateway-formal-backend-quarantine-validation-summary/nonclaims.md".to_owned(),
            nonclaims.into_bytes(),
        ),
        (
            "gateway-formal-backend-quarantine-validation-summary/validation-report.json"
                .to_owned(),
            serde_json::to_vec_pretty(&validation_report)
                .map_err(gateway_formal_backend_quarantine_validation_summary_serde_error)?,
        ),
    ]);
    let manifest = gateway_formal_backend_quarantine_validation_summary_output_manifest_for_files(
        summary,
        source_manifest,
        &coverage_labels,
        &validation_report,
        request,
        &files,
    );
    files.insert(
        "gateway-formal-backend-quarantine-validation-summary/manifest.json".to_owned(),
        serde_json::to_vec_pretty(&manifest)
            .map_err(gateway_formal_backend_quarantine_validation_summary_serde_error)?,
    );
    Ok(files)
}

fn gateway_formal_backend_quarantine_validation_summary_output_manifest_for_files(
    summary: &GatewayFormalBackendExecutionQuarantineValidationSummary,
    source_manifest: &GatewayFormalBackendExecutionQuarantineOutputManifest,
    coverage_labels: &GatewayFormalBackendExecutionQuarantineValidationSummaryCoverageLabels,
    validation_report: &GatewayFormalBackendExecutionQuarantineValidationSummaryOutputValidationReport,
    request: &GatewayFormalBackendExecutionQuarantineValidationSummaryOutputRequest,
    files: &BTreeMap<String, Vec<u8>>,
) -> GatewayFormalBackendExecutionQuarantineValidationSummaryOutputManifest {
    let mut declared_file_digests = BTreeMap::new();
    for (logical_path, bytes) in files {
        declared_file_digests.insert(logical_path.clone(), hash_bytes(bytes));
    }
    GatewayFormalBackendExecutionQuarantineValidationSummaryOutputManifest {
        schema_version: GATEWAY_FORMAL_BACKEND_QUARANTINE_VALIDATION_SUMMARY_OUTPUT_SCHEMA_VERSION
            .to_owned(),
        bundle_id: request.bundle_id.clone(),
        state_slice:
            GATEWAY_FORMAL_BACKEND_EXECUTION_QUARANTINE_VALIDATION_SUMMARY_OUTPUT_STATE_SLICE
                .to_owned(),
        created_at_unix: request.created_at_unix,
        validation_summary_digest: summary.digest(),
        source_quarantine_output_manifest_digest: source_manifest.digest(),
        source_quarantine_artifact_digest: source_manifest.quarantine_artifact_digest,
        coverage_labels_digest: coverage_labels.digest(),
        validation_report_digest: validation_report.digest(),
        nonclaims_digest: hash_bytes(
            files
                .get("gateway-formal-backend-quarantine-validation-summary/nonclaims.md")
                .map(Vec::as_slice)
                .unwrap_or_default(),
        ),
        declared_files:
            gateway_formal_backend_execution_quarantine_validation_summary_output_declared_files(),
        declared_file_digests,
        claim_boundary:
            gateway_formal_backend_execution_quarantine_validation_summary_output_claim_boundary(),
        local_regression_only: true,
        no_backend_executed: true,
        proof_artifact_promoted: false,
        checker_transcript_promoted: false,
        accepted_evidence_mutation: false,
        creates_level2_evidence: false,
        populates_score_axes: false,
        semantic_correctness_claimed: false,
        production_readiness_claimed: false,
        sota_claimed: false,
        breakthrough_claimed: false,
        full_security_claimed: false,
        grants_authority: false,
        nonclaims: summary.nonclaims.clone(),
    }
}

fn validate_gateway_formal_backend_quarantine_validation_summary_bundle_semantics(
    files: &BTreeMap<String, Vec<u8>>,
) -> Result<
    GatewayFormalBackendExecutionQuarantineValidationSummaryOutputManifest,
    GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError,
> {
    let manifest: GatewayFormalBackendExecutionQuarantineValidationSummaryOutputManifest =
        parse_gateway_formal_backend_quarantine_validation_summary_declared_json(
            files,
            "gateway-formal-backend-quarantine-validation-summary/manifest.json",
        )?;
    let summary: GatewayFormalBackendExecutionQuarantineValidationSummary =
        parse_gateway_formal_backend_quarantine_validation_summary_declared_json(
            files,
            "gateway-formal-backend-quarantine-validation-summary/summary.json",
        )?;
    let source_manifest: GatewayFormalBackendExecutionQuarantineOutputManifest =
        parse_gateway_formal_backend_quarantine_validation_summary_declared_json(
            files,
            "gateway-formal-backend-quarantine-validation-summary/source-manifest.json",
        )?;
    let coverage_labels: GatewayFormalBackendExecutionQuarantineValidationSummaryCoverageLabels =
        parse_gateway_formal_backend_quarantine_validation_summary_declared_json(
            files,
            "gateway-formal-backend-quarantine-validation-summary/coverage-labels.json",
        )?;
    let validation_report:
        GatewayFormalBackendExecutionQuarantineValidationSummaryOutputValidationReport =
        parse_gateway_formal_backend_quarantine_validation_summary_declared_json(
            files,
            "gateway-formal-backend-quarantine-validation-summary/validation-report.json",
        )?;

    let summary_validation =
        validate_gateway_formal_backend_execution_quarantine_validation_summary(
            &summary,
            &source_manifest,
        );
    if !summary_validation.valid {
        return Err(
            GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError::InvalidSummary(
                summary_validation.issues,
            ),
        );
    }
    if summary.quarantine_output_manifest_digest != source_manifest.digest()
        || summary.quarantine_artifact_digest != source_manifest.quarantine_artifact_digest
    {
        return Err(
            GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError::SourceManifestMismatch,
        );
    }
    if coverage_labels
        != gateway_formal_backend_quarantine_validation_summary_coverage_labels(&summary)
    {
        return Err(
            GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError::CoverageLabelMismatch,
        );
    }
    if declared_gateway_formal_backend_quarantine_validation_summary_bytes(
        files,
        "gateway-formal-backend-quarantine-validation-summary/nonclaims.md",
    )? != render_gateway_formal_backend_quarantine_validation_summary_nonclaims(
        &summary.nonclaims,
    )
    .as_bytes()
    {
        return Err(
            GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError::NonclaimMismatch,
        );
    }

    let expected_report =
        gateway_formal_backend_quarantine_validation_summary_validation_report_for_manifest(
            &summary, &manifest,
        );
    if validation_report != expected_report {
        return Err(
            GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError::ValidationReportMismatch,
        );
    }
    validate_gateway_formal_backend_quarantine_validation_summary_manifest_semantics(
        &manifest,
        &summary,
        &source_manifest,
        &coverage_labels,
        &validation_report,
        files,
    )?;
    Ok(manifest)
}

fn validate_gateway_formal_backend_quarantine_validation_summary_manifest_semantics(
    manifest: &GatewayFormalBackendExecutionQuarantineValidationSummaryOutputManifest,
    summary: &GatewayFormalBackendExecutionQuarantineValidationSummary,
    source_manifest: &GatewayFormalBackendExecutionQuarantineOutputManifest,
    coverage_labels: &GatewayFormalBackendExecutionQuarantineValidationSummaryCoverageLabels,
    validation_report: &GatewayFormalBackendExecutionQuarantineValidationSummaryOutputValidationReport,
    files: &BTreeMap<String, Vec<u8>>,
) -> Result<(), GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError> {
    let expected_digest_paths: BTreeSet<String> =
        GATEWAY_FORMAL_BACKEND_QUARANTINE_VALIDATION_SUMMARY_DECLARED_FILES
            .iter()
            .filter(|path| {
                **path != "gateway-formal-backend-quarantine-validation-summary/manifest.json"
            })
            .map(|path| (*path).to_owned())
            .collect();
    let actual_digest_paths: BTreeSet<String> =
        manifest.declared_file_digests.keys().cloned().collect();
    if manifest.schema_version
        != GATEWAY_FORMAL_BACKEND_QUARANTINE_VALIDATION_SUMMARY_OUTPUT_SCHEMA_VERSION
        || manifest.bundle_id.trim().is_empty()
        || !is_safe_relative_path(&manifest.bundle_id)
        || manifest.bundle_id.contains(['/', '\\'])
        || manifest.state_slice
            != GATEWAY_FORMAL_BACKEND_EXECUTION_QUARANTINE_VALIDATION_SUMMARY_OUTPUT_STATE_SLICE
        || manifest.validation_summary_digest != summary.digest()
        || manifest.source_quarantine_output_manifest_digest != source_manifest.digest()
        || manifest.source_quarantine_artifact_digest != source_manifest.quarantine_artifact_digest
        || manifest.coverage_labels_digest != coverage_labels.digest()
        || manifest.validation_report_digest != validation_report.digest()
        || manifest.nonclaims_digest
            != hash_bytes(
                declared_gateway_formal_backend_quarantine_validation_summary_bytes(
                    files,
                    "gateway-formal-backend-quarantine-validation-summary/nonclaims.md",
                )?,
            )
        || manifest.declared_files
            != gateway_formal_backend_execution_quarantine_validation_summary_output_declared_files(
            )
        || actual_digest_paths != expected_digest_paths
        || manifest.claim_boundary
            != gateway_formal_backend_execution_quarantine_validation_summary_output_claim_boundary(
            )
        || !manifest.local_regression_only
        || !manifest.no_backend_executed
        || manifest.proof_artifact_promoted
        || manifest.checker_transcript_promoted
        || manifest.accepted_evidence_mutation
        || manifest.creates_level2_evidence
        || manifest.populates_score_axes
        || manifest.semantic_correctness_claimed
        || manifest.production_readiness_claimed
        || manifest.sota_claimed
        || manifest.breakthrough_claimed
        || manifest.full_security_claimed
        || manifest.grants_authority
        || manifest.nonclaims != summary.nonclaims
    {
        return Err(
            GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError::ManifestSemanticMismatch,
        );
    }
    for (logical_path, expected_digest) in &manifest.declared_file_digests {
        let bytes = declared_gateway_formal_backend_quarantine_validation_summary_bytes(
            files,
            logical_path,
        )?;
        if *expected_digest != hash_bytes(bytes) {
            return Err(
                GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError::DigestMismatch(
                    logical_path.clone(),
                ),
            );
        }
    }
    Ok(())
}

