fn render_gateway_formal_backend_quarantine_validation_summary_nonclaims(
    nonclaims: &BTreeSet<NonClaimLabel>,
) -> String {
    let mut out =
        String::from("# Gateway Formal Backend Quarantine Validation Summary Nonclaims\n\n");
    for nonclaim in nonclaims {
        out.push_str("- ");
        out.push_str(&nonclaim.0);
        out.push('\n');
    }
    out
}

fn declared_gateway_formal_backend_quarantine_validation_summary_bytes<'a>(
    files: &'a BTreeMap<String, Vec<u8>>,
    logical_path: &str,
) -> Result<&'a [u8], GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError> {
    files.get(logical_path).map(Vec::as_slice).ok_or_else(|| {
        GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError::Io(format!(
            "declared file missing: {logical_path}"
        ))
    })
}

fn parse_gateway_formal_backend_quarantine_validation_summary_declared_json<
    T: for<'de> Deserialize<'de>,
>(
    files: &BTreeMap<String, Vec<u8>>,
    logical_path: &str,
) -> Result<T, GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError> {
    let bytes =
        declared_gateway_formal_backend_quarantine_validation_summary_bytes(files, logical_path)?;
    let text = std::str::from_utf8(bytes).map_err(|_| {
        GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError::MalformedDeclaredFile(
            logical_path.to_owned(),
        )
    })?;
    serde_json::from_str(text).map_err(|_| {
        GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError::MalformedDeclaredFile(
            logical_path.to_owned(),
        )
    })
}

fn reject_undeclared_gateway_formal_backend_quarantine_validation_summary_files(
    output_root: &Path,
) -> Result<(), GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError> {
    let mut declared: BTreeSet<String> =
        GATEWAY_FORMAL_BACKEND_QUARANTINE_VALIDATION_SUMMARY_DECLARED_FILES
            .iter()
            .chain(GATEWAY_FORMAL_BACKEND_QUARANTINE_VALIDATION_SUMMARY_DECLARED_SIDECARS.iter())
            .map(|value| (*value).to_owned())
            .collect();
    let bundle_dir = output_root.join("gateway-formal-backend-quarantine-validation-summary");
    for entry in fs::read_dir(&bundle_dir)
        .map_err(gateway_formal_backend_quarantine_validation_summary_io_error)?
    {
        let entry = entry.map_err(gateway_formal_backend_quarantine_validation_summary_io_error)?;
        let logical_path = entry
            .path()
            .strip_prefix(output_root)
            .map_err(|error| {
                GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError::Io(
                    error.to_string(),
                )
            })?
            .to_string_lossy()
            .replace('\\', "/");
        if !declared.remove(&logical_path) {
            return Err(
                GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError::UndeclaredFile(
                    logical_path,
                ),
            );
        }
    }
    if let Some(missing) = declared.into_iter().next() {
        return Err(
            GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError::Io(format!(
                "declared file missing: {missing}"
            )),
        );
    }
    Ok(())
}

fn validate_gateway_formal_backend_quarantine_validation_summary_output_root(
    output_root: &Path,
    protected_roots: &[PathBuf],
    overwrite: bool,
) -> Result<(), GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError> {
    match validate_output_root(output_root, protected_roots, overwrite) {
        Ok(()) => Ok(()),
        Err(AdmissionJournalMaterializationError::EmptyOutputRoot) => {
            Err(GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError::EmptyOutputRoot)
        }
        Err(AdmissionJournalMaterializationError::ProtectedOutputRoot) => Err(
            GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError::ProtectedOutputRoot,
        ),
        Err(AdmissionJournalMaterializationError::OutputRootExistsWithoutOverwrite) => Err(
            GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError::OutputRootExistsWithoutOverwrite,
        ),
        Err(AdmissionJournalMaterializationError::OutputRootIsFile) => Err(
            GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError::OutputRootIsFile,
        ),
        Err(AdmissionJournalMaterializationError::OutputRootIsSymlink) => Err(
            GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError::OutputRootIsSymlink,
        ),
        Err(AdmissionJournalMaterializationError::Io(error)) => {
            Err(GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError::Io(error))
        }
        Err(other) => Err(
            GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError::Io(format!(
                "{other:?}"
            )),
        ),
    }
}

fn gateway_formal_backend_quarantine_validation_summary_staging_root_for(
    output_root: &Path,
    bundle_id: &str,
) -> Result<PathBuf, GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError> {
    let parent = output_root.parent().ok_or(
        GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError::EmptyOutputRoot,
    )?;
    let name = output_root
        .file_name()
        .map(|value| value.to_string_lossy().into_owned())
        .ok_or(
            GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError::EmptyOutputRoot,
        )?;
    Ok(parent.join(format!(".{name}.{bundle_id}.staging")))
}

fn remove_gateway_formal_backend_quarantine_validation_summary_dir_all_checked(
    path: &Path,
) -> Result<(), GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError> {
    if !path.exists() {
        return Ok(());
    }
    if fs::symlink_metadata(path)
        .map_err(gateway_formal_backend_quarantine_validation_summary_io_error)?
        .file_type()
        .is_symlink()
    {
        return Err(
            GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError::OutputRootIsSymlink,
        );
    }
    fs::remove_dir_all(path).map_err(gateway_formal_backend_quarantine_validation_summary_io_error)
}

fn gateway_formal_backend_quarantine_validation_summary_io_error(
    error: io::Error,
) -> GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError {
    GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError::Io(error.to_string())
}

fn gateway_formal_backend_quarantine_validation_summary_serde_error(
    error: serde_json::Error,
) -> GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError {
    GatewayFormalBackendExecutionQuarantineValidationSummaryOutputError::Serialization(
        error.to_string(),
    )
}

