fn validate_gateway_formal_backend_hermetic_process_spawn_executable_policy(
    policy: &GatewayFormalBackendHermeticProcessSpawnExecutablePolicy,
    descriptor: &GatewayFormalBackendHermeticExecutionDescriptor,
    issues: &mut Vec<GatewayFormalBackendHermeticProcessSpawnInterfaceIssue>,
) {
    if policy.policy_id.trim().is_empty() || !is_safe_relative_path(&policy.policy_id) {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::EmptyPolicyId);
    }
    if policy.backend_id != "local_smt_tiny_gateway_invariant" {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::BackendIdMismatch);
    }
    if policy.lane != GatewayFormalBackendHermeticExecutionLane::LocalSmtTinyGatewayInvariant {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::UnsupportedLane);
    }
    if policy.backend_kind != descriptor.backend_kind
        || policy.backend_kind != GatewayFormalBackendKind::Smt
    {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::BackendKindMismatch);
    }
    if policy.command_kind != GatewayFormalBackendHermeticCommandKind::DirectProcessNoShell {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::UnsupportedCommandKind);
    }
    if policy.executable_path_label != descriptor.executable_path_label {
        issues.push(
            GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::ExecutablePathLabelMismatch,
        );
    }
    if !is_safe_relative_path(&policy.executable_path_label)
        || policy.executable_path_label.starts_with('/')
        || policy.executable_path_label.contains("..")
    {
        issues.push(
            GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::UnsafeExecutablePathLabel,
        );
    }
    if policy.executable_digest == Hash([0; 32]) {
        issues
            .push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::ExecutableDigestMissing);
    }
    if policy.tool_name != descriptor.tool_name {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::ToolNameMismatch);
    }
    if policy.tool_version != descriptor.tool_version {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::ToolVersionMismatch);
    }
    if policy.toolchain_lock_digest != descriptor.toolchain_lock_digest {
        issues.push(
            GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::ToolchainLockDigestMismatch,
        );
    }
    if policy.argv_template != descriptor.argv_template {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::ArgvTemplateMismatch);
    }
    if policy.argv_template_digest
        != gateway_formal_backend_hermetic_argv_template_digest(&policy.argv_template)
        || policy.argv_template_digest
            != gateway_formal_backend_hermetic_argv_template_digest(&descriptor.argv_template)
    {
        issues.push(
            GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::ArgvTemplateDigestMismatch,
        );
    }
    for fragment in &policy.argv_template {
        if fragment.contains([';', '|', '&', '`', '$', '<', '>']) {
            issues
                .push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::ShellProcessAllowed);
        }
        if looks_like_credential_value(fragment) {
            issues.push(
                GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::CredentialLookingEnvironmentValue(
                    fragment.clone(),
                ),
            );
        }
    }
    if policy.caller_supplied_executable_allowed {
        issues
            .push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::CallerExecutableAllowed);
    }
    if policy.caller_supplied_argv_allowed {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::CallerArgvAllowed);
    }
    if !policy.direct_process_no_shell {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::ShellProcessAllowed);
    }
}

fn validate_gateway_formal_backend_hermetic_process_spawn_runtime_policy(
    policy: &GatewayFormalBackendHermeticProcessSpawnRuntimePolicy,
    descriptor: &GatewayFormalBackendHermeticExecutionDescriptor,
    issues: &mut Vec<GatewayFormalBackendHermeticProcessSpawnInterfaceIssue>,
) {
    if policy.output_root_label.trim().is_empty()
        || !is_safe_relative_path(&policy.output_root_label)
        || path_label_is_protected(&policy.output_root_label)
    {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::InvalidOutputRootLabel);
    }
    if !policy.output_root_outside_repo_required {
        issues.push(
            GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::OutputRootMayBeInsideRepo,
        );
    }
    if policy.inherit_environment {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::InheritedEnvironment);
    }
    for name in &policy.allowed_environment_variables {
        if !is_safe_environment_variable_name(name) || looks_like_credential_name(name) {
            issues.push(
                GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::InvalidEnvironmentVariableName(
                    name.clone(),
                ),
            );
        }
    }
    for (name, value) in &policy.environment_variables {
        if !policy.allowed_environment_variables.contains(name) {
            issues.push(
                GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::EnvironmentVariableNotAllowed(
                    name.clone(),
                ),
            );
        }
        if looks_like_credential_name(name) || looks_like_credential_value(value) {
            issues.push(
                GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::CredentialLookingEnvironmentValue(
                    name.clone(),
                ),
            );
        }
    }
    if !policy.no_stdin {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::StdinEnabled);
    }
    if !policy.no_shell {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::ShellEnabled);
    }
    if !policy.no_network {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::NetworkEnabled);
    }
    if policy.timeout_millis == 0 || policy.timeout_millis > 300_000 {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::InvalidTimeout);
    }
    if policy.max_stdout_bytes == 0 || policy.max_stdout_bytes > 64 * 1024 {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::InvalidStdoutLimit);
    }
    if policy.max_stderr_bytes == 0 || policy.max_stderr_bytes > 64 * 1024 {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::InvalidStderrLimit);
    }
    if !policy.redact_stdout {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::MissingStdoutRedaction);
    }
    if !policy.redact_stderr {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::MissingStderrRedaction);
    }
    if policy.retain_raw_stdout {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::RawStdoutRetained);
    }
    if policy.retain_raw_stderr {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::RawStderrRetained);
    }
    if policy.retain_raw_solver_trace {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::RawSolverTraceRetained);
    }
    if policy.retain_raw_prover_log {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::RawProverLogRetained);
    }
    if policy.retain_raw_checker_log {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::RawCheckerLogRetained);
    }
    if policy.retain_proof_artifact {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::ProofArtifactRetained);
    }
    if policy.retain_checker_transcript {
        issues.push(
            GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::CheckerTranscriptRetained,
        );
    }
    if policy.retain_solver_certificate {
        issues.push(
            GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::SolverCertificateRetained,
        );
    }
    if policy.output_root_label != descriptor.output_root_label
        || policy.timeout_millis != descriptor.timeout_millis
        || policy.max_stdout_bytes != descriptor.max_stdout_bytes
        || policy.max_stderr_bytes != descriptor.max_stderr_bytes
    {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::InvalidOutputRootLabel);
    }
}

fn validate_gateway_formal_backend_hermetic_process_spawn_nonpromotion_policy(
    policy: &GatewayFormalBackendHermeticProcessSpawnNonpromotionPolicy,
    issues: &mut Vec<GatewayFormalBackendHermeticProcessSpawnInterfaceIssue>,
) {
    if policy.proof_artifact_created {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::ProofArtifactCreated);
    }
    if policy.checker_transcript_created {
        issues
            .push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::CheckerTranscriptCreated);
    }
    if policy.solver_certificate_created {
        issues
            .push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::SolverCertificateCreated);
    }
    if policy.creates_accepted_evidence {
        issues
            .push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::AcceptedEvidenceCreated);
    }
    if policy.creates_level2_evidence {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::Level2EvidenceCreated);
    }
    if policy.populates_score_axes {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::ScoreAxesPopulated);
    }
    if policy.grants_authority {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::AuthorityGranted);
    }
    if policy.semantic_correctness_claimed {
        issues.push(
            GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::SemanticCorrectnessClaimed,
        );
    }
    if policy.production_readiness_claimed {
        issues.push(
            GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::ProductionReadinessClaimed,
        );
    }
    if policy.sota_claimed {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::SotaClaimed);
    }
    if policy.breakthrough_claimed {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::BreakthroughClaimed);
    }
    if policy.full_security_claimed {
        issues.push(GatewayFormalBackendHermeticProcessSpawnInterfaceIssue::FullSecurityClaimed);
    }
}

