pub fn materialize_gateway_formal_backend_hermetic_fixture_runner_output_bundle(
    output_root: &Path,
    interface: &GatewayFormalBackendHermeticProcessSpawnInterface,
    descriptor: &GatewayFormalBackendHermeticExecutionDescriptor,
    descriptor_report_manifest: &GatewayFormalBackendHermeticDescriptorReportOutputManifest,
    source_result_quarantine_manifest: &GatewayFormalBackendHermeticExecutionResultQuarantineOutputManifest,
    request: &GatewayFormalBackendHermeticFixtureRunnerRequest,
) -> Result<
    GatewayFormalBackendHermeticFixtureRunnerOutput,
    GatewayFormalBackendHermeticFixtureRunnerError,
> {
    validate_gateway_formal_backend_hermetic_fixture_runner_request(output_root, request)?;
    let interface_validation = validate_gateway_formal_backend_hermetic_process_spawn_interface(
        interface,
        descriptor,
        descriptor_report_manifest,
        source_result_quarantine_manifest,
    );
    if !interface_validation.valid {
        return Err(
            GatewayFormalBackendHermeticFixtureRunnerError::InvalidInterface(
                interface_validation.issues,
            ),
        );
    }
    if !gateway_formal_backend_hermetic_process_spawn_result_quarantine_manifest_matches(
        descriptor,
        descriptor_report_manifest,
        source_result_quarantine_manifest,
    ) {
        return Err(
            GatewayFormalBackendHermeticFixtureRunnerError::SourceResultQuarantineManifestMismatch,
        );
    }

    let process_result =
        run_gateway_formal_backend_hermetic_fixture_process(&interface.executable_policy)
            .map_err(GatewayFormalBackendHermeticFixtureRunnerError::ProcessSpawn)?;
    let files = build_gateway_formal_backend_hermetic_fixture_runner_bundle_files(
        interface,
        descriptor,
        descriptor_report_manifest,
        source_result_quarantine_manifest,
        request,
        &process_result,
    )?;
    let staging_root =
        gateway_formal_backend_hermetic_execution_result_quarantine_staging_root_for(
            output_root,
            &request.run_id,
        )
        .map_err(GatewayFormalBackendHermeticFixtureRunnerError::Output)?;
    if staging_root.exists() {
        remove_gateway_formal_backend_hermetic_execution_result_quarantine_dir_all_checked(
            &staging_root,
        )
        .map_err(GatewayFormalBackendHermeticFixtureRunnerError::Output)?;
    }
    fs::create_dir_all(
        staging_root.join("gateway-formal-backend-hermetic-execution-result-quarantine"),
    )
    .map_err(gateway_formal_backend_hermetic_fixture_runner_io_error)?;
    for (logical_path, bytes) in &files {
        let target = staging_root.join(logical_path);
        if let Some(parent) = target.parent() {
            fs::create_dir_all(parent)
                .map_err(gateway_formal_backend_hermetic_fixture_runner_io_error)?;
        }
        fs::write(&target, bytes)
            .map_err(gateway_formal_backend_hermetic_fixture_runner_io_error)?;
        fs::write(
            sidecar_path(&target),
            hash_hex(hash_bytes(bytes)).into_bytes(),
        )
        .map_err(gateway_formal_backend_hermetic_fixture_runner_io_error)?;
    }
    if output_root.exists() {
        if !request.overwrite {
            remove_gateway_formal_backend_hermetic_execution_result_quarantine_dir_all_checked(
                &staging_root,
            )
            .map_err(GatewayFormalBackendHermeticFixtureRunnerError::Output)?;
            return Err(GatewayFormalBackendHermeticFixtureRunnerError::Output(
                GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::OutputRootExistsWithoutOverwrite,
            ));
        }
        remove_gateway_formal_backend_hermetic_execution_result_quarantine_dir_all_checked(
            output_root,
        )
        .map_err(GatewayFormalBackendHermeticFixtureRunnerError::Output)?;
    }
    fs::rename(&staging_root, output_root)
        .map_err(gateway_formal_backend_hermetic_fixture_runner_io_error)?;
    let manifest = read_gateway_formal_backend_hermetic_fixture_runner_output_bundle(output_root)?;
    let report = gateway_formal_backend_hermetic_fixture_runner_report(
        interface,
        descriptor,
        descriptor_report_manifest,
        source_result_quarantine_manifest,
        &manifest,
        request,
    );
    Ok(GatewayFormalBackendHermeticFixtureRunnerOutput { manifest, report })
}

pub fn read_gateway_formal_backend_hermetic_fixture_runner_output_bundle(
    output_root: &Path,
) -> Result<
    GatewayFormalBackendHermeticExecutionResultQuarantineOutputManifest,
    GatewayFormalBackendHermeticFixtureRunnerError,
> {
    let output_metadata = fs::symlink_metadata(output_root)
        .map_err(gateway_formal_backend_hermetic_fixture_runner_io_error)?;
    if output_metadata.file_type().is_symlink() {
        return Err(GatewayFormalBackendHermeticFixtureRunnerError::Output(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::OutputRootIsSymlink,
        ));
    }
    if !output_metadata.is_dir() {
        return Err(GatewayFormalBackendHermeticFixtureRunnerError::Output(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::OutputRootIsFile,
        ));
    }
    let bundle_dir =
        output_root.join("gateway-formal-backend-hermetic-execution-result-quarantine");
    let bundle_metadata = fs::symlink_metadata(&bundle_dir)
        .map_err(gateway_formal_backend_hermetic_fixture_runner_io_error)?;
    if bundle_metadata.file_type().is_symlink() {
        return Err(GatewayFormalBackendHermeticFixtureRunnerError::Output(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::BundleFileIsSymlink(
                "gateway-formal-backend-hermetic-execution-result-quarantine".to_owned(),
            ),
        ));
    }
    if !bundle_metadata.is_dir() {
        return Err(GatewayFormalBackendHermeticFixtureRunnerError::Output(
            GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::DeclaredFileTypeMismatch(
                "gateway-formal-backend-hermetic-execution-result-quarantine".to_owned(),
            ),
        ));
    }
    reject_undeclared_gateway_formal_backend_hermetic_execution_result_quarantine_files(
        output_root,
    )
    .map_err(GatewayFormalBackendHermeticFixtureRunnerError::Output)?;
    let mut files = BTreeMap::new();
    for logical_path in
        gateway_formal_backend_hermetic_execution_result_quarantine_output_declared_files()
    {
        let path = output_root.join(&logical_path);
        let metadata = fs::symlink_metadata(&path)
            .map_err(gateway_formal_backend_hermetic_fixture_runner_io_error)?;
        if metadata.file_type().is_symlink() {
            return Err(GatewayFormalBackendHermeticFixtureRunnerError::Output(
                GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::BundleFileIsSymlink(
                    logical_path,
                ),
            ));
        }
        if !metadata.is_file() {
            return Err(GatewayFormalBackendHermeticFixtureRunnerError::Output(
                GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::DeclaredFileTypeMismatch(
                    logical_path,
                ),
            ));
        }
        let sidecar = sidecar_path(&path);
        let sidecar_metadata = fs::symlink_metadata(&sidecar)
            .map_err(gateway_formal_backend_hermetic_fixture_runner_io_error)?;
        if sidecar_metadata.file_type().is_symlink() {
            return Err(GatewayFormalBackendHermeticFixtureRunnerError::Output(
                GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::BundleFileIsSymlink(
                    sidecar
                        .strip_prefix(output_root)
                        .unwrap_or(&sidecar)
                        .to_string_lossy()
                        .replace('\\', "/"),
                ),
            ));
        }
        let bytes =
            fs::read(&path).map_err(gateway_formal_backend_hermetic_fixture_runner_io_error)?;
        let expected_digest = fs::read_to_string(&sidecar)
            .map_err(gateway_formal_backend_hermetic_fixture_runner_io_error)?;
        if expected_digest.trim() != hash_hex(hash_bytes(&bytes)) {
            return Err(GatewayFormalBackendHermeticFixtureRunnerError::Output(
                GatewayFormalBackendHermeticExecutionResultQuarantineOutputError::DigestMismatch(
                    logical_path,
                ),
            ));
        }
        files.insert(logical_path, bytes);
    }
    validate_gateway_formal_backend_hermetic_fixture_runner_bundle_semantics(&files)
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct GatewayFormalBackendHermeticFixtureProcessResult {
    process_exit_code_label: String,
    timeout: bool,
    signal: bool,
    stdout: Vec<u8>,
    stderr: Vec<u8>,
    solver_status: GatewayFormalBackendHermeticExecutionSolverStatus,
}

fn validate_gateway_formal_backend_hermetic_fixture_runner_request(
    output_root: &Path,
    request: &GatewayFormalBackendHermeticFixtureRunnerRequest,
) -> Result<(), GatewayFormalBackendHermeticFixtureRunnerError> {
    if request.run_id.trim().is_empty()
        || !is_safe_relative_path(&request.run_id)
        || request.run_id.contains(['/', '\\'])
    {
        return Err(GatewayFormalBackendHermeticFixtureRunnerError::InvalidRequest);
    }
    if !request.operator_acknowledged {
        return Err(GatewayFormalBackendHermeticFixtureRunnerError::OperatorAcknowledgementMissing);
    }
    let mut protected_roots = request.protected_roots.clone();
    if let Ok(current_dir) = std::env::current_dir() {
        protected_roots.push(current_dir);
    }
    validate_gateway_formal_backend_hermetic_execution_result_quarantine_output_root(
        output_root,
        &protected_roots,
        request.overwrite,
    )
    .map_err(GatewayFormalBackendHermeticFixtureRunnerError::Output)
}

fn run_gateway_formal_backend_hermetic_fixture_process(
    policy: &GatewayFormalBackendHermeticProcessSpawnExecutablePolicy,
) -> Result<GatewayFormalBackendHermeticFixtureProcessResult, String> {
    let executable = std::env::current_exe().map_err(|error| error.to_string())?;
    let mut command = std::process::Command::new(executable);
    command
        .args(&policy.argv_template)
        .env_clear()
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    let mut child = command.spawn().map_err(|error| error.to_string())?;
    let deadline = Instant::now() + Duration::from_millis(5_000);
    loop {
        if child
            .try_wait()
            .map_err(|error| error.to_string())?
            .is_some()
        {
            let output = child
                .wait_with_output()
                .map_err(|error| error.to_string())?;
            let process_exit_code_label = output
                .status
                .code()
                .map(|code| format!("exit_{code}"))
                .unwrap_or_else(|| "signal".to_owned());
            let signal = output.status.code().is_none();
            let solver_status = if output.status.success() {
                GatewayFormalBackendHermeticExecutionSolverStatus::FixtureProcessExited
            } else {
                GatewayFormalBackendHermeticExecutionSolverStatus::FixtureProcessFailed
            };
            return Ok(GatewayFormalBackendHermeticFixtureProcessResult {
                process_exit_code_label,
                timeout: false,
                signal,
                stdout: output.stdout,
                stderr: output.stderr,
                solver_status,
            });
        }
        if Instant::now() >= deadline {
            let _ = child.kill();
            let output = child
                .wait_with_output()
                .map_err(|error| error.to_string())?;
            return Ok(GatewayFormalBackendHermeticFixtureProcessResult {
                process_exit_code_label: "timeout".to_owned(),
                timeout: true,
                signal: false,
                stdout: output.stdout,
                stderr: output.stderr,
                solver_status:
                    GatewayFormalBackendHermeticExecutionSolverStatus::FixtureProcessTimedOut,
            });
        }
        std::thread::sleep(Duration::from_millis(5));
    }
}

