pub fn validate_gateway_formal_tiny_digest_backend_z3_accepted_append_decision_blocker_review_input(
    blocker: &GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionBlocker,
    input: &GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionBlockerReviewInput,
) -> GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionBlockerReviewValidation {
    let mut issues = Vec::new();
    if input.schema_version
        != GATEWAY_FORMAL_TINY_DIGEST_BACKEND_Z3_ACCEPTED_APPEND_DECISION_BLOCKER_REVIEW_SCHEMA_VERSION
    {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionBlockerReviewIssue::InvalidSchemaVersion,
        );
    }
    if !is_single_segment_id(&input.accepted_append_decision_blocker_review_id) {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionBlockerReviewIssue::InvalidAcceptedAppendDecisionBlockerReviewId,
        );
    }
    if !is_single_segment_id(&input.reviewer_policy_id) {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionBlockerReviewIssue::InvalidReviewerPolicyId,
        );
    }
    if !is_single_segment_id(&input.reviewer_decision_id) {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionBlockerReviewIssue::InvalidReviewerDecisionId,
        );
    }
    if !is_single_segment_id(&input.proposal_policy_id) {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionBlockerReviewIssue::InvalidProposalPolicyId,
        );
    }
    if !is_single_segment_id(&input.proposal_candidate_id) {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionBlockerReviewIssue::InvalidProposalCandidateId,
        );
    }
    if !is_single_segment_id(&input.proposal_review_id) {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionBlockerReviewIssue::InvalidProposalReviewId,
        );
    }
    if !is_single_segment_id(&input.append_preflight_id) {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionBlockerReviewIssue::InvalidAppendPreflightId,
        );
    }
    if !is_single_segment_id(&input.append_preflight_review_id) {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionBlockerReviewIssue::InvalidAppendPreflightReviewId,
        );
    }
    if !is_single_segment_id(&input.accepted_append_decision_candidate_id) {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionBlockerReviewIssue::InvalidAcceptedAppendDecisionCandidateId,
        );
    }
    if !is_single_segment_id(&input.accepted_append_decision_candidate_review_id) {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionBlockerReviewIssue::InvalidAcceptedAppendDecisionCandidateReviewId,
        );
    }
    if !is_single_segment_id(&input.accepted_append_decision_blocker_id) {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionBlockerReviewIssue::InvalidAcceptedAppendDecisionBlockerId,
        );
    }
    if input.review_decision_at_unix == 0 {
        issues.push(
            GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionBlockerReviewIssue::MissingReviewDecisionTimestamp,
        );
    }
    validate_gateway_formal_tiny_digest_backend_z3_accepted_append_decision_blocker_review_digests(
        input,
        &mut issues,
    );
    validate_gateway_formal_tiny_digest_backend_z3_accepted_append_decision_blocker_review_blocker(
        blocker,
        input,
        &mut issues,
    );
    validate_gateway_formal_tiny_digest_backend_z3_accepted_append_decision_blocker_review_policy(
        input,
        &mut issues,
    );
    GatewayFormalTinyDigestBackendZ3AcceptedAppendDecisionBlockerReviewValidation {
        valid: issues.is_empty(),
        issues,
    }
}

