pub fn validate_gateway_formal_tiny_z3_backend_execution_external_import_review_input(
    import_candidate: &GatewayFormalTinyZ3BackendExecutionExternalImportCandidate,
    input: &GatewayFormalTinyZ3BackendExecutionExternalImportReviewInput,
) -> GatewayFormalTinyZ3BackendExecutionExternalImportReviewValidation {
    let mut issues = Vec::new();
    if input.schema_version
        != GATEWAY_FORMAL_TINY_Z3_BACKEND_EXECUTION_EXTERNAL_IMPORT_REVIEW_SCHEMA_VERSION
    {
        issues.push(
            GatewayFormalTinyZ3BackendExecutionExternalImportReviewIssue::InvalidSchemaVersion,
        );
    }
    if !is_single_segment_id(&input.review_id) {
        issues.push(GatewayFormalTinyZ3BackendExecutionExternalImportReviewIssue::InvalidReviewId);
    }
    if !is_single_segment_id(&input.review_policy_id) {
        issues.push(
            GatewayFormalTinyZ3BackendExecutionExternalImportReviewIssue::InvalidReviewPolicyId,
        );
    }
    if !is_single_segment_id(&input.review_decision_id) {
        issues.push(
            GatewayFormalTinyZ3BackendExecutionExternalImportReviewIssue::InvalidReviewDecisionId,
        );
    }
    if input.review_decision_at_unix == 0 {
        issues.push(
            GatewayFormalTinyZ3BackendExecutionExternalImportReviewIssue::MissingReviewDecisionTimestamp,
        );
    }
    let expected_digests =
        gateway_formal_tiny_z3_backend_execution_external_import_review_digest_bindings(
            import_candidate,
        );
    for (label, digest) in &input.digest_bindings {
        if *digest == Hash([0; 32]) {
            issues.push(
                GatewayFormalTinyZ3BackendExecutionExternalImportReviewIssue::MissingDigest(
                    label.clone(),
                ),
            );
        }
    }
    if input.digest_bindings != expected_digests {
        issues.push(
            GatewayFormalTinyZ3BackendExecutionExternalImportReviewIssue::DigestBindingMismatch,
        );
    }
    let expected_ids = gateway_formal_tiny_z3_backend_execution_external_import_review_id_bindings(
        import_candidate,
        &input.review_id,
        &input.review_policy_id,
        &input.review_decision_id,
    );
    for (label, value) in &input.id_bindings {
        if !is_single_segment_id(value) {
            issues.push(
                GatewayFormalTinyZ3BackendExecutionExternalImportReviewIssue::InvalidIdBinding(
                    label.clone(),
                ),
            );
        }
    }
    if input.id_bindings != expected_ids {
        issues
            .push(GatewayFormalTinyZ3BackendExecutionExternalImportReviewIssue::IdBindingMismatch);
    }
    let expected_labels =
        gateway_formal_tiny_z3_backend_execution_external_import_review_label_bindings(
            import_candidate,
            &input.review_label,
        );
    if input.label_bindings != expected_labels {
        issues.push(
            GatewayFormalTinyZ3BackendExecutionExternalImportReviewIssue::LabelBindingMismatch,
        );
    }
    if import_candidate.schema_version
        != GATEWAY_FORMAL_TINY_Z3_BACKEND_EXECUTION_EXTERNAL_IMPORT_CANDIDATE_SCHEMA_VERSION
        || import_candidate.state_slice
            != GATEWAY_FORMAL_TINY_Z3_BACKEND_EXECUTION_EXTERNAL_IMPORT_CANDIDATE_STATE_SLICE
        || import_candidate.promotion_state
            != "backend_execution_external_result_import_candidate_metadata"
        || import_candidate.next_required_state
            != "backend_execution_independent_external_result_review_still_unperformed"
        || import_candidate.classification
            != GatewayFormalTinyZ3BackendExecutionExternalImportCandidateClassification::ImportCandidateQuarantinedLocalMetadata
        || import_candidate.phase549_classification
            != GatewayFormalTinyZ3BackendExecutionExternalReproductionClassification::ExternalReproductionBlockedNoIndependentRun
        || import_candidate.phase547_classification
            != GatewayFormalTinyZ3BackendExecutionLevel2EligibilityClassification::Level2BlockedLocalOnly
        || import_candidate.phase547_report_claim_boundary
            != GATEWAY_FORMAL_TINY_Z3_LEVEL2_REPORT_CLAIM_BOUNDARY
        || import_candidate.phase547_report_creates_level2_evidence
        || import_candidate.phase543_evidence_class != "LocalReplay"
        || import_candidate.phase543_claim_boundary != "Level1LocalReplay"
        || import_candidate.external_owner_id != GATEWAY_FORMAL_TINY_Z3_EXTERNAL_OWNER_ID
        || import_candidate.candidate_status != GATEWAY_FORMAL_TINY_Z3_EXTERNAL_IMPORT_CANDIDATE_STATUS
        || import_candidate.requested_claim_boundary
            != GATEWAY_FORMAL_TINY_Z3_EXTERNAL_IMPORT_REQUESTED_CLAIM_BOUNDARY
        || !import_candidate.validation_valid
        || import_candidate.validation_issue_count != 0
        || import_candidate.quarantine_status != "Quarantined"
        || import_candidate.phase541_materialized_ledger_artifact_digest == Hash([0; 32])
        || import_candidate.phase535_owner_decision_digest == Hash([0; 32])
        || import_candidate.phase533_review_digest == Hash([0; 32])
        || import_candidate.phase531_package_digest == Hash([0; 32])
        || import_candidate.phase529_result_digest == Hash([0; 32])
        || import_candidate.phase527_candidate_digest == Hash([0; 32])
        || import_candidate.writes_external_result_artifact_files
        || import_candidate.claims_independent_external_reproduction
        || import_candidate.writes_level2_artifact_files
        || import_candidate.writes_score_axis_artifact_files
        || import_candidate.populates_score_axes
        || import_candidate.creates_accepted_formal_evidence
        || import_candidate.creates_level2_evidence
        || import_candidate.proof_artifact_created
        || import_candidate.checker_transcript_created
        || import_candidate.solver_certificate_created
        || import_candidate.lean_execution_evidence_created
        || import_candidate.additional_smt_z3_execution_created
        || import_candidate.cobalt_execution_evidence_created
        || import_candidate.rust_to_lean_execution_evidence_created
        || import_candidate.backend_execution_evidence_created
        || import_candidate.benchmark_evidence_created
        || import_candidate.external_audit_evidence_created
        || import_candidate.semantic_correctness_claimed
        || import_candidate.production_readiness_claimed
        || import_candidate.sota_claimed
        || import_candidate.breakthrough_claimed
        || import_candidate.full_security_claimed
        || import_candidate.grants_authority
    {
        issues.push(
            GatewayFormalTinyZ3BackendExecutionExternalImportReviewIssue::Phase551ImportCandidateStateMismatch,
        );
    }
    let nonclaims =
        gateway_formal_tiny_z3_backend_execution_external_import_review_required_nonclaims();
    if input.explicit_nonclaims != nonclaims
        || input.explicit_nonclaims_digest
            != hash_tagged(
                "hsai-agent-admission:gateway-formal-tiny-z3-backend-execution-external-import-review-nonclaims:v1",
                &nonclaims,
            )
    {
        issues.push(GatewayFormalTinyZ3BackendExecutionExternalImportReviewIssue::NonclaimMismatch);
    }
    if input.classification
        != GatewayFormalTinyZ3BackendExecutionExternalImportReviewClassification::BackendExecutionImportReviewBlockedNoIndependentRun
    {
        issues.push(
            GatewayFormalTinyZ3BackendExecutionExternalImportReviewIssue::InvalidClassification,
        );
    }
    let blockers = gateway_formal_tiny_z3_backend_execution_external_import_review_blockers();
    if input.review_blockers != blockers
        || input.review_blocker_digest
            != hash_tagged(
                "hsai-agent-admission:gateway-formal-tiny-z3-backend-execution-external-import-review-blockers:v1",
                &blockers,
            )
    {
        issues.push(
            GatewayFormalTinyZ3BackendExecutionExternalImportReviewIssue::ReviewBlockerMismatch,
        );
    }
    let expected_nonpromotion_digest =
        gateway_formal_tiny_z3_backend_execution_external_import_review_nonpromotion_digest(
            &input.classification,
            import_candidate.digest(),
            import_candidate.candidate_digest,
            import_candidate.validation_digest,
            import_candidate.quarantine_record_digest,
            &blockers,
        );
    if input.review_nonpromotion_digest != expected_nonpromotion_digest {
        issues.push(
            GatewayFormalTinyZ3BackendExecutionExternalImportReviewIssue::ReviewNonpromotionDigestMismatch,
        );
    }
    let expected_policy_digest =
        gateway_formal_tiny_z3_backend_execution_external_import_review_policy_digest(
            &input.review_policy_id,
            &input.classification,
            import_candidate.digest(),
            import_candidate.candidate_digest,
            import_candidate.validation_digest,
            import_candidate.quarantine_record_digest,
            &blockers,
        );
    if input.review_policy_digest != expected_policy_digest {
        issues.push(
            GatewayFormalTinyZ3BackendExecutionExternalImportReviewIssue::ReviewPolicyDigestMismatch,
        );
    }
    if input.review_rules != gateway_formal_tiny_z3_backend_execution_external_import_review_rules()
    {
        issues.push(
            GatewayFormalTinyZ3BackendExecutionExternalImportReviewIssue::ReviewRulesMismatch,
        );
    }
    if input.forbidden_api_set
        != gateway_formal_tiny_z3_backend_execution_external_import_review_forbidden_apis()
    {
        issues.push(
            GatewayFormalTinyZ3BackendExecutionExternalImportReviewIssue::ForbiddenApiSetMismatch,
        );
    }
    if input.inherited_digest_requirements
        != gateway_formal_tiny_z3_backend_execution_external_import_review_inherited_digest_requirements()
    {
        issues.push(
            GatewayFormalTinyZ3BackendExecutionExternalImportReviewIssue::InheritedDigestRequirementsMismatch,
        );
    }
    if gateway_formal_real_command_lane_local_review_audit_package_text_promotes(
        &input.review_summary,
    ) {
        issues.push(
            GatewayFormalTinyZ3BackendExecutionExternalImportReviewIssue::ReviewSummaryPromotionClaim,
        );
    }
    if input.accepted_external_result_evidence_created
        || input.accepted_evidence_artifact_write_requested
        || input.independent_external_reproduction_claimed
        || input.level2_artifact_write_requested
        || input.score_axis_artifact_write_requested
        || input.score_axis_population_requested
        || input.accepted_formal_evidence_created
        || input.creates_level2_evidence
        || input.proof_artifact_promoted
        || input.checker_transcript_promoted
        || input.solver_certificate_promoted
        || input.lean_execution_evidence_created
        || input.additional_smt_z3_execution_created
        || input.cobalt_execution_evidence_created
        || input.rust_to_lean_execution_evidence_created
        || input.backend_execution_evidence_created
        || input.benchmark_evidence_created
        || input.external_audit_evidence_created
        || input.semantic_correctness_claimed
        || input.production_readiness_claimed
        || input.sota_claimed
        || input.breakthrough_claimed
        || input.full_security_claimed
        || input.action_authority_claimed
    {
        issues.push(GatewayFormalTinyZ3BackendExecutionExternalImportReviewIssue::PromotionAttempt);
    }
    GatewayFormalTinyZ3BackendExecutionExternalImportReviewValidation {
        valid: issues.is_empty(),
        issues,
    }
}

