pub fn validate_gateway_formal_tiny_z3_independent_operator_evidence_packet_input(
    requirement: &GatewayFormalTinyZ3ExternalOperatorIndependentReproductionRequirement,
    input: &GatewayFormalTinyZ3IndependentOperatorEvidencePacketInput,
) -> GatewayFormalTinyZ3IndependentOperatorEvidencePacketValidation {
    let mut issues = Vec::new();
    if input.schema_version
        != GATEWAY_FORMAL_TINY_Z3_INDEPENDENT_OPERATOR_EVIDENCE_PACKET_SCHEMA_VERSION
    {
        issues
            .push(GatewayFormalTinyZ3IndependentOperatorEvidencePacketIssue::InvalidSchemaVersion);
    }
    if !is_single_segment_id(&input.packet_id) {
        issues.push(GatewayFormalTinyZ3IndependentOperatorEvidencePacketIssue::InvalidPacketId);
    }
    if !is_single_segment_id(&input.packet_policy_id) {
        issues
            .push(GatewayFormalTinyZ3IndependentOperatorEvidencePacketIssue::InvalidPacketPolicyId);
    }
    if !is_single_segment_id(&input.packet_decision_id) {
        issues.push(
            GatewayFormalTinyZ3IndependentOperatorEvidencePacketIssue::InvalidPacketDecisionId,
        );
    }
    if input.packet_decision_at_unix == 0 {
        issues.push(
            GatewayFormalTinyZ3IndependentOperatorEvidencePacketIssue::MissingPacketDecisionTimestamp,
        );
    }
    let expected_digests =
        gateway_formal_tiny_z3_independent_operator_evidence_packet_digest_bindings(requirement);
    for (label, digest) in &input.digest_bindings {
        if *digest == Hash([0; 32]) {
            issues.push(
                GatewayFormalTinyZ3IndependentOperatorEvidencePacketIssue::MissingDigest(
                    label.clone(),
                ),
            );
        }
    }
    if input.digest_bindings != expected_digests {
        issues
            .push(GatewayFormalTinyZ3IndependentOperatorEvidencePacketIssue::DigestBindingMismatch);
    }
    let expected_ids = gateway_formal_tiny_z3_independent_operator_evidence_packet_id_bindings(
        requirement,
        &input.packet_id,
        &input.packet_policy_id,
        &input.packet_decision_id,
    );
    for (label, value) in &input.id_bindings {
        if !is_single_segment_id(value) {
            issues.push(
                GatewayFormalTinyZ3IndependentOperatorEvidencePacketIssue::InvalidIdBinding(
                    label.clone(),
                ),
            );
        }
    }
    if input.id_bindings != expected_ids {
        issues.push(GatewayFormalTinyZ3IndependentOperatorEvidencePacketIssue::IdBindingMismatch);
    }
    let expected_labels =
        gateway_formal_tiny_z3_independent_operator_evidence_packet_label_bindings(
            requirement,
            &input.packet_label,
        );
    if input.label_bindings != expected_labels {
        issues
            .push(GatewayFormalTinyZ3IndependentOperatorEvidencePacketIssue::LabelBindingMismatch);
    }
    if gateway_formal_tiny_z3_independent_operator_evidence_packet_phase569_state_invalid(
        requirement,
    ) {
        issues.push(
            GatewayFormalTinyZ3IndependentOperatorEvidencePacketIssue::Phase569RequirementStateMismatch,
        );
    }
    let nonclaims =
        gateway_formal_tiny_z3_independent_operator_evidence_packet_required_nonclaims();
    if input.explicit_nonclaims != nonclaims
        || input.explicit_nonclaims_digest
            != hash_tagged(
                "hsai-agent-admission:gateway-formal-tiny-z3-independent-operator-evidence-packet-nonclaims:v1",
                &nonclaims,
            )
    {
        issues.push(GatewayFormalTinyZ3IndependentOperatorEvidencePacketIssue::NonclaimMismatch);
    }
    if input.classification
        != GatewayFormalTinyZ3IndependentOperatorEvidencePacketClassification::IndependentOperatorEvidencePacketMissing
    {
        issues.push(
            GatewayFormalTinyZ3IndependentOperatorEvidencePacketIssue::InvalidClassification,
        );
    }
    let blockers = gateway_formal_tiny_z3_independent_operator_evidence_packet_blockers();
    if input.packet_blockers != blockers
        || input.packet_blocker_digest
            != hash_tagged(
                "hsai-agent-admission:gateway-formal-tiny-z3-independent-operator-evidence-packet-blockers:v1",
                &blockers,
            )
    {
        issues
            .push(GatewayFormalTinyZ3IndependentOperatorEvidencePacketIssue::PacketBlockerMismatch);
    }
    let expected_role_digests =
        gateway_formal_tiny_z3_independent_operator_evidence_packet_role_digests(&input.packet_id);
    let expected_role_manifest_digest = hash_tagged(
        "hsai-agent-admission:gateway-formal-tiny-z3-independent-operator-evidence-packet-role-manifest:v1",
        &expected_role_digests,
    );
    if input.packet_role_digests != expected_role_digests
        || input.packet_role_manifest_digest != expected_role_manifest_digest
    {
        issues.push(
            GatewayFormalTinyZ3IndependentOperatorEvidencePacketIssue::PacketRoleDigestMismatch,
        );
    }
    let expected_nonpromotion_digest =
        gateway_formal_tiny_z3_independent_operator_evidence_packet_nonpromotion_digest(
            &input.classification,
            requirement.digest(),
            requirement.requirement_policy_digest,
            requirement.requirement_nonpromotion_digest,
            &blockers,
            &expected_role_digests,
        );
    if input.packet_nonpromotion_digest != expected_nonpromotion_digest {
        issues.push(
            GatewayFormalTinyZ3IndependentOperatorEvidencePacketIssue::PacketNonpromotionDigestMismatch,
        );
    }
    let expected_policy_digest =
        gateway_formal_tiny_z3_independent_operator_evidence_packet_policy_digest(
            &input.packet_policy_id,
            &input.classification,
            requirement.digest(),
            requirement.requirement_policy_digest,
            requirement.requirement_nonpromotion_digest,
            &blockers,
            &expected_role_digests,
        );
    if input.packet_policy_digest != expected_policy_digest {
        issues.push(
            GatewayFormalTinyZ3IndependentOperatorEvidencePacketIssue::PacketPolicyDigestMismatch,
        );
    }
    if input.packet_rules != gateway_formal_tiny_z3_independent_operator_evidence_packet_rules() {
        issues.push(GatewayFormalTinyZ3IndependentOperatorEvidencePacketIssue::PacketRulesMismatch);
    }
    if input.forbidden_api_set
        != gateway_formal_tiny_z3_independent_operator_evidence_packet_forbidden_apis()
    {
        issues.push(
            GatewayFormalTinyZ3IndependentOperatorEvidencePacketIssue::ForbiddenApiSetMismatch,
        );
    }
    if input.inherited_digest_requirements
        != gateway_formal_tiny_z3_independent_operator_evidence_packet_inherited_digest_requirements(
        )
    {
        issues.push(
            GatewayFormalTinyZ3IndependentOperatorEvidencePacketIssue::InheritedDigestRequirementsMismatch,
        );
    }
    if gateway_formal_real_command_lane_local_review_audit_package_text_promotes(
        &input.packet_summary,
    ) {
        issues.push(
            GatewayFormalTinyZ3IndependentOperatorEvidencePacketIssue::PacketSummaryPromotionClaim,
        );
    }
    if input.operator_identity_present
        || input.operator_statement_present
        || input.environment_declaration_present
        || input.captured_output_summary_present
        || input.redaction_report_present
        || input.replay_correspondence_present
        || input.import_ownership_present
        || input.packet_materialized
    {
        issues.push(
            GatewayFormalTinyZ3IndependentOperatorEvidencePacketIssue::PacketRolePresenceAttempt,
        );
    }
    if input.external_result_import_created
        || input.accepted_external_result_evidence_created
        || input.accepted_evidence_artifact_write_requested
        || input.accepted_evidence_ledger_mutation_requested
        || input.independent_external_reproduction_accepted
        || input.level2_artifact_write_requested
        || input.score_axis_artifact_write_requested
        || input.score_axis_population_requested
        || input.accepted_formal_evidence_created
        || input.creates_level2_evidence
        || input.proof_artifact_promoted
        || input.checker_transcript_promoted
        || input.solver_certificate_promoted
        || input.lean_execution_evidence_created
        || input.additional_smt_z3_execution_created
        || input.cobalt_execution_evidence_created
        || input.rust_to_lean_execution_evidence_created
        || input.backend_execution_evidence_created
        || input.benchmark_evidence_created
        || input.external_audit_evidence_created
        || input.semantic_correctness_claimed
        || input.production_readiness_claimed
        || input.sota_claimed
        || input.breakthrough_claimed
        || input.full_security_claimed
        || input.action_authority_claimed
    {
        issues.push(GatewayFormalTinyZ3IndependentOperatorEvidencePacketIssue::PromotionAttempt);
    }
    GatewayFormalTinyZ3IndependentOperatorEvidencePacketValidation {
        valid: issues.is_empty(),
        issues,
    }
}

fn gateway_formal_tiny_z3_independent_operator_evidence_packet_phase569_state_invalid(
    requirement: &GatewayFormalTinyZ3ExternalOperatorIndependentReproductionRequirement,
) -> bool {
    requirement.schema_version
        != GATEWAY_FORMAL_TINY_Z3_EXTERNAL_OPERATOR_INDEPENDENT_REPRODUCTION_REQUIREMENT_SCHEMA_VERSION
        || requirement.state_slice
            != GATEWAY_FORMAL_TINY_Z3_EXTERNAL_OPERATOR_INDEPENDENT_REPRODUCTION_REQUIREMENT_STATE_SLICE
        || requirement.promotion_state
            != "external_operator_independent_reproduction_requirement_metadata"
        || requirement.next_required_state != "operator_independent_reproduction_evidence_still_required"
        || requirement.classification
            != GatewayFormalTinyZ3ExternalOperatorIndependentReproductionRequirementClassification::IndependentReproductionEvidenceBlocked
        || requirement.phase569_required_digest_missing()
        || requirement.phase567_classification
            != GatewayFormalTinyZ3ExternalOperatorAcceptedResultPolicyResolutionClassification::AcceptedResultPolicyResolutionBlocked
        || requirement.phase565_classification
            != GatewayFormalTinyZ3ExternalOperatorAcceptedResultEligibilityClassification::OperatorCaptureAcceptedResultBlockedPolicyNotSatisfied
        || !requirement.phase561_validation_valid
        || requirement.phase561_validation_issue_count != 0
        || requirement.phase561_quarantine_status != "Quarantined"
        || !requirement.phase555_manual_handoff_validation_valid
        || requirement.phase555_manual_handoff_validation_issue_count != 0
        || requirement.claim_boundary
            != gateway_formal_tiny_z3_external_operator_independent_reproduction_requirement_claim_boundary()
        || requirement.independent_operator_identity_present
        || requirement.operator_statement_present
        || requirement.environment_declaration_present
        || requirement.captured_output_summary_present
        || requirement.redaction_report_present
        || requirement.replay_correspondence_present
        || requirement.import_ownership_bound
        || requirement.imports_external_result
        || requirement.creates_accepted_external_result_evidence
        || requirement.writes_accepted_evidence_artifacts
        || requirement.mutates_accepted_evidence_ledger
        || requirement.accepts_independent_external_reproduction
        || requirement.writes_level2_artifact_files
        || requirement.writes_score_axis_artifact_files
        || requirement.populates_score_axes
        || requirement.creates_accepted_formal_evidence
        || requirement.creates_level2_evidence
        || requirement.proof_artifact_created
        || requirement.checker_transcript_created
        || requirement.solver_certificate_created
        || requirement.lean_execution_evidence_created
        || requirement.additional_smt_z3_execution_created
        || requirement.cobalt_execution_evidence_created
        || requirement.rust_to_lean_execution_evidence_created
        || requirement.backend_execution_evidence_created
        || requirement.benchmark_evidence_created
        || requirement.external_audit_evidence_created
        || requirement.semantic_correctness_claimed
        || requirement.production_readiness_claimed
        || requirement.sota_claimed
        || requirement.breakthrough_claimed
        || requirement.full_security_claimed
        || requirement.grants_authority
}

impl GatewayFormalTinyZ3ExternalOperatorIndependentReproductionRequirement {
    fn phase569_required_digest_missing(&self) -> bool {
        [
            self.requirement_input_digest,
            self.phase567_resolution_digest,
            self.phase567_resolution_input_digest,
            self.phase567_digest_binding_map_digest,
            self.phase567_id_binding_map_digest,
            self.phase567_label_binding_map_digest,
            self.phase567_resolution_blocker_digest,
            self.phase567_resolution_policy_digest,
            self.phase567_resolution_nonpromotion_digest,
            self.phase565_eligibility_digest,
            self.phase565_eligibility_input_digest,
            self.phase563_import_review_digest,
            self.phase561_import_candidate_digest,
            self.phase559_capture_manifest_digest,
            self.phase557_handoff_packet_manifest_digest,
            self.phase555_manual_handoff_bundle_digest,
            self.phase555_manual_handoff_validation_digest,
            self.requirement_policy_digest,
            self.requirement_blocker_digest,
            self.requirement_nonpromotion_digest,
            self.required_operator_identity_digest,
            self.required_operator_statement_digest,
            self.required_environment_declaration_digest,
            self.required_captured_output_summary_digest,
            self.required_redaction_report_digest,
            self.required_replay_correspondence_digest,
            self.required_import_ownership_digest,
            self.requirement_rules_digest,
            self.forbidden_api_set_digest,
            self.inherited_digest_requirements_digest,
        ]
        .into_iter()
        .any(|digest| digest == Hash([0; 32]))
    }
}

