fn validate_gateway_formal_real_command_lane_local_reviewed_metadata_digests(
    input: &GatewayFormalRealCommandLaneLocalReviewedFormalEvidenceMetadataInput,
    issues: &mut Vec<GatewayFormalRealCommandLaneLocalReviewedFormalEvidenceMetadataIssue>,
) {
    for (label, digest) in [
        ("class_policy_digest", input.class_policy_digest),
        ("class_policy_input_digest", input.class_policy_input_digest),
        ("feasibility_digest", input.feasibility_digest),
        ("policy_decision_digest", input.policy_decision_digest),
        ("handoff_digest", input.handoff_digest),
        ("reviewed_record_digest", input.reviewed_record_digest),
        (
            "current_accepted_append_blockers_digest",
            input.current_accepted_append_blockers_digest,
        ),
        ("reviewed_scope_digest", input.reviewed_scope_digest),
        (
            "source_correspondence_requirement_digest",
            input.source_correspondence_requirement_digest,
        ),
        ("replay_requirement_digest", input.replay_requirement_digest),
        ("reviewer_policy_digest", input.reviewer_policy_digest),
        ("explicit_nonclaims_digest", input.explicit_nonclaims_digest),
    ] {
        if digest == Hash([0; 32]) {
            issues.push(
                GatewayFormalRealCommandLaneLocalReviewedFormalEvidenceMetadataIssue::MissingDigest(
                    label.to_owned(),
                ),
            );
        }
    }
}

fn validate_gateway_formal_real_command_lane_local_reviewed_metadata_class_policy(
    class_policy: &GatewayFormalRealCommandLaneLocalNonAcceptedClassPolicy,
    input: &GatewayFormalRealCommandLaneLocalReviewedFormalEvidenceMetadataInput,
    issues: &mut Vec<GatewayFormalRealCommandLaneLocalReviewedFormalEvidenceMetadataIssue>,
) {
    if input.class_policy_digest != class_policy.digest()
        || input.class_policy_input_digest != class_policy.policy_input_digest
        || input.feasibility_digest != class_policy.feasibility_digest
        || input.policy_decision_digest != class_policy.policy_decision_digest
        || input.handoff_digest != class_policy.handoff_digest
        || input.reviewed_record_digest != class_policy.reviewed_record_digest
    {
        issues.push(
            GatewayFormalRealCommandLaneLocalReviewedFormalEvidenceMetadataIssue::ClassPolicyDigestDrift,
        );
    }
    if class_policy.schema_version
        != GATEWAY_FORMAL_REAL_COMMAND_LANE_LOCAL_NON_ACCEPTED_CLASS_POLICY_SCHEMA_VERSION
        || class_policy.state_slice
            != GATEWAY_FORMAL_REAL_COMMAND_LANE_LOCAL_NON_ACCEPTED_CLASS_POLICY_STATE_SLICE
        || class_policy.promotion_state != "local_non_accepted_class_policy_metadata"
        || class_policy.next_required_state
            != "local_reviewed_formal_evidence_metadata_class_boundary"
        || class_policy.claim_boundary
            != gateway_formal_real_command_lane_local_non_accepted_class_policy_claim_boundary()
        || class_policy.class_name
            != GATEWAY_FORMAL_REAL_COMMAND_LANE_BOUNDED_FORMAL_EVIDENCE_FEASIBILITY_CANDIDATE_CLASS
        || class_policy.owner_path
            != GATEWAY_FORMAL_REAL_COMMAND_LANE_LOCAL_NON_ACCEPTED_CLASS_POLICY_OWNER_PATH
        || class_policy.class_status
            != GATEWAY_FORMAL_REAL_COMMAND_LANE_LOCAL_NON_ACCEPTED_CLASS_POLICY_CLASS_STATUS
        || class_policy.creates_accepted_evidence
        || class_policy.changes_accepted_append_policy
        || class_policy.implements_bounded_formal_evidence_class
        || class_policy.creates_level2_evidence
        || class_policy.populates_score_axes
        || class_policy.proof_artifact_created
        || class_policy.checker_transcript_created
        || class_policy.solver_certificate_created
        || class_policy.semantic_correctness_claimed
        || class_policy.production_readiness_claimed
        || class_policy.sota_claimed
        || class_policy.breakthrough_claimed
        || class_policy.full_security_claimed
        || class_policy.grants_authority
    {
        issues.push(
            GatewayFormalRealCommandLaneLocalReviewedFormalEvidenceMetadataIssue::ClassPolicyStateMismatch,
        );
    }
}

fn validate_gateway_formal_real_command_lane_local_reviewed_metadata_policy(
    input: &GatewayFormalRealCommandLaneLocalReviewedFormalEvidenceMetadataInput,
    issues: &mut Vec<GatewayFormalRealCommandLaneLocalReviewedFormalEvidenceMetadataIssue>,
) {
    let blockers = gateway_formal_real_command_lane_accepted_handoff_current_blockers();
    if input.current_accepted_append_blockers != blockers
        || input.current_accepted_append_blockers_digest
            != hash_tagged(
                "hsai-agent-admission:gateway-formal-real-command-lane-accepted-handoff-current-blockers:v1",
                &blockers,
            )
    {
        issues.push(
            GatewayFormalRealCommandLaneLocalReviewedFormalEvidenceMetadataIssue::AcceptedAppendBlockerMismatch,
        );
    }
    if input.class_name
        != GATEWAY_FORMAL_REAL_COMMAND_LANE_BOUNDED_FORMAL_EVIDENCE_FEASIBILITY_CANDIDATE_CLASS
    {
        issues.push(
            GatewayFormalRealCommandLaneLocalReviewedFormalEvidenceMetadataIssue::ClassNameMismatch,
        );
    }
    if input.owner_path
        != GATEWAY_FORMAL_REAL_COMMAND_LANE_LOCAL_NON_ACCEPTED_CLASS_POLICY_OWNER_PATH
    {
        issues.push(
            GatewayFormalRealCommandLaneLocalReviewedFormalEvidenceMetadataIssue::OwnerPathMismatch,
        );
    }
    if input.class_status
        != GATEWAY_FORMAL_REAL_COMMAND_LANE_LOCAL_NON_ACCEPTED_CLASS_POLICY_CLASS_STATUS
    {
        issues.push(
            GatewayFormalRealCommandLaneLocalReviewedFormalEvidenceMetadataIssue::ClassStatusMismatch,
        );
    }
    let requirement_digests =
        gateway_formal_real_command_lane_local_non_accepted_class_policy_requirement_digests();
    if input.source_correspondence_requirement_digest
        != requirement_digests["source_correspondence_requirement"]
        || input.replay_requirement_digest != requirement_digests["replay_requirement"]
        || input.reviewer_policy_digest != requirement_digests["reviewer_policy_requirement"]
    {
        issues.push(
            GatewayFormalRealCommandLaneLocalReviewedFormalEvidenceMetadataIssue::RequirementDigestMismatch,
        );
    }
    let nonclaims = gateway_formal_real_command_lane_local_reviewed_metadata_required_nonclaims();
    if input.explicit_nonclaims != nonclaims
        || input.explicit_nonclaims_digest
            != hash_tagged(
                "hsai-agent-admission:gateway-formal-real-command-lane-local-reviewed-formal-evidence-metadata-nonclaims:v1",
                &nonclaims,
            )
    {
        issues.push(
            GatewayFormalRealCommandLaneLocalReviewedFormalEvidenceMetadataIssue::NonclaimMismatch,
        );
    }
    if input.accepted_evidence_mutation_requested
        || input.accepted_append_policy_change_requested
        || input.accepted_formal_evidence_created
        || input.creates_level2_evidence
        || input.populates_score_axes
        || input.proof_artifact_promoted
        || input.checker_transcript_promoted
        || input.solver_certificate_promoted
        || input.benchmark_or_sota_comparison_claimed
        || input.semantic_correctness_claimed
        || input.production_readiness_claimed
        || input.sota_claimed
        || input.breakthrough_claimed
        || input.full_security_claimed
        || input.action_authority_claimed
    {
        issues.push(
            GatewayFormalRealCommandLaneLocalReviewedFormalEvidenceMetadataIssue::PromotionAttempt,
        );
    }
}

