fn validate_gateway_formal_real_command_lane_accepted_evidence_proposal_candidate_review(
    review: &GatewayFormalRealCommandLaneLocalAuditPackageReview,
    input: &GatewayFormalRealCommandLaneAcceptedEvidenceProposalCandidateInput,
    issues: &mut Vec<GatewayFormalRealCommandLaneAcceptedEvidenceProposalCandidateIssue>,
) {
    if input.phase355_review_digest != review.digest()
        || input.phase355_review_input_digest != review.review_input_digest
        || input.phase353_materialized_manifest_digest
            != review.materialized_package_manifest_digest
        || input.phase351_review_digest != review.phase351_review_digest
        || input.phase349_serialization_preview_digest
            != review.phase349_serialization_preview_digest
        || input.phase347_audit_package_digest != review.phase347_audit_package_digest
        || input.phase345_review_record_digest != review.phase345_review_record_digest
        || input.phase343_metadata_digest != review.phase343_metadata_digest
        || input.declared_file_digest_map_digest != review.declared_file_digest_map_digest
        || input.current_accepted_append_blockers_digest
            != review.current_accepted_append_blockers_digest
    {
        issues.push(
            GatewayFormalRealCommandLaneAcceptedEvidenceProposalCandidateIssue::Phase355ReviewDigestDrift,
        );
    }
    if review.schema_version
        != GATEWAY_FORMAL_REAL_COMMAND_LANE_LOCAL_AUDIT_PACKAGE_REVIEW_SCHEMA_VERSION
        || review.state_slice
            != GATEWAY_FORMAL_REAL_COMMAND_LANE_LOCAL_AUDIT_PACKAGE_REVIEW_STATE_SLICE
        || review.promotion_state != "local_materialized_audit_package_review_metadata"
        || review.next_required_state != "accepted_evidence_proposal_still_blocked"
        || review.claim_boundary
            != gateway_formal_real_command_lane_local_audit_package_review_claim_boundary()
        || review.creates_accepted_evidence
        || review.changes_accepted_append_policy
        || review.creates_level2_evidence
        || review.populates_score_axes
        || review.proof_artifact_created
        || review.checker_transcript_created
        || review.solver_certificate_created
        || review.semantic_correctness_claimed
        || review.production_readiness_claimed
        || review.sota_claimed
        || review.breakthrough_claimed
        || review.full_security_claimed
        || review.grants_authority
    {
        issues.push(
            GatewayFormalRealCommandLaneAcceptedEvidenceProposalCandidateIssue::Phase355ReviewStateMismatch,
        );
    }
}

fn validate_gateway_formal_real_command_lane_accepted_evidence_proposal_candidate_policy(
    input: &GatewayFormalRealCommandLaneAcceptedEvidenceProposalCandidateInput,
    issues: &mut Vec<GatewayFormalRealCommandLaneAcceptedEvidenceProposalCandidateIssue>,
) {
    let blockers = gateway_formal_real_command_lane_accepted_handoff_current_blockers();
    if input.current_accepted_append_blockers_digest
        != hash_tagged(
            "hsai-agent-admission:gateway-formal-real-command-lane-accepted-handoff-current-blockers:v1",
            &blockers,
        )
    {
        issues.push(
            GatewayFormalRealCommandLaneAcceptedEvidenceProposalCandidateIssue::AcceptedAppendBlockerMismatch,
        );
    }
    let nonclaims =
        gateway_formal_real_command_lane_accepted_evidence_proposal_candidate_required_nonclaims();
    if input.explicit_nonclaims != nonclaims
        || input.explicit_nonclaims_digest
            != hash_tagged(
                "hsai-agent-admission:gateway-formal-real-command-lane-accepted-evidence-proposal-candidate-nonclaims:v1",
                &nonclaims,
            )
    {
        issues.push(
            GatewayFormalRealCommandLaneAcceptedEvidenceProposalCandidateIssue::NonclaimMismatch,
        );
    }
    if gateway_formal_real_command_lane_local_review_audit_package_text_promotes(
        &input.candidate_summary,
    ) {
        issues.push(
            GatewayFormalRealCommandLaneAcceptedEvidenceProposalCandidateIssue::CandidateSummaryPromotionClaim,
        );
    }
    if input.accepted_evidence_mutation_requested
        || input.accepted_append_policy_change_requested
        || input.accepted_formal_evidence_created
        || input.creates_level2_evidence
        || input.populates_score_axes
        || input.proof_artifact_promoted
        || input.checker_transcript_promoted
        || input.solver_certificate_promoted
        || input.benchmark_or_sota_comparison_claimed
        || input.semantic_correctness_claimed
        || input.production_readiness_claimed
        || input.sota_claimed
        || input.breakthrough_claimed
        || input.full_security_claimed
        || input.action_authority_claimed
    {
        issues.push(
            GatewayFormalRealCommandLaneAcceptedEvidenceProposalCandidateIssue::PromotionAttempt,
        );
    }
}

