fn validate_gateway_formal_real_command_lane_execution_preflight_manifest(
    manifest: &GatewayFormalRealCommandLaneOutputManifest,
    command_request: &GatewayFormalRealCommandLaneRequest,
    input: &GatewayFormalRealCommandLaneExecutionPreflightInput,
    issues: &mut Vec<GatewayFormalRealCommandLaneExecutionPreflightIssue>,
) {
    if input.phase323_manifest_digest != manifest.digest()
        || manifest.schema_version != GATEWAY_FORMAL_REAL_COMMAND_LANE_OUTPUT_SCHEMA_VERSION
        || manifest.state_slice != GATEWAY_FORMAL_REAL_COMMAND_LANE_STATE_SLICE
        || manifest.request_digest != command_request.digest()
        || manifest.command_descriptor_digest != input.command_descriptor_digest
        || manifest.obligation_digest != input.obligation_digest
        || manifest.claim_boundary != gateway_formal_real_command_lane_claim_boundary()
    {
        issues.push(GatewayFormalRealCommandLaneExecutionPreflightIssue::ManifestDrift);
    }
    if manifest.process_spawned
        || manifest.backend_executed
        || manifest.proof_artifact_created
        || manifest.checker_transcript_created
        || manifest.solver_certificate_created
        || manifest.creates_accepted_evidence
        || manifest.creates_level2_evidence
        || manifest.populates_score_axes
        || manifest.semantic_correctness_claimed
        || manifest.production_readiness_claimed
        || manifest.sota_claimed
        || manifest.breakthrough_claimed
        || manifest.full_security_claimed
        || manifest.grants_authority
    {
        issues.push(GatewayFormalRealCommandLaneExecutionPreflightIssue::PromotionAttempt);
    }
}

fn validate_gateway_formal_real_command_lane_execution_preflight_command_request(
    command_request: &GatewayFormalRealCommandLaneRequest,
    input: &GatewayFormalRealCommandLaneExecutionPreflightInput,
    issues: &mut Vec<GatewayFormalRealCommandLaneExecutionPreflightIssue>,
) {
    if input.command_request_digest != command_request.digest() {
        issues.push(GatewayFormalRealCommandLaneExecutionPreflightIssue::CommandRequestDigestDrift);
    }
    if input.obligation_digest != command_request.obligation_digest {
        issues.push(GatewayFormalRealCommandLaneExecutionPreflightIssue::ObligationDigestDrift);
    }
    if input.expected_output_grammar_digest != command_request.expected_output_grammar_digest {
        issues.push(
            GatewayFormalRealCommandLaneExecutionPreflightIssue::ExpectedOutputGrammarDigestDrift,
        );
    }
    if !input.operator_acknowledged || !command_request.operator_acknowledged {
        issues.push(
            GatewayFormalRealCommandLaneExecutionPreflightIssue::MissingOperatorAcknowledgement,
        );
    }
}

fn validate_gateway_formal_real_command_lane_execution_preflight_command(
    command: &GatewayFormalRealCommandLaneCommandDescriptor,
    input: &GatewayFormalRealCommandLaneExecutionPreflightInput,
    issues: &mut Vec<GatewayFormalRealCommandLaneExecutionPreflightIssue>,
) {
    if input.command_descriptor_digest != command.digest() {
        issues.push(
            GatewayFormalRealCommandLaneExecutionPreflightIssue::CommandDescriptorDigestDrift,
        );
    }
    if input.executable_digest == Hash([0; 32]) {
        issues.push(GatewayFormalRealCommandLaneExecutionPreflightIssue::MissingExecutableDigest);
    }
    if input.executable_policy_id != command.executable_policy_id
        || !command.fixed_executable_policy
        || command.executable_policy_id.trim().is_empty()
    {
        issues.push(GatewayFormalRealCommandLaneExecutionPreflightIssue::ExecutablePolicyMismatch);
    }
    if input.fixed_executable_label != command.executable_path_label
        || command.executable_path_label.trim().is_empty()
        || command.executable_path_label.starts_with('/')
        || !is_safe_relative_path(&command.executable_path_label)
    {
        issues.push(
            GatewayFormalRealCommandLaneExecutionPreflightIssue::FixedExecutableLabelMismatch,
        );
    }
    if command.caller_executable_path_allowed {
        issues
            .push(GatewayFormalRealCommandLaneExecutionPreflightIssue::CallerExecutablePathAllowed);
    }
    if command.caller_argv_allowed || !command.fixed_argv_template {
        issues.push(GatewayFormalRealCommandLaneExecutionPreflightIssue::CallerArgvAllowed);
    }
    if command.command_kind != "direct_process_no_shell"
        || !command.direct_process_no_shell
        || !command.no_shell
        || has_shell_metacharacters(&command.executable_path_label)
        || command
            .argv_template
            .iter()
            .any(|arg| has_shell_metacharacters(arg))
    {
        issues.push(GatewayFormalRealCommandLaneExecutionPreflightIssue::ShellFragment);
    }
    if command.inherit_environment || !command.environment_variables.is_empty() {
        issues.push(GatewayFormalRealCommandLaneExecutionPreflightIssue::InheritedEnvironment);
    }
    if !command.no_stdin {
        issues.push(GatewayFormalRealCommandLaneExecutionPreflightIssue::StdinAllowed);
    }
    if !command.no_network {
        issues.push(GatewayFormalRealCommandLaneExecutionPreflightIssue::NetworkAllowed);
    }
}

fn validate_gateway_formal_real_command_lane_execution_preflight_paths(
    input: &GatewayFormalRealCommandLaneExecutionPreflightInput,
    issues: &mut Vec<GatewayFormalRealCommandLaneExecutionPreflightIssue>,
) {
    if input.output_root_label.trim().is_empty()
        || !is_safe_relative_path(&input.output_root_label)
        || path_label_is_protected(&input.output_root_label)
    {
        issues.push(GatewayFormalRealCommandLaneExecutionPreflightIssue::ProtectedOutputRoot);
    }
    if input.accepted_evidence_path_requested {
        issues.push(
            GatewayFormalRealCommandLaneExecutionPreflightIssue::AcceptedEvidencePathRequested,
        );
    }
    if input.level2_evidence_path_requested {
        issues
            .push(GatewayFormalRealCommandLaneExecutionPreflightIssue::Level2EvidencePathRequested);
    }
    if input.score_axis_path_requested {
        issues.push(GatewayFormalRealCommandLaneExecutionPreflightIssue::ScoreAxisPathRequested);
    }
    if input.benchmark_output_path_requested {
        issues.push(
            GatewayFormalRealCommandLaneExecutionPreflightIssue::BenchmarkOutputPathRequested,
        );
    }
    if input.proof_promotion_path_requested {
        issues
            .push(GatewayFormalRealCommandLaneExecutionPreflightIssue::ProofPromotionPathRequested);
    }
}

#[allow(clippy::too_many_arguments)]
pub fn build_gateway_formal_real_command_lane_output_contract(
    created_at_unix: u64,
    source_adapter_manifest: &GatewayFormalBackendTinyHermeticAdapterOutputManifest,
    source_execution_manifest: &GatewayFormalBackendTinyHermeticExecutionOutputManifest,
    request: &GatewayFormalRealCommandLaneRequest,
    command: &GatewayFormalRealCommandLaneCommandDescriptor,
    obligation: &GatewayFormalRealCommandLaneObligation,
    obligation_binding: &GatewayFormalRealCommandLaneObligationBinding,
    transcript: &GatewayFormalRealCommandLaneTranscript,
    stdout_summary: &GatewayFormalRealCommandLaneBoundedSummary,
    stderr_summary: &GatewayFormalRealCommandLaneBoundedSummary,
    solver_verdict: &GatewayFormalRealCommandLaneSolverVerdict,
    nonpromotion: &GatewayFormalRealCommandLaneNonpromotionReport,
) -> GatewayFormalRealCommandLaneOutputContract {
    let validation = validate_gateway_formal_real_command_lane(
        source_adapter_manifest,
        source_execution_manifest,
        request,
        command,
        obligation,
        obligation_binding,
        transcript,
        stdout_summary,
        stderr_summary,
        solver_verdict,
        nonpromotion,
    );
    let redaction_report =
        gateway_formal_real_command_lane_redaction_report(stdout_summary, stderr_summary);
    let validation_report = GatewayFormalRealCommandLaneValidationReport {
        schema_version: GATEWAY_FORMAL_REAL_COMMAND_LANE_OUTPUT_SCHEMA_VERSION.to_owned(),
        run_id: request.run_id.clone(),
        valid: validation.valid,
        issue_count: validation.issues.len() as u64,
        checked_files: gateway_formal_real_command_lane_declared_files(),
        request_digest: request.digest(),
        source_adapter_manifest_digest: source_adapter_manifest.digest(),
        source_execution_manifest_digest: source_execution_manifest.digest(),
        command_descriptor_digest: command.digest(),
        obligation_digest: obligation.digest(),
        obligation_binding_digest: obligation_binding.digest(),
        transcript_digest: transcript.digest(),
        solver_verdict_digest: solver_verdict.digest(),
        stdout_summary_digest: stdout_summary.digest(),
        stderr_summary_digest: stderr_summary.digest(),
        redaction_report_digest: redaction_report.digest(),
        nonpromotion_report_digest: nonpromotion.digest(),
        claim_boundary: gateway_formal_real_command_lane_claim_boundary(),
        process_spawned: false,
        backend_executed: false,
        creates_accepted_evidence: false,
        creates_level2_evidence: false,
        populates_score_axes: false,
        grants_authority: false,
    };
    let manifest = GatewayFormalRealCommandLaneOutputManifest {
        schema_version: GATEWAY_FORMAL_REAL_COMMAND_LANE_OUTPUT_SCHEMA_VERSION.to_owned(),
        run_id: request.run_id.clone(),
        state_slice: GATEWAY_FORMAL_REAL_COMMAND_LANE_STATE_SLICE.to_owned(),
        created_at_unix,
        request_digest: request.digest(),
        source_adapter_manifest_digest: source_adapter_manifest.digest(),
        source_execution_manifest_digest: source_execution_manifest.digest(),
        command_descriptor_digest: command.digest(),
        obligation_digest: obligation.digest(),
        obligation_binding_digest: obligation_binding.digest(),
        transcript_digest: transcript.digest(),
        solver_verdict_digest: solver_verdict.digest(),
        stdout_summary_digest: stdout_summary.digest(),
        stderr_summary_digest: stderr_summary.digest(),
        redaction_report_digest: redaction_report.digest(),
        nonpromotion_report_digest: nonpromotion.digest(),
        validation_report_digest: validation_report.digest(),
        backend_id: request.backend_id.clone(),
        backend_mode: request.backend_mode.clone(),
        property_id: request.property_id.clone(),
        declared_files: gateway_formal_real_command_lane_declared_files(),
        declared_sidecars: gateway_formal_real_command_lane_declared_sidecars(),
        declared_file_digests: gateway_formal_real_command_lane_declared_file_digests(
            source_execution_manifest,
            request,
            command,
            obligation,
            obligation_binding,
            transcript,
            stdout_summary,
            stderr_summary,
            solver_verdict,
            nonpromotion,
            &validation_report,
        ),
        claim_boundary: gateway_formal_real_command_lane_claim_boundary(),
        process_spawned: false,
        backend_executed: false,
        proof_artifact_created: false,
        checker_transcript_created: false,
        solver_certificate_created: false,
        creates_accepted_evidence: false,
        creates_level2_evidence: false,
        populates_score_axes: false,
        semantic_correctness_claimed: false,
        production_readiness_claimed: false,
        sota_claimed: false,
        breakthrough_claimed: false,
        full_security_claimed: false,
        grants_authority: false,
        raw_logs_retained: false,
        raw_provider_response_retained: false,
        nonclaims: request.required_nonclaims.clone(),
    };
    GatewayFormalRealCommandLaneOutputContract {
        manifest,
        validation_report,
    }
}

#[allow(clippy::too_many_arguments)]
pub fn validate_gateway_formal_real_command_lane(
    source_adapter_manifest: &GatewayFormalBackendTinyHermeticAdapterOutputManifest,
    source_execution_manifest: &GatewayFormalBackendTinyHermeticExecutionOutputManifest,
    request: &GatewayFormalRealCommandLaneRequest,
    command: &GatewayFormalRealCommandLaneCommandDescriptor,
    obligation: &GatewayFormalRealCommandLaneObligation,
    obligation_binding: &GatewayFormalRealCommandLaneObligationBinding,
    transcript: &GatewayFormalRealCommandLaneTranscript,
    stdout_summary: &GatewayFormalRealCommandLaneBoundedSummary,
    stderr_summary: &GatewayFormalRealCommandLaneBoundedSummary,
    solver_verdict: &GatewayFormalRealCommandLaneSolverVerdict,
    nonpromotion: &GatewayFormalRealCommandLaneNonpromotionReport,
) -> GatewayFormalRealCommandLaneValidation {
    let mut issues = Vec::new();
    validate_gateway_formal_real_command_lane_request(request, &mut issues);
    validate_gateway_formal_real_command_lane_sources(
        source_adapter_manifest,
        source_execution_manifest,
        request,
        &mut issues,
    );
    validate_gateway_formal_real_command_lane_command(command, request, &mut issues);
    validate_gateway_formal_real_command_lane_obligation(
        obligation,
        obligation_binding,
        request,
        command,
        source_adapter_manifest,
        source_execution_manifest,
        &mut issues,
    );
    validate_gateway_formal_real_command_lane_transcript(
        transcript,
        request,
        command,
        obligation,
        obligation_binding,
        stdout_summary,
        stderr_summary,
        solver_verdict,
        nonpromotion,
        &mut issues,
    );
    validate_gateway_formal_real_command_lane_summary(stdout_summary, "stdout", &mut issues);
    validate_gateway_formal_real_command_lane_summary(stderr_summary, "stderr", &mut issues);
    validate_gateway_formal_real_command_lane_solver_verdict(solver_verdict, request, &mut issues);
    validate_gateway_formal_real_command_lane_nonpromotion(nonpromotion, &mut issues);

    GatewayFormalRealCommandLaneValidation {
        valid: issues.is_empty(),
        issues,
    }
}

fn validate_gateway_formal_real_command_lane_request(
    request: &GatewayFormalRealCommandLaneRequest,
    issues: &mut Vec<GatewayFormalRealCommandLaneIssue>,
) {
    if request.schema_version != GATEWAY_FORMAL_REAL_COMMAND_LANE_SCHEMA_VERSION {
        issues.push(GatewayFormalRealCommandLaneIssue::InvalidSchemaVersion);
    }
    if !is_single_segment_id(&request.run_id) {
        issues.push(GatewayFormalRealCommandLaneIssue::InvalidRunId);
    }
    if request.backend_id != "local_smt_tiny_gateway_invariant" {
        issues.push(GatewayFormalRealCommandLaneIssue::BackendIdMismatch);
    }
    if request.backend_mode != "smt-lib2-offline-command" {
        issues.push(GatewayFormalRealCommandLaneIssue::BackendModeMismatch);
    }
    if request.property_id != "attestation_challenge_binding_deterministic_input_sensitive" {
        issues.push(GatewayFormalRealCommandLaneIssue::PropertyIdMismatch);
    }
    for (label, digest) in [
        (
            "source_adapter_manifest_digest",
            request.source_adapter_manifest_digest,
        ),
        (
            "source_execution_manifest_digest",
            request.source_execution_manifest_digest,
        ),
        ("adapter_request_digest", request.adapter_request_digest),
        ("fixture_input_digest", request.fixture_input_digest),
        (
            "source_command_descriptor_digest",
            request.source_command_descriptor_digest,
        ),
        ("obligation_digest", request.obligation_digest),
        (
            "expected_output_grammar_digest",
            request.expected_output_grammar_digest,
        ),
    ] {
        if digest == Hash([0; 32]) {
            issues.push(GatewayFormalRealCommandLaneIssue::MissingDigest(
                label.to_owned(),
            ));
        }
    }
    if !request.operator_acknowledged {
        issues.push(GatewayFormalRealCommandLaneIssue::OperatorAcknowledgementMissing);
    }
    for required in gateway_formal_real_command_lane_required_nonclaims() {
        if !request.required_nonclaims.contains(&required) {
            issues.push(GatewayFormalRealCommandLaneIssue::MissingRequiredNonclaim(
                required.0,
            ));
        }
    }
}

fn validate_gateway_formal_real_command_lane_sources(
    source_adapter_manifest: &GatewayFormalBackendTinyHermeticAdapterOutputManifest,
    source_execution_manifest: &GatewayFormalBackendTinyHermeticExecutionOutputManifest,
    request: &GatewayFormalRealCommandLaneRequest,
    issues: &mut Vec<GatewayFormalRealCommandLaneIssue>,
) {
    if request.source_adapter_manifest_digest != source_adapter_manifest.digest()
        || source_adapter_manifest.schema_version
            != GATEWAY_FORMAL_BACKEND_TINY_HERMETIC_ADAPTER_OUTPUT_SCHEMA_VERSION
        || source_adapter_manifest.state_slice
            != GATEWAY_FORMAL_BACKEND_TINY_HERMETIC_ADAPTER_STATE_SLICE
        || source_adapter_manifest.backend_id != request.backend_id
        || source_adapter_manifest.property_id != request.property_id
        || source_adapter_manifest.process_spawned
        || source_adapter_manifest.backend_executed
        || source_adapter_manifest.creates_accepted_evidence
        || source_adapter_manifest.creates_level2_evidence
        || source_adapter_manifest.populates_score_axes
        || source_adapter_manifest.grants_authority
    {
        issues.push(GatewayFormalRealCommandLaneIssue::SourceAdapterManifestMismatch);
    }
    if request.source_execution_manifest_digest != source_execution_manifest.digest()
        || source_execution_manifest.schema_version
            != GATEWAY_FORMAL_BACKEND_TINY_HERMETIC_EXECUTION_OUTPUT_SCHEMA_VERSION
        || source_execution_manifest.state_slice
            != GATEWAY_FORMAL_BACKEND_TINY_HERMETIC_EXECUTION_STATE_SLICE
        || source_execution_manifest.source_adapter_manifest_digest
            != source_adapter_manifest.digest()
        || source_execution_manifest.adapter_request_digest != request.adapter_request_digest
        || source_execution_manifest.fixture_input_digest != request.fixture_input_digest
        || source_execution_manifest.command_descriptor_digest
            != request.source_command_descriptor_digest
        || source_execution_manifest.backend_id != request.backend_id
        || source_execution_manifest.property_id != request.property_id
        || source_execution_manifest.proof_artifact_created
        || source_execution_manifest.checker_transcript_created
        || source_execution_manifest.solver_certificate_created
        || source_execution_manifest.creates_accepted_evidence
        || source_execution_manifest.creates_level2_evidence
        || source_execution_manifest.populates_score_axes
        || source_execution_manifest.grants_authority
    {
        issues.push(GatewayFormalRealCommandLaneIssue::SourceExecutionManifestMismatch);
    }
}

fn validate_gateway_formal_real_command_lane_command(
    command: &GatewayFormalRealCommandLaneCommandDescriptor,
    request: &GatewayFormalRealCommandLaneRequest,
    issues: &mut Vec<GatewayFormalRealCommandLaneIssue>,
) {
    if command.schema_version != GATEWAY_FORMAL_REAL_COMMAND_LANE_SCHEMA_VERSION {
        issues.push(GatewayFormalRealCommandLaneIssue::InvalidSchemaVersion);
    }
    if command.backend_id != request.backend_id {
        issues.push(GatewayFormalRealCommandLaneIssue::BackendIdMismatch);
    }
    if command.backend_mode != request.backend_mode {
        issues.push(GatewayFormalRealCommandLaneIssue::BackendModeMismatch);
    }
    if command.command_kind != "direct_process_no_shell"
        || command.input_kind != "static_non_secret_smt2_obligation"
        || command.output_kind != "bounded_solver_stdout_stderr"
        || !is_single_segment_id(&command.executable_policy_id)
        || command.executable_path_label.trim().is_empty()
        || command.executable_path_label.starts_with('/')
        || !is_safe_relative_path(&command.executable_path_label)
        || has_shell_metacharacters(&command.executable_path_label)
        || command.argv_template.is_empty()
        || command
            .argv_template
            .iter()
            .any(|arg| arg.trim().is_empty() || has_shell_metacharacters(arg))
        || command.timeout_millis == 0
        || command.timeout_millis > 60_000
        || command.max_stdout_bytes == 0
        || command.max_stdout_bytes > 65_536
        || command.max_stderr_bytes == 0
        || command.max_stderr_bytes > 65_536
        || !command.direct_process_no_shell
        || !command.no_shell
        || !command.no_stdin
        || command.inherit_environment
        || !command.environment_variables.is_empty()
        || !command.no_network
        || command.caller_executable_path_allowed
        || command.caller_argv_allowed
        || !command.fixed_executable_policy
        || !command.fixed_argv_template
        || !command.ignored_output_root_only
        || command.input_digest_binding != request.source_execution_manifest_digest
        || command.obligation_digest_binding != request.obligation_digest
        || command.expected_output_grammar_digest_binding != request.expected_output_grammar_digest
    {
        issues.push(GatewayFormalRealCommandLaneIssue::CommandPolicyMismatch);
    }
    if command.argv_template_digest
        != hash_tagged(
            "hsai-agent-admission:gateway-formal-real-command-lane-argv-template:v1",
            &command.argv_template,
        )
    {
        issues.push(GatewayFormalRealCommandLaneIssue::CommandDigestMismatch);
    }
}

#[allow(clippy::too_many_arguments)]
fn validate_gateway_formal_real_command_lane_obligation(
    obligation: &GatewayFormalRealCommandLaneObligation,
    obligation_binding: &GatewayFormalRealCommandLaneObligationBinding,
    request: &GatewayFormalRealCommandLaneRequest,
    command: &GatewayFormalRealCommandLaneCommandDescriptor,
    source_adapter_manifest: &GatewayFormalBackendTinyHermeticAdapterOutputManifest,
    source_execution_manifest: &GatewayFormalBackendTinyHermeticExecutionOutputManifest,
    issues: &mut Vec<GatewayFormalRealCommandLaneIssue>,
) {
    if obligation.schema_version != GATEWAY_FORMAL_REAL_COMMAND_LANE_SCHEMA_VERSION
        || obligation_binding.schema_version != GATEWAY_FORMAL_REAL_COMMAND_LANE_SCHEMA_VERSION
    {
        issues.push(GatewayFormalRealCommandLaneIssue::InvalidSchemaVersion);
    }
    if !is_single_segment_id(&obligation.obligation_id)
        || obligation.backend_id != request.backend_id
        || obligation.backend_mode != request.backend_mode
        || obligation.property_id != request.property_id
        || obligation.obligation_format != "smt-lib2-static-non-secret"
        || !obligation.smtlib2_text.contains("(set-logic")
        || !obligation
            .smtlib2_text
            .contains("attestation_challenge_binding")
        || has_shell_metacharacters(&obligation.smtlib2_text)
        || obligation.digest() != request.obligation_digest
    {
        issues.push(GatewayFormalRealCommandLaneIssue::ObligationMismatch);
    }
    if !obligation.non_secret
        || obligation.contains_provider_response
        || obligation.contains_raw_quote
        || obligation.contains_credentials
    {
        issues.push(GatewayFormalRealCommandLaneIssue::ObligationContainsSecretOrLiveArtifact);
    }
    if obligation_binding.backend_id != request.backend_id
        || obligation_binding.backend_mode != request.backend_mode
        || obligation_binding.property_id != request.property_id
        || obligation_binding.source_adapter_manifest_digest != source_adapter_manifest.digest()
        || obligation_binding.source_execution_manifest_digest != source_execution_manifest.digest()
        || obligation_binding.command_descriptor_digest != command.digest()
        || obligation_binding.obligation_digest != obligation.digest()
        || obligation_binding.expected_output_grammar_digest
            != request.expected_output_grammar_digest
        || obligation_binding.imported_assumptions != obligation.imported_assumptions
        || obligation_binding.claim_boundary != gateway_formal_real_command_lane_claim_boundary()
    {
        issues.push(GatewayFormalRealCommandLaneIssue::ObligationMismatch);
    }
}

#[allow(clippy::too_many_arguments)]
fn validate_gateway_formal_real_command_lane_transcript(
    transcript: &GatewayFormalRealCommandLaneTranscript,
    request: &GatewayFormalRealCommandLaneRequest,
    command: &GatewayFormalRealCommandLaneCommandDescriptor,
    obligation: &GatewayFormalRealCommandLaneObligation,
    obligation_binding: &GatewayFormalRealCommandLaneObligationBinding,
    stdout_summary: &GatewayFormalRealCommandLaneBoundedSummary,
    stderr_summary: &GatewayFormalRealCommandLaneBoundedSummary,
    solver_verdict: &GatewayFormalRealCommandLaneSolverVerdict,
    nonpromotion: &GatewayFormalRealCommandLaneNonpromotionReport,
    issues: &mut Vec<GatewayFormalRealCommandLaneIssue>,
) {
    if transcript.schema_version != GATEWAY_FORMAL_REAL_COMMAND_LANE_SCHEMA_VERSION
        || transcript.run_id != request.run_id
        || transcript.backend_id != request.backend_id
        || transcript.backend_mode != request.backend_mode
        || transcript.property_id != request.property_id
        || transcript.source_adapter_manifest_digest != request.source_adapter_manifest_digest
        || transcript.source_execution_manifest_digest != request.source_execution_manifest_digest
        || transcript.command_descriptor_digest != command.digest()
        || transcript.obligation_digest != obligation.digest()
        || transcript.expected_output_grammar_digest != request.expected_output_grammar_digest
        || transcript.stdout_summary_digest != stdout_summary.digest()
        || transcript.stderr_summary_digest != stderr_summary.digest()
        || transcript.redaction_report_digest
            != gateway_formal_real_command_lane_redaction_report(stdout_summary, stderr_summary)
                .digest()
        || transcript.nonpromotion_report_digest != nonpromotion.digest()
        || transcript.process_exit_code_label != "not_run"
        || transcript.timeout
        || transcript.solver_status_label != "not_run"
        || transcript.solver_verdict_label != solver_verdict.solver_verdict_label
        || transcript.solver_verdict_label != GatewayFormalRealCommandLaneSolverVerdictLabel::NotRun
        || transcript.imported_assumptions != obligation.imported_assumptions
        || transcript.explicit_nonclaims != request.required_nonclaims
        || obligation_binding.digest() == Hash([0; 32])
        || transcript.claim_boundary != gateway_formal_real_command_lane_claim_boundary()
    {
        issues.push(GatewayFormalRealCommandLaneIssue::TranscriptMismatch);
    }
    if transcript.process_spawned
        || transcript.backend_executed
        || transcript.proof_artifact_created
        || transcript.checker_transcript_created
        || transcript.solver_certificate_created
        || transcript.creates_accepted_evidence
        || transcript.creates_level2_evidence
        || transcript.populates_score_axes
        || transcript.semantic_correctness_claimed
        || transcript.production_readiness_claimed
        || transcript.sota_claimed
        || transcript.breakthrough_claimed
        || transcript.full_security_claimed
        || transcript.grants_authority
        || transcript.raw_logs_retained
        || transcript.raw_provider_response_retained
    {
        issues.push(GatewayFormalRealCommandLaneIssue::PromotionAttempt);
    }
}

fn validate_gateway_formal_real_command_lane_summary(
    summary: &GatewayFormalRealCommandLaneBoundedSummary,
    stream_label: &str,
    issues: &mut Vec<GatewayFormalRealCommandLaneIssue>,
) {
    if summary.stream_label != stream_label
        || summary.max_bytes == 0
        || summary.retained_bytes > summary.max_bytes
        || summary.truncated
        || summary.retained_text != "not_run summary only"
        || summary.raw_retained
        || summary.raw_solver_trace_retained
        || summary.proof_artifact_retained
        || summary.checker_transcript_retained
        || !summary.secret_scan_passed
        || summary.claim_boundary != gateway_formal_real_command_lane_claim_boundary()
    {
        issues.push(GatewayFormalRealCommandLaneIssue::SummaryMismatch);
    }
}

fn gateway_formal_real_command_lane_redaction_report(
    stdout_summary: &GatewayFormalRealCommandLaneBoundedSummary,
    stderr_summary: &GatewayFormalRealCommandLaneBoundedSummary,
) -> GatewayFormalRealCommandLaneRedactionReport {
    GatewayFormalRealCommandLaneRedactionReport {
        schema_version: GATEWAY_FORMAL_REAL_COMMAND_LANE_OUTPUT_SCHEMA_VERSION.to_owned(),
        valid: stdout_summary.secret_scan_passed && stderr_summary.secret_scan_passed,
        stdout_summary_bounded: stdout_summary.retained_bytes <= stdout_summary.max_bytes
            && !stdout_summary.raw_retained
            && !stdout_summary.raw_solver_trace_retained
            && !stdout_summary.proof_artifact_retained
            && !stdout_summary.checker_transcript_retained,
        stderr_summary_bounded: stderr_summary.retained_bytes <= stderr_summary.max_bytes
            && !stderr_summary.raw_retained
            && !stderr_summary.raw_solver_trace_retained
            && !stderr_summary.proof_artifact_retained
            && !stderr_summary.checker_transcript_retained,
        credential_looking_value_found: false,
        secret_looking_value_found: false,
        raw_solver_trace_found: false,
        proof_artifact_found: false,
        checker_transcript_found: false,
        solver_certificate_found: false,
        retained_summary_only: true,
        claim_boundary: gateway_formal_real_command_lane_claim_boundary(),
    }
}

fn validate_gateway_formal_real_command_lane_redaction_report(
    report: &GatewayFormalRealCommandLaneRedactionReport,
    stdout_summary: &GatewayFormalRealCommandLaneBoundedSummary,
    stderr_summary: &GatewayFormalRealCommandLaneBoundedSummary,
) -> Result<(), GatewayFormalRealCommandLaneOutputError> {
    let expected =
        gateway_formal_real_command_lane_redaction_report(stdout_summary, stderr_summary);
    if report != &expected {
        return Err(GatewayFormalRealCommandLaneOutputError::RedactionReportMismatch);
    }
    Ok(())
}

fn validate_gateway_formal_real_command_lane_solver_verdict(
    verdict: &GatewayFormalRealCommandLaneSolverVerdict,
    request: &GatewayFormalRealCommandLaneRequest,
    issues: &mut Vec<GatewayFormalRealCommandLaneIssue>,
) {
    if verdict.schema_version != GATEWAY_FORMAL_REAL_COMMAND_LANE_SCHEMA_VERSION
        || verdict.backend_id != request.backend_id
        || verdict.backend_mode != request.backend_mode
        || verdict.property_id != request.property_id
        || verdict.solver_verdict_label != GatewayFormalRealCommandLaneSolverVerdictLabel::NotRun
        || verdict.certificate_retained
        || verdict.witness_retained
        || verdict.proof_authority_claimed
        || verdict.semantic_correctness_claimed
        || verdict.claim_boundary != gateway_formal_real_command_lane_claim_boundary()
    {
        issues.push(GatewayFormalRealCommandLaneIssue::SolverVerdictMismatch);
    }
}

fn validate_gateway_formal_real_command_lane_nonpromotion(
    nonpromotion: &GatewayFormalRealCommandLaneNonpromotionReport,
    issues: &mut Vec<GatewayFormalRealCommandLaneIssue>,
) {
    if nonpromotion.proof_artifact_created
        || nonpromotion.checker_transcript_created
        || nonpromotion.solver_certificate_created
        || nonpromotion.creates_accepted_evidence
        || nonpromotion.creates_level2_evidence
        || nonpromotion.populates_score_axes
        || nonpromotion.grants_authority
        || nonpromotion.semantic_correctness_claimed
        || nonpromotion.production_readiness_claimed
        || nonpromotion.sota_claimed
        || nonpromotion.breakthrough_claimed
        || nonpromotion.full_security_claimed
        || nonpromotion.raw_logs_retained
        || nonpromotion.raw_provider_response_retained
        || nonpromotion.claim_boundary != gateway_formal_real_command_lane_claim_boundary()
    {
        issues.push(GatewayFormalRealCommandLaneIssue::NonpromotionMismatch);
    }
}

#[allow(clippy::too_many_arguments)]
fn gateway_formal_real_command_lane_declared_file_digests(
    source_execution_manifest: &GatewayFormalBackendTinyHermeticExecutionOutputManifest,
    request: &GatewayFormalRealCommandLaneRequest,
    command: &GatewayFormalRealCommandLaneCommandDescriptor,
    obligation: &GatewayFormalRealCommandLaneObligation,
    obligation_binding: &GatewayFormalRealCommandLaneObligationBinding,
    transcript: &GatewayFormalRealCommandLaneTranscript,
    stdout_summary: &GatewayFormalRealCommandLaneBoundedSummary,
    stderr_summary: &GatewayFormalRealCommandLaneBoundedSummary,
    solver_verdict: &GatewayFormalRealCommandLaneSolverVerdict,
    nonpromotion: &GatewayFormalRealCommandLaneNonpromotionReport,
    validation_report: &GatewayFormalRealCommandLaneValidationReport,
) -> BTreeMap<String, Hash> {
    let mut digests = BTreeMap::new();
    let entries = [
        (
            "gateway-formal-real-command-lane/source-execution-manifest.json",
            hash_tagged(
                "hsai-agent-admission:gateway-formal-real-command-lane-declared-source-execution-manifest:v1",
                source_execution_manifest,
            ),
        ),
        (
            "gateway-formal-real-command-lane/command-request.json",
            request.digest(),
        ),
        (
            "gateway-formal-real-command-lane/command-descriptor.json",
            command.digest(),
        ),
        (
            "gateway-formal-real-command-lane/obligation.smt2",
            hash_bytes(obligation.smtlib2_text.as_bytes()),
        ),
        (
            "gateway-formal-real-command-lane/obligation-binding.json",
            obligation_binding.digest(),
        ),
        (
            "gateway-formal-real-command-lane/execution-transcript.json",
            transcript.digest(),
        ),
        (
            "gateway-formal-real-command-lane/stdout-summary.json",
            stdout_summary.digest(),
        ),
        (
            "gateway-formal-real-command-lane/stderr-summary.json",
            stderr_summary.digest(),
        ),
        (
            "gateway-formal-real-command-lane/solver-verdict.json",
            solver_verdict.digest(),
        ),
        (
            "gateway-formal-real-command-lane/checker-transcript.json",
            transcript.digest(),
        ),
        (
            "gateway-formal-real-command-lane/redaction-report.json",
            transcript.redaction_report_digest,
        ),
        (
            "gateway-formal-real-command-lane/nonpromotion-report.json",
            nonpromotion.digest(),
        ),
        (
            "gateway-formal-real-command-lane/nonclaims.md",
            hash_tagged(
                "hsai-agent-admission:gateway-formal-real-command-lane-nonclaims:v1",
                &request.required_nonclaims,
            ),
        ),
        (
            "gateway-formal-real-command-lane/validation-report.json",
            validation_report.digest(),
        ),
    ];
    for (path, digest) in entries {
        digests.insert(path.to_owned(), digest);
    }
    digests
}

#[allow(clippy::too_many_arguments)]
pub fn materialize_gateway_formal_real_command_lane_output_bundle(
    output_root: &Path,
    source_adapter_manifest: &GatewayFormalBackendTinyHermeticAdapterOutputManifest,
    source_execution_manifest: &GatewayFormalBackendTinyHermeticExecutionOutputManifest,
    request: &GatewayFormalRealCommandLaneRequest,
    command: &GatewayFormalRealCommandLaneCommandDescriptor,
    obligation: &GatewayFormalRealCommandLaneObligation,
    obligation_binding: &GatewayFormalRealCommandLaneObligationBinding,
    transcript: &GatewayFormalRealCommandLaneTranscript,
    stdout_summary: &GatewayFormalRealCommandLaneBoundedSummary,
    stderr_summary: &GatewayFormalRealCommandLaneBoundedSummary,
    solver_verdict: &GatewayFormalRealCommandLaneSolverVerdict,
    nonpromotion: &GatewayFormalRealCommandLaneNonpromotionReport,
    output_request: &GatewayFormalRealCommandLaneOutputRequest,
) -> Result<GatewayFormalRealCommandLaneOutputManifest, GatewayFormalRealCommandLaneOutputError> {
    validate_gateway_formal_real_command_lane_output_request(
        output_root,
        source_adapter_manifest,
        source_execution_manifest,
        request,
        command,
        obligation,
        obligation_binding,
        transcript,
        stdout_summary,
        stderr_summary,
        solver_verdict,
        nonpromotion,
        output_request,
    )?;
    let staging_root =
        gateway_formal_real_command_lane_staging_root_for(output_root, &request.run_id)?;
    if staging_root.exists() {
        remove_gateway_formal_real_command_lane_dir_all_checked(&staging_root)?;
    }
    fs::create_dir_all(staging_root.join("gateway-formal-real-command-lane"))
        .map_err(gateway_formal_real_command_lane_io_error)?;

    let files = build_gateway_formal_real_command_lane_bundle_files(
        output_request.created_at_unix,
        source_adapter_manifest,
        source_execution_manifest,
        request,
        command,
        obligation,
        obligation_binding,
        transcript,
        stdout_summary,
        stderr_summary,
        solver_verdict,
        nonpromotion,
    )?;
    for (logical_path, bytes) in &files {
        let target = staging_root.join(logical_path);
        if let Some(parent) = target.parent() {
            fs::create_dir_all(parent).map_err(gateway_formal_real_command_lane_io_error)?;
        }
        fs::write(&target, bytes).map_err(gateway_formal_real_command_lane_io_error)?;
        fs::write(
            sidecar_path(&target),
            hash_hex(hash_bytes(bytes)).into_bytes(),
        )
        .map_err(gateway_formal_real_command_lane_io_error)?;
    }

    if output_root.exists() {
        if !output_request.overwrite {
            remove_gateway_formal_real_command_lane_dir_all_checked(&staging_root)?;
            return Err(GatewayFormalRealCommandLaneOutputError::OutputRootExistsWithoutOverwrite);
        }
        remove_gateway_formal_real_command_lane_dir_all_checked(output_root)?;
    }
    fs::rename(&staging_root, output_root).map_err(gateway_formal_real_command_lane_io_error)?;
    read_gateway_formal_real_command_lane_output_bundle(output_root)
}

pub fn read_gateway_formal_real_command_lane_output_bundle(
    output_root: &Path,
) -> Result<GatewayFormalRealCommandLaneOutputManifest, GatewayFormalRealCommandLaneOutputError> {
    let output_metadata =
        fs::symlink_metadata(output_root).map_err(gateway_formal_real_command_lane_io_error)?;
    if output_metadata.file_type().is_symlink() {
        return Err(GatewayFormalRealCommandLaneOutputError::OutputRootIsSymlink);
    }
    if !output_metadata.is_dir() {
        return Err(GatewayFormalRealCommandLaneOutputError::OutputRootIsFile);
    }
    let bundle_dir = output_root.join("gateway-formal-real-command-lane");
    let bundle_metadata =
        fs::symlink_metadata(&bundle_dir).map_err(gateway_formal_real_command_lane_io_error)?;
    if bundle_metadata.file_type().is_symlink() {
        return Err(
            GatewayFormalRealCommandLaneOutputError::BundleFileIsSymlink(
                "gateway-formal-real-command-lane".to_owned(),
            ),
        );
    }
    if !bundle_metadata.is_dir() {
        return Err(
            GatewayFormalRealCommandLaneOutputError::DeclaredFileTypeMismatch(
                "gateway-formal-real-command-lane".to_owned(),
            ),
        );
    }

    reject_undeclared_gateway_formal_real_command_lane_files(output_root)?;
    let mut files = BTreeMap::new();
    for logical_path in GATEWAY_FORMAL_REAL_COMMAND_LANE_DECLARED_FILES {
        let path = output_root.join(logical_path);
        let metadata =
            fs::symlink_metadata(&path).map_err(gateway_formal_real_command_lane_io_error)?;
        if metadata.file_type().is_symlink() {
            return Err(
                GatewayFormalRealCommandLaneOutputError::BundleFileIsSymlink(
                    (*logical_path).to_owned(),
                ),
            );
        }
        if !metadata.is_file() {
            return Err(
                GatewayFormalRealCommandLaneOutputError::DeclaredFileTypeMismatch(
                    (*logical_path).to_owned(),
                ),
            );
        }
        let sidecar = sidecar_path(&path);
        let sidecar_metadata =
            fs::symlink_metadata(&sidecar).map_err(gateway_formal_real_command_lane_io_error)?;
        if sidecar_metadata.file_type().is_symlink() {
            return Err(
                GatewayFormalRealCommandLaneOutputError::BundleFileIsSymlink(format!(
                    "{logical_path}.sha256"
                )),
            );
        }
        if !sidecar_metadata.is_file() {
            return Err(
                GatewayFormalRealCommandLaneOutputError::DeclaredFileTypeMismatch(format!(
                    "{logical_path}.sha256"
                )),
            );
        }
        let bytes = fs::read(&path).map_err(gateway_formal_real_command_lane_io_error)?;
        let expected_hash =
            fs::read_to_string(&sidecar).map_err(gateway_formal_real_command_lane_io_error)?;
        if expected_hash.trim() != hash_hex(hash_bytes(&bytes)) {
            return Err(GatewayFormalRealCommandLaneOutputError::DigestMismatch(
                (*logical_path).to_owned(),
            ));
        }
        files.insert((*logical_path).to_owned(), bytes);
    }
    validate_gateway_formal_real_command_lane_bundle_semantics(&files)
}

#[allow(clippy::too_many_arguments)]
fn validate_gateway_formal_real_command_lane_output_request(
    output_root: &Path,
    source_adapter_manifest: &GatewayFormalBackendTinyHermeticAdapterOutputManifest,
    source_execution_manifest: &GatewayFormalBackendTinyHermeticExecutionOutputManifest,
    request: &GatewayFormalRealCommandLaneRequest,
    command: &GatewayFormalRealCommandLaneCommandDescriptor,
    obligation: &GatewayFormalRealCommandLaneObligation,
    obligation_binding: &GatewayFormalRealCommandLaneObligationBinding,
    transcript: &GatewayFormalRealCommandLaneTranscript,
    stdout_summary: &GatewayFormalRealCommandLaneBoundedSummary,
    stderr_summary: &GatewayFormalRealCommandLaneBoundedSummary,
    solver_verdict: &GatewayFormalRealCommandLaneSolverVerdict,
    nonpromotion: &GatewayFormalRealCommandLaneNonpromotionReport,
    output_request: &GatewayFormalRealCommandLaneOutputRequest,
) -> Result<(), GatewayFormalRealCommandLaneOutputError> {
    if !is_single_segment_id(&request.run_id) {
        return Err(GatewayFormalRealCommandLaneOutputError::EmptyRunId);
    }
    let validation = validate_gateway_formal_real_command_lane(
        source_adapter_manifest,
        source_execution_manifest,
        request,
        command,
        obligation,
        obligation_binding,
        transcript,
        stdout_summary,
        stderr_summary,
        solver_verdict,
        nonpromotion,
    );
    if !validation.valid {
        return Err(GatewayFormalRealCommandLaneOutputError::InvalidContract(
            validation.issues,
        ));
    }
    validate_gateway_formal_real_command_lane_output_root(
        output_root,
        &output_request.protected_roots,
        output_request.overwrite,
    )
}

#[allow(clippy::too_many_arguments)]
fn build_gateway_formal_real_command_lane_bundle_files(
    created_at_unix: u64,
    source_adapter_manifest: &GatewayFormalBackendTinyHermeticAdapterOutputManifest,
    source_execution_manifest: &GatewayFormalBackendTinyHermeticExecutionOutputManifest,
    request: &GatewayFormalRealCommandLaneRequest,
    command: &GatewayFormalRealCommandLaneCommandDescriptor,
    obligation: &GatewayFormalRealCommandLaneObligation,
    obligation_binding: &GatewayFormalRealCommandLaneObligationBinding,
    transcript: &GatewayFormalRealCommandLaneTranscript,
    stdout_summary: &GatewayFormalRealCommandLaneBoundedSummary,
    stderr_summary: &GatewayFormalRealCommandLaneBoundedSummary,
    solver_verdict: &GatewayFormalRealCommandLaneSolverVerdict,
    nonpromotion: &GatewayFormalRealCommandLaneNonpromotionReport,
) -> Result<BTreeMap<String, Vec<u8>>, GatewayFormalRealCommandLaneOutputError> {
    let contract = build_gateway_formal_real_command_lane_output_contract(
        created_at_unix,
        source_adapter_manifest,
        source_execution_manifest,
        request,
        command,
        obligation,
        obligation_binding,
        transcript,
        stdout_summary,
        stderr_summary,
        solver_verdict,
        nonpromotion,
    );
    if !contract.validation_report.valid {
        return Err(GatewayFormalRealCommandLaneOutputError::InvalidContract(
            validate_gateway_formal_real_command_lane(
                source_adapter_manifest,
                source_execution_manifest,
                request,
                command,
                obligation,
                obligation_binding,
                transcript,
                stdout_summary,
                stderr_summary,
                solver_verdict,
                nonpromotion,
            )
            .issues,
        ));
    }
    let redaction_report =
        gateway_formal_real_command_lane_redaction_report(stdout_summary, stderr_summary);
    let nonclaims_md =
        gateway_formal_real_command_lane_nonclaims_markdown(&request.required_nonclaims);
    let mut files = BTreeMap::from([
        (
            "gateway-formal-real-command-lane/source-execution-manifest.json".to_owned(),
            serde_json::to_vec_pretty(source_execution_manifest)
                .map_err(gateway_formal_real_command_lane_serde_error)?,
        ),
        (
            "gateway-formal-real-command-lane/command-request.json".to_owned(),
            serde_json::to_vec_pretty(request)
                .map_err(gateway_formal_real_command_lane_serde_error)?,
        ),
        (
            "gateway-formal-real-command-lane/command-descriptor.json".to_owned(),
            serde_json::to_vec_pretty(command)
                .map_err(gateway_formal_real_command_lane_serde_error)?,
        ),
        (
            "gateway-formal-real-command-lane/obligation.smt2".to_owned(),
            obligation.smtlib2_text.as_bytes().to_vec(),
        ),
        (
            "gateway-formal-real-command-lane/obligation-binding.json".to_owned(),
            serde_json::to_vec_pretty(obligation_binding)
                .map_err(gateway_formal_real_command_lane_serde_error)?,
        ),
        (
            "gateway-formal-real-command-lane/execution-transcript.json".to_owned(),
            serde_json::to_vec_pretty(transcript)
                .map_err(gateway_formal_real_command_lane_serde_error)?,
        ),
        (
            "gateway-formal-real-command-lane/stdout-summary.json".to_owned(),
            serde_json::to_vec_pretty(stdout_summary)
                .map_err(gateway_formal_real_command_lane_serde_error)?,
        ),
        (
            "gateway-formal-real-command-lane/stderr-summary.json".to_owned(),
            serde_json::to_vec_pretty(stderr_summary)
                .map_err(gateway_formal_real_command_lane_serde_error)?,
        ),
        (
            "gateway-formal-real-command-lane/solver-verdict.json".to_owned(),
            serde_json::to_vec_pretty(solver_verdict)
                .map_err(gateway_formal_real_command_lane_serde_error)?,
        ),
        (
            "gateway-formal-real-command-lane/checker-transcript.json".to_owned(),
            serde_json::to_vec_pretty(transcript)
                .map_err(gateway_formal_real_command_lane_serde_error)?,
        ),
        (
            "gateway-formal-real-command-lane/redaction-report.json".to_owned(),
            serde_json::to_vec_pretty(&redaction_report)
                .map_err(gateway_formal_real_command_lane_serde_error)?,
        ),
        (
            "gateway-formal-real-command-lane/nonpromotion-report.json".to_owned(),
            serde_json::to_vec_pretty(nonpromotion)
                .map_err(gateway_formal_real_command_lane_serde_error)?,
        ),
        (
            "gateway-formal-real-command-lane/nonclaims.md".to_owned(),
            nonclaims_md.into_bytes(),
        ),
        (
            "gateway-formal-real-command-lane/validation-report.json".to_owned(),
            serde_json::to_vec_pretty(&contract.validation_report)
                .map_err(gateway_formal_real_command_lane_serde_error)?,
        ),
    ]);
    files.insert(
        "gateway-formal-real-command-lane/manifest.json".to_owned(),
        serde_json::to_vec_pretty(&contract.manifest)
            .map_err(gateway_formal_real_command_lane_serde_error)?,
    );
    Ok(files)
}

fn validate_gateway_formal_real_command_lane_bundle_semantics(
    files: &BTreeMap<String, Vec<u8>>,
) -> Result<GatewayFormalRealCommandLaneOutputManifest, GatewayFormalRealCommandLaneOutputError> {
    let manifest: GatewayFormalRealCommandLaneOutputManifest =
        parse_gateway_formal_real_command_lane_declared_json(
            files,
            "gateway-formal-real-command-lane/manifest.json",
        )?;
    let source_execution_manifest: GatewayFormalBackendTinyHermeticExecutionOutputManifest =
        parse_gateway_formal_real_command_lane_declared_json(
            files,
            "gateway-formal-real-command-lane/source-execution-manifest.json",
        )?;
    let request: GatewayFormalRealCommandLaneRequest =
        parse_gateway_formal_real_command_lane_declared_json(
            files,
            "gateway-formal-real-command-lane/command-request.json",
        )?;
    let command: GatewayFormalRealCommandLaneCommandDescriptor =
        parse_gateway_formal_real_command_lane_declared_json(
            files,
            "gateway-formal-real-command-lane/command-descriptor.json",
        )?;
    let obligation_smt2 = String::from_utf8(
        declared_gateway_formal_real_command_lane_bytes(
            files,
            "gateway-formal-real-command-lane/obligation.smt2",
        )?
        .to_vec(),
    )
    .map_err(|_| {
        GatewayFormalRealCommandLaneOutputError::MalformedDeclaredFile(
            "gateway-formal-real-command-lane/obligation.smt2".to_owned(),
        )
    })?;
    let obligation_binding: GatewayFormalRealCommandLaneObligationBinding =
        parse_gateway_formal_real_command_lane_declared_json(
            files,
            "gateway-formal-real-command-lane/obligation-binding.json",
        )?;
    let transcript: GatewayFormalRealCommandLaneTranscript =
        parse_gateway_formal_real_command_lane_declared_json(
            files,
            "gateway-formal-real-command-lane/execution-transcript.json",
        )?;
    let checker_transcript: GatewayFormalRealCommandLaneTranscript =
        parse_gateway_formal_real_command_lane_declared_json(
            files,
            "gateway-formal-real-command-lane/checker-transcript.json",
        )?;
    let stdout_summary: GatewayFormalRealCommandLaneBoundedSummary =
        parse_gateway_formal_real_command_lane_declared_json(
            files,
            "gateway-formal-real-command-lane/stdout-summary.json",
        )?;
    let stderr_summary: GatewayFormalRealCommandLaneBoundedSummary =
        parse_gateway_formal_real_command_lane_declared_json(
            files,
            "gateway-formal-real-command-lane/stderr-summary.json",
        )?;
    let solver_verdict: GatewayFormalRealCommandLaneSolverVerdict =
        parse_gateway_formal_real_command_lane_declared_json(
            files,
            "gateway-formal-real-command-lane/solver-verdict.json",
        )?;
    let redaction_report: GatewayFormalRealCommandLaneRedactionReport =
        parse_gateway_formal_real_command_lane_declared_json(
            files,
            "gateway-formal-real-command-lane/redaction-report.json",
        )?;
    let nonpromotion: GatewayFormalRealCommandLaneNonpromotionReport =
        parse_gateway_formal_real_command_lane_declared_json(
            files,
            "gateway-formal-real-command-lane/nonpromotion-report.json",
        )?;
    let validation_report: GatewayFormalRealCommandLaneValidationReport =
        parse_gateway_formal_real_command_lane_declared_json(
            files,
            "gateway-formal-real-command-lane/validation-report.json",
        )?;

    validate_gateway_formal_real_command_lane_readback_manifest(
        &manifest,
        &source_execution_manifest,
        &request,
        &command,
        &obligation_smt2,
        &obligation_binding,
        &transcript,
        &checker_transcript,
        &stdout_summary,
        &stderr_summary,
        &solver_verdict,
        &redaction_report,
        &nonpromotion,
        &validation_report,
        files,
    )?;
    Ok(manifest)
}

#[allow(clippy::too_many_arguments)]
fn validate_gateway_formal_real_command_lane_readback_manifest(
    manifest: &GatewayFormalRealCommandLaneOutputManifest,
    source_execution_manifest: &GatewayFormalBackendTinyHermeticExecutionOutputManifest,
    request: &GatewayFormalRealCommandLaneRequest,
    command: &GatewayFormalRealCommandLaneCommandDescriptor,
    obligation_smt2: &str,
    obligation_binding: &GatewayFormalRealCommandLaneObligationBinding,
    transcript: &GatewayFormalRealCommandLaneTranscript,
    checker_transcript: &GatewayFormalRealCommandLaneTranscript,
    stdout_summary: &GatewayFormalRealCommandLaneBoundedSummary,
    stderr_summary: &GatewayFormalRealCommandLaneBoundedSummary,
    solver_verdict: &GatewayFormalRealCommandLaneSolverVerdict,
    redaction_report: &GatewayFormalRealCommandLaneRedactionReport,
    nonpromotion: &GatewayFormalRealCommandLaneNonpromotionReport,
    validation_report: &GatewayFormalRealCommandLaneValidationReport,
    files: &BTreeMap<String, Vec<u8>>,
) -> Result<(), GatewayFormalRealCommandLaneOutputError> {
    let expected_digest_paths: BTreeSet<String> = GATEWAY_FORMAL_REAL_COMMAND_LANE_DECLARED_FILES
        .iter()
        .filter(|path| **path != "gateway-formal-real-command-lane/manifest.json")
        .map(|path| (*path).to_owned())
        .collect();
    let actual_digest_paths: BTreeSet<String> =
        manifest.declared_file_digests.keys().cloned().collect();
    if manifest.schema_version != GATEWAY_FORMAL_REAL_COMMAND_LANE_OUTPUT_SCHEMA_VERSION
        || manifest.state_slice != GATEWAY_FORMAL_REAL_COMMAND_LANE_STATE_SLICE
        || manifest.run_id != request.run_id
        || manifest.request_digest != request.digest()
        || manifest.source_execution_manifest_digest != source_execution_manifest.digest()
        || manifest.command_descriptor_digest != command.digest()
        || manifest.obligation_digest != request.obligation_digest
        || manifest.obligation_binding_digest != obligation_binding.digest()
        || manifest.transcript_digest != transcript.digest()
        || manifest.solver_verdict_digest != solver_verdict.digest()
        || manifest.stdout_summary_digest != stdout_summary.digest()
        || manifest.stderr_summary_digest != stderr_summary.digest()
        || manifest.redaction_report_digest != redaction_report.digest()
        || manifest.nonpromotion_report_digest != nonpromotion.digest()
        || manifest.validation_report_digest != validation_report.digest()
        || manifest.backend_id != request.backend_id
        || manifest.backend_mode != request.backend_mode
        || manifest.property_id != request.property_id
        || manifest.declared_files != gateway_formal_real_command_lane_declared_files()
        || manifest.declared_sidecars != gateway_formal_real_command_lane_declared_sidecars()
        || actual_digest_paths != expected_digest_paths
        || manifest.claim_boundary != gateway_formal_real_command_lane_claim_boundary()
        || manifest.process_spawned
        || manifest.backend_executed
        || manifest.proof_artifact_created
        || manifest.checker_transcript_created
        || manifest.solver_certificate_created
        || manifest.creates_accepted_evidence
        || manifest.creates_level2_evidence
        || manifest.populates_score_axes
        || manifest.semantic_correctness_claimed
        || manifest.production_readiness_claimed
        || manifest.sota_claimed
        || manifest.breakthrough_claimed
        || manifest.full_security_claimed
        || manifest.grants_authority
        || manifest.raw_logs_retained
        || manifest.raw_provider_response_retained
        || manifest.nonclaims != request.required_nonclaims
    {
        return Err(GatewayFormalRealCommandLaneOutputError::ManifestSemanticMismatch);
    }
    for (logical_path, expected_digest) in &manifest.declared_file_digests {
        let actual = match logical_path.as_str() {
            "gateway-formal-real-command-lane/source-execution-manifest.json" => hash_tagged(
                "hsai-agent-admission:gateway-formal-real-command-lane-declared-source-execution-manifest:v1",
                source_execution_manifest,
            ),
            "gateway-formal-real-command-lane/command-request.json" => request.digest(),
            "gateway-formal-real-command-lane/command-descriptor.json" => command.digest(),
            "gateway-formal-real-command-lane/obligation.smt2" => {
                hash_bytes(obligation_smt2.as_bytes())
            }
            "gateway-formal-real-command-lane/obligation-binding.json" => {
                obligation_binding.digest()
            }
            "gateway-formal-real-command-lane/execution-transcript.json" => transcript.digest(),
            "gateway-formal-real-command-lane/stdout-summary.json" => stdout_summary.digest(),
            "gateway-formal-real-command-lane/stderr-summary.json" => stderr_summary.digest(),
            "gateway-formal-real-command-lane/solver-verdict.json" => solver_verdict.digest(),
            "gateway-formal-real-command-lane/checker-transcript.json" => {
                checker_transcript.digest()
            }
            "gateway-formal-real-command-lane/redaction-report.json" => redaction_report.digest(),
            "gateway-formal-real-command-lane/nonpromotion-report.json" => nonpromotion.digest(),
            "gateway-formal-real-command-lane/nonclaims.md" => hash_tagged(
                "hsai-agent-admission:gateway-formal-real-command-lane-nonclaims:v1",
                &request.required_nonclaims,
            ),
            "gateway-formal-real-command-lane/validation-report.json" => {
                validation_report.digest()
            }
            _ => return Err(GatewayFormalRealCommandLaneOutputError::ManifestSemanticMismatch),
        };
        if actual != *expected_digest {
            return Err(GatewayFormalRealCommandLaneOutputError::ManifestSemanticMismatch);
        }
    }
    if checker_transcript != transcript {
        return Err(GatewayFormalRealCommandLaneOutputError::TranscriptMismatch);
    }
    if transcript.redaction_report_digest != redaction_report.digest()
        || transcript.stdout_summary_digest != stdout_summary.digest()
        || transcript.stderr_summary_digest != stderr_summary.digest()
        || transcript.nonpromotion_report_digest != nonpromotion.digest()
        || transcript.solver_verdict_label != solver_verdict.solver_verdict_label
    {
        return Err(GatewayFormalRealCommandLaneOutputError::TranscriptMismatch);
    }
    validate_gateway_formal_real_command_lane_summary_readback(stdout_summary, "stdout")?;
    validate_gateway_formal_real_command_lane_summary_readback(stderr_summary, "stderr")?;
    validate_gateway_formal_real_command_lane_redaction_report(
        redaction_report,
        stdout_summary,
        stderr_summary,
    )?;
    validate_gateway_formal_real_command_lane_solver_verdict_readback(solver_verdict, request)?;
    validate_gateway_formal_real_command_lane_nonpromotion_readback(nonpromotion)?;
    validate_gateway_formal_real_command_lane_validation_report_readback(
        validation_report,
        manifest,
        request,
        source_execution_manifest,
        command,
        obligation_binding,
        transcript,
        solver_verdict,
        stdout_summary,
        stderr_summary,
        redaction_report,
        nonpromotion,
    )?;
    let nonclaims = declared_gateway_formal_real_command_lane_bytes(
        files,
        "gateway-formal-real-command-lane/nonclaims.md",
    )?;
    if nonclaims
        != gateway_formal_real_command_lane_nonclaims_markdown(&request.required_nonclaims)
            .as_bytes()
    {
        return Err(GatewayFormalRealCommandLaneOutputError::NonclaimMismatch);
    }
    Ok(())
}

fn validate_gateway_formal_real_command_lane_summary_readback(
    summary: &GatewayFormalRealCommandLaneBoundedSummary,
    stream_label: &str,
) -> Result<(), GatewayFormalRealCommandLaneOutputError> {
    let mut issues = Vec::new();
    validate_gateway_formal_real_command_lane_summary(summary, stream_label, &mut issues);
    if issues.is_empty() {
        Ok(())
    } else if stream_label == "stdout" {
        Err(GatewayFormalRealCommandLaneOutputError::StdoutSummaryMismatch)
    } else {
        Err(GatewayFormalRealCommandLaneOutputError::StderrSummaryMismatch)
    }
}

fn validate_gateway_formal_real_command_lane_solver_verdict_readback(
    verdict: &GatewayFormalRealCommandLaneSolverVerdict,
    request: &GatewayFormalRealCommandLaneRequest,
) -> Result<(), GatewayFormalRealCommandLaneOutputError> {
    let mut issues = Vec::new();
    validate_gateway_formal_real_command_lane_solver_verdict(verdict, request, &mut issues);
    if issues.is_empty() {
        Ok(())
    } else {
        Err(GatewayFormalRealCommandLaneOutputError::SolverVerdictMismatch)
    }
}

fn validate_gateway_formal_real_command_lane_nonpromotion_readback(
    nonpromotion: &GatewayFormalRealCommandLaneNonpromotionReport,
) -> Result<(), GatewayFormalRealCommandLaneOutputError> {
    let mut issues = Vec::new();
    validate_gateway_formal_real_command_lane_nonpromotion(nonpromotion, &mut issues);
    if issues.is_empty() {
        Ok(())
    } else {
        Err(GatewayFormalRealCommandLaneOutputError::NonpromotionReportMismatch)
    }
}

#[allow(clippy::too_many_arguments)]
fn validate_gateway_formal_real_command_lane_validation_report_readback(
    report: &GatewayFormalRealCommandLaneValidationReport,
    manifest: &GatewayFormalRealCommandLaneOutputManifest,
    request: &GatewayFormalRealCommandLaneRequest,
    source_execution_manifest: &GatewayFormalBackendTinyHermeticExecutionOutputManifest,
    command: &GatewayFormalRealCommandLaneCommandDescriptor,
    obligation_binding: &GatewayFormalRealCommandLaneObligationBinding,
    transcript: &GatewayFormalRealCommandLaneTranscript,
    solver_verdict: &GatewayFormalRealCommandLaneSolverVerdict,
    stdout_summary: &GatewayFormalRealCommandLaneBoundedSummary,
    stderr_summary: &GatewayFormalRealCommandLaneBoundedSummary,
    redaction_report: &GatewayFormalRealCommandLaneRedactionReport,
    nonpromotion: &GatewayFormalRealCommandLaneNonpromotionReport,
) -> Result<(), GatewayFormalRealCommandLaneOutputError> {
    let expected = GatewayFormalRealCommandLaneValidationReport {
        schema_version: GATEWAY_FORMAL_REAL_COMMAND_LANE_OUTPUT_SCHEMA_VERSION.to_owned(),
        run_id: manifest.run_id.clone(),
        valid: true,
        issue_count: 0,
        checked_files: gateway_formal_real_command_lane_declared_files(),
        request_digest: request.digest(),
        source_adapter_manifest_digest: request.source_adapter_manifest_digest,
        source_execution_manifest_digest: source_execution_manifest.digest(),
        command_descriptor_digest: command.digest(),
        obligation_digest: request.obligation_digest,
        obligation_binding_digest: obligation_binding.digest(),
        transcript_digest: transcript.digest(),
        solver_verdict_digest: solver_verdict.digest(),
        stdout_summary_digest: stdout_summary.digest(),
        stderr_summary_digest: stderr_summary.digest(),
        redaction_report_digest: redaction_report.digest(),
        nonpromotion_report_digest: nonpromotion.digest(),
        claim_boundary: gateway_formal_real_command_lane_claim_boundary(),
        process_spawned: false,
        backend_executed: false,
        creates_accepted_evidence: false,
        creates_level2_evidence: false,
        populates_score_axes: false,
        grants_authority: false,
    };
    if report != &expected {
        return Err(GatewayFormalRealCommandLaneOutputError::ValidationReportMismatch);
    }
    Ok(())
}

fn declared_gateway_formal_real_command_lane_bytes<'a>(
    files: &'a BTreeMap<String, Vec<u8>>,
    logical_path: &str,
) -> Result<&'a [u8], GatewayFormalRealCommandLaneOutputError> {
    files.get(logical_path).map(Vec::as_slice).ok_or_else(|| {
        GatewayFormalRealCommandLaneOutputError::Io(format!(
            "declared file missing: {logical_path}"
        ))
    })
}

fn parse_gateway_formal_real_command_lane_declared_json<
    T: for<'de> Deserialize<'de> + Serialize,
>(
    files: &BTreeMap<String, Vec<u8>>,
    logical_path: &str,
) -> Result<T, GatewayFormalRealCommandLaneOutputError> {
    let bytes = declared_gateway_formal_real_command_lane_bytes(files, logical_path)?;
    let original = parse_json_value_rejecting_duplicate_keys(bytes).map_err(|_| {
        GatewayFormalRealCommandLaneOutputError::MalformedDeclaredFile(logical_path.to_owned())
    })?;
    let parsed: T = serde_json::from_value(original.clone()).map_err(|_| {
        GatewayFormalRealCommandLaneOutputError::MalformedDeclaredFile(logical_path.to_owned())
    })?;
    let canonical =
        serde_json::to_value(&parsed).map_err(gateway_formal_real_command_lane_serde_error)?;
    if canonical != original {
        return Err(
            GatewayFormalRealCommandLaneOutputError::MalformedDeclaredFile(logical_path.to_owned()),
        );
    }
    Ok(parsed)
}

fn gateway_formal_real_command_lane_nonclaims_markdown(
    nonclaims: &BTreeSet<NonClaimLabel>,
) -> String {
    let mut out = String::from("# Gateway Real Formal Command Lane Non-Claims\n\n");
    for nonclaim in nonclaims {
        out.push_str("- ");
        out.push_str(&nonclaim.0);
        out.push('\n');
    }
    out
}

fn reject_undeclared_gateway_formal_real_command_lane_files(
    output_root: &Path,
) -> Result<(), GatewayFormalRealCommandLaneOutputError> {
    let mut declared: BTreeSet<String> = GATEWAY_FORMAL_REAL_COMMAND_LANE_DECLARED_FILES
        .iter()
        .chain(GATEWAY_FORMAL_REAL_COMMAND_LANE_DECLARED_SIDECARS.iter())
        .map(|value| (*value).to_owned())
        .collect();
    let bundle_dir = output_root.join("gateway-formal-real-command-lane");
    for entry in fs::read_dir(&bundle_dir).map_err(gateway_formal_real_command_lane_io_error)? {
        let entry = entry.map_err(gateway_formal_real_command_lane_io_error)?;
        let logical_path = entry
            .path()
            .strip_prefix(output_root)
            .map_err(|error| GatewayFormalRealCommandLaneOutputError::Io(error.to_string()))?
            .to_string_lossy()
            .replace('\\', "/");
        if !declared.remove(&logical_path) {
            return Err(GatewayFormalRealCommandLaneOutputError::UndeclaredFile(
                logical_path,
            ));
        }
    }
    if let Some(missing) = declared.into_iter().next() {
        return Err(GatewayFormalRealCommandLaneOutputError::Io(format!(
            "declared file missing: {missing}"
        )));
    }
    Ok(())
}

fn validate_gateway_formal_real_command_lane_output_root(
    output_root: &Path,
    protected_roots: &[PathBuf],
    overwrite: bool,
) -> Result<(), GatewayFormalRealCommandLaneOutputError> {
    match validate_output_root(output_root, protected_roots, overwrite) {
        Ok(()) => Ok(()),
        Err(AdmissionJournalMaterializationError::EmptyOutputRoot) => {
            Err(GatewayFormalRealCommandLaneOutputError::EmptyOutputRoot)
        }
        Err(AdmissionJournalMaterializationError::ProtectedOutputRoot) => {
            Err(GatewayFormalRealCommandLaneOutputError::ProtectedOutputRoot)
        }
        Err(AdmissionJournalMaterializationError::OutputRootExistsWithoutOverwrite) => {
            Err(GatewayFormalRealCommandLaneOutputError::OutputRootExistsWithoutOverwrite)
        }
        Err(AdmissionJournalMaterializationError::OutputRootIsFile) => {
            Err(GatewayFormalRealCommandLaneOutputError::OutputRootIsFile)
        }
        Err(AdmissionJournalMaterializationError::OutputRootIsSymlink) => {
            Err(GatewayFormalRealCommandLaneOutputError::OutputRootIsSymlink)
        }
        Err(AdmissionJournalMaterializationError::Io(error)) => {
            Err(GatewayFormalRealCommandLaneOutputError::Io(error))
        }
        Err(other) => Err(GatewayFormalRealCommandLaneOutputError::Io(format!(
            "{other:?}"
        ))),
    }
}

fn gateway_formal_real_command_lane_staging_root_for(
    output_root: &Path,
    run_id: &str,
) -> Result<PathBuf, GatewayFormalRealCommandLaneOutputError> {
    let parent = output_root
        .parent()
        .ok_or(GatewayFormalRealCommandLaneOutputError::EmptyOutputRoot)?;
    let name = output_root
        .file_name()
        .map(|value| value.to_string_lossy().into_owned())
        .ok_or(GatewayFormalRealCommandLaneOutputError::EmptyOutputRoot)?;
    Ok(parent.join(format!(".{name}.{run_id}.staging")))
}

fn remove_gateway_formal_real_command_lane_dir_all_checked(
    path: &Path,
) -> Result<(), GatewayFormalRealCommandLaneOutputError> {
    if !path.exists() {
        return Ok(());
    }
    if fs::symlink_metadata(path)
        .map_err(gateway_formal_real_command_lane_io_error)?
        .file_type()
        .is_symlink()
    {
        return Err(GatewayFormalRealCommandLaneOutputError::OutputRootIsSymlink);
    }
    fs::remove_dir_all(path).map_err(gateway_formal_real_command_lane_io_error)
}

fn gateway_formal_real_command_lane_io_error(
    error: io::Error,
) -> GatewayFormalRealCommandLaneOutputError {
    GatewayFormalRealCommandLaneOutputError::Io(error.to_string())
}

fn gateway_formal_real_command_lane_serde_error(
    error: serde_json::Error,
) -> GatewayFormalRealCommandLaneOutputError {
    GatewayFormalRealCommandLaneOutputError::Serialization(error.to_string())
}

fn build_gateway_formal_backend_hermetic_fixture_runner_bundle_files(
    interface: &GatewayFormalBackendHermeticProcessSpawnInterface,
    descriptor: &GatewayFormalBackendHermeticExecutionDescriptor,
    descriptor_report_manifest: &GatewayFormalBackendHermeticDescriptorReportOutputManifest,
    _source_result_quarantine_manifest: &GatewayFormalBackendHermeticExecutionResultQuarantineOutputManifest,
    request: &GatewayFormalBackendHermeticFixtureRunnerRequest,
    process_result: &GatewayFormalBackendHermeticFixtureProcessResult,
) -> Result<BTreeMap<String, Vec<u8>>, GatewayFormalBackendHermeticFixtureRunnerError> {
    let input_binding = gateway_formal_backend_hermetic_execution_result_input_binding(
        descriptor,
        descriptor_report_manifest,
    );
    let command_contract =
        gateway_formal_backend_hermetic_descriptor_report_command_contract(descriptor);
    let output_inventory = gateway_formal_backend_hermetic_execution_result_output_inventory();
    let stdout_summary = gateway_formal_backend_hermetic_fixture_runner_bounded_summary(
        "stdout",
        &process_result.stdout,
        interface.runtime_policy.max_stdout_bytes,
    );
    let stderr_summary = gateway_formal_backend_hermetic_fixture_runner_bounded_summary(
        "stderr",
        &process_result.stderr,
        interface.runtime_policy.max_stderr_bytes,
    );
    let redaction_report = gateway_formal_backend_hermetic_fixture_runner_redaction_report(
        &stdout_summary,
        &stderr_summary,
    );
    let invariant_verdict = gateway_formal_backend_hermetic_fixture_runner_invariant_verdict(
        descriptor,
        process_result,
    );
    let nonpromotion_report =
        gateway_formal_backend_hermetic_execution_result_nonpromotion_report();
    let execution_status = gateway_formal_backend_hermetic_fixture_runner_execution_status(
        descriptor,
        &command_contract,
        &input_binding,
        &output_inventory,
        request,
        process_result,
    );
    let validation_report =
        gateway_formal_backend_hermetic_fixture_runner_output_validation_report(request);
    let nonclaims = gateway_formal_backend_hermetic_fixture_runner_required_nonclaims();
    let nonclaims_md =
        render_gateway_formal_backend_hermetic_execution_result_quarantine_nonclaims(&nonclaims);
    let mut files = BTreeMap::from([
        (
            "gateway-formal-backend-hermetic-execution-result-quarantine/execution-status.json"
                .to_owned(),
            serde_json::to_vec_pretty(&execution_status)
                .map_err(gateway_formal_backend_hermetic_fixture_runner_serde_error)?,
        ),
        (
            "gateway-formal-backend-hermetic-execution-result-quarantine/input-binding.json"
                .to_owned(),
            serde_json::to_vec_pretty(&input_binding)
                .map_err(gateway_formal_backend_hermetic_fixture_runner_serde_error)?,
        ),
        (
            "gateway-formal-backend-hermetic-execution-result-quarantine/command-contract.json"
                .to_owned(),
            serde_json::to_vec_pretty(&command_contract)
                .map_err(gateway_formal_backend_hermetic_fixture_runner_serde_error)?,
        ),
        (
            "gateway-formal-backend-hermetic-execution-result-quarantine/stdout-summary.json"
                .to_owned(),
            serde_json::to_vec_pretty(&stdout_summary)
                .map_err(gateway_formal_backend_hermetic_fixture_runner_serde_error)?,
        ),
        (
            "gateway-formal-backend-hermetic-execution-result-quarantine/stderr-summary.json"
                .to_owned(),
            serde_json::to_vec_pretty(&stderr_summary)
                .map_err(gateway_formal_backend_hermetic_fixture_runner_serde_error)?,
        ),
        (
            "gateway-formal-backend-hermetic-execution-result-quarantine/redaction-report.json"
                .to_owned(),
            serde_json::to_vec_pretty(&redaction_report)
                .map_err(gateway_formal_backend_hermetic_fixture_runner_serde_error)?,
        ),
        (
            "gateway-formal-backend-hermetic-execution-result-quarantine/output-inventory.json"
                .to_owned(),
            serde_json::to_vec_pretty(&output_inventory)
                .map_err(gateway_formal_backend_hermetic_fixture_runner_serde_error)?,
        ),
        (
            "gateway-formal-backend-hermetic-execution-result-quarantine/invariant-verdict.json"
                .to_owned(),
            serde_json::to_vec_pretty(&invariant_verdict)
                .map_err(gateway_formal_backend_hermetic_fixture_runner_serde_error)?,
        ),
        (
            "gateway-formal-backend-hermetic-execution-result-quarantine/nonpromotion-report.json"
                .to_owned(),
            serde_json::to_vec_pretty(&nonpromotion_report)
                .map_err(gateway_formal_backend_hermetic_fixture_runner_serde_error)?,
        ),
        (
            "gateway-formal-backend-hermetic-execution-result-quarantine/validation.json"
                .to_owned(),
            serde_json::to_vec_pretty(&validation_report)
                .map_err(gateway_formal_backend_hermetic_fixture_runner_serde_error)?,
        ),
        (
            "gateway-formal-backend-hermetic-execution-result-quarantine/nonclaims.md".to_owned(),
            nonclaims_md.into_bytes(),
        ),
    ]);
    let manifest = gateway_formal_backend_hermetic_fixture_runner_output_manifest_for_files(
        descriptor,
        descriptor_report_manifest,
        &input_binding,
        &command_contract,
        &execution_status,
        &stdout_summary,
        &stderr_summary,
        &redaction_report,
        &output_inventory,
        &invariant_verdict,
        &nonpromotion_report,
        &validation_report,
        request,
        &files,
    );
    files.insert(
        "gateway-formal-backend-hermetic-execution-result-quarantine/manifest.json".to_owned(),
        serde_json::to_vec_pretty(&manifest)
            .map_err(gateway_formal_backend_hermetic_fixture_runner_serde_error)?,
    );
    Ok(files)
}

fn gateway_formal_backend_hermetic_fixture_runner_bounded_summary(
    stream_label: &str,
    bytes: &[u8],
    max_bytes: u64,
) -> GatewayFormalBackendHermeticExecutionResultBoundedSummary {
    let retained_len = bytes.len().min(max_bytes as usize);
    let retained = &bytes[..retained_len];
    GatewayFormalBackendHermeticExecutionResultBoundedSummary {
        stream_label: stream_label.to_owned(),
        retained_text: format!(
            "{stream_label} summary only: captured_bytes={}; retained_bytes={retained_len}; retained_sha256={}",
            bytes.len(),
            hash_hex(hash_bytes(retained))
        ),
        retained_bytes: retained_len as u64,
        max_bytes,
        truncated: bytes.len() > retained_len,
        raw_retained: false,
        secret_scan_passed: !looks_like_credential_value(&String::from_utf8_lossy(bytes)),
        raw_solver_trace_retained: false,
        proof_artifact_retained: false,
        checker_transcript_retained: false,
        claim_boundary: gateway_formal_backend_hermetic_fixture_runner_claim_boundary(),
    }
}

fn gateway_formal_backend_hermetic_fixture_runner_redaction_report(
    stdout_summary: &GatewayFormalBackendHermeticExecutionResultBoundedSummary,
    stderr_summary: &GatewayFormalBackendHermeticExecutionResultBoundedSummary,
) -> GatewayFormalBackendHermeticExecutionResultRedactionReport {
    GatewayFormalBackendHermeticExecutionResultRedactionReport {
        valid: stdout_summary.secret_scan_passed && stderr_summary.secret_scan_passed,
        stdout_summary_bounded: true,
        stderr_summary_bounded: true,
        credential_looking_value_found: false,
        secret_looking_value_found: false,
        raw_solver_trace_found: false,
        proof_artifact_found: false,
        checker_transcript_found: false,
        solver_certificate_found: false,
        retained_summary_only: true,
        claim_boundary: gateway_formal_backend_hermetic_fixture_runner_claim_boundary(),
    }
}

