        || execution_status.process_exit_code_label.trim().is_empty()
        || execution_status.solver_status
            == GatewayFormalBackendHermeticExecutionSolverStatus::NotRun
        || execution_status.invariant_verdict
            != GatewayFormalBackendHermeticExecutionInvariantVerdict::NotEvaluated
        || execution_status.command_contract_digest != command_contract.digest()
