        || output_inventory.raw_solver_trace_retained
        || output_inventory.raw_prover_log_retained
        || output_inventory.raw_checker_log_retained
        || output_inventory.proof_artifact_retained
        || output_inventory.checker_transcript_retained
        || output_inventory.solver_certificate_retained
        || output_inventory.accepted_evidence_file_retained
        || output_inventory.level2_evidence_file_retained
