fn gateway_formal_correspondence_declared_files() -> Vec<String> {
    GATEWAY_FORMAL_CORRESPONDENCE_DECLARED_FILES
        .iter()
        .map(|value| (*value).to_owned())
        .collect()
}

fn validate_gateway_formal_correspondence_output_request(
    output_root: &Path,
    certificate: &GatewayFormalCorrespondenceCertificate,
    request: &GatewayFormalCorrespondenceOutputRequest,
) -> Result<(), GatewayFormalCorrespondenceOutputError> {
    if request.bundle_id.trim().is_empty()
        || !is_safe_relative_path(&request.bundle_id)
        || request.bundle_id.contains(['/', '\\'])
    {
        return Err(GatewayFormalCorrespondenceOutputError::EmptyBundleId);
    }
    let validation = validate_gateway_formal_correspondence_certificate(certificate);
    if !validation.valid {
        return Err(GatewayFormalCorrespondenceOutputError::InvalidCertificate(
            validation.issues,
        ));
    }
    validate_gateway_formal_correspondence_output_root(
        output_root,
        &request.protected_roots,
        request.overwrite,
    )
}

fn build_gateway_formal_correspondence_bundle_files(
    certificate: &GatewayFormalCorrespondenceCertificate,
    request: &GatewayFormalCorrespondenceOutputRequest,
) -> Result<BTreeMap<String, Vec<u8>>, GatewayFormalCorrespondenceOutputError> {
    let validation = validate_gateway_formal_correspondence_certificate(certificate);
    if !validation.valid {
        return Err(GatewayFormalCorrespondenceOutputError::InvalidCertificate(
            validation.issues,
        ));
    }

    let validation_report = gateway_formal_correspondence_output_validation_report(
        certificate,
        request,
        validation.issues.len() as u64,
    );
    let redaction_report = gateway_formal_correspondence_redaction_report();
    let source_files = certificate.source_files.clone();
    let source_anchors = certificate.source_anchors.clone();
    let proof_obligations = certificate.proof_obligations.clone();
    let assumptions = render_gateway_formal_correspondence_assumptions(certificate).into_bytes();
    let nonclaims =
        render_gateway_formal_correspondence_nonclaims(&certificate.nonclaims).into_bytes();

    let mut files = BTreeMap::from([
        (
            "gateway-formal-correspondence/certificate.json".to_owned(),
            serde_json::to_vec_pretty(certificate)
                .map_err(gateway_formal_correspondence_serde_error)?,
        ),
        (
            "gateway-formal-correspondence/validation-report.json".to_owned(),
            serde_json::to_vec_pretty(&validation_report)
                .map_err(gateway_formal_correspondence_serde_error)?,
        ),
        (
            "gateway-formal-correspondence/source-files.json".to_owned(),
            serde_json::to_vec_pretty(&source_files)
                .map_err(gateway_formal_correspondence_serde_error)?,
        ),
        (
            "gateway-formal-correspondence/source-anchors.json".to_owned(),
            serde_json::to_vec_pretty(&source_anchors)
                .map_err(gateway_formal_correspondence_serde_error)?,
        ),
        (
            "gateway-formal-correspondence/proof-obligations.json".to_owned(),
            serde_json::to_vec_pretty(&proof_obligations)
                .map_err(gateway_formal_correspondence_serde_error)?,
        ),
        (
            "gateway-formal-correspondence/assumptions.md".to_owned(),
            assumptions,
        ),
        (
            "gateway-formal-correspondence/nonclaims.md".to_owned(),
            nonclaims,
        ),
        (
            "gateway-formal-correspondence/redaction-report.json".to_owned(),
            serde_json::to_vec_pretty(&redaction_report)
                .map_err(gateway_formal_correspondence_serde_error)?,
        ),
    ]);
    let manifest =
        gateway_formal_correspondence_output_manifest_for_files(certificate, request, &files);
    files.insert(
        "gateway-formal-correspondence/manifest.json".to_owned(),
        serde_json::to_vec_pretty(&manifest).map_err(gateway_formal_correspondence_serde_error)?,
    );
    Ok(files)
}

fn gateway_formal_correspondence_output_validation_report(
    certificate: &GatewayFormalCorrespondenceCertificate,
    request: &GatewayFormalCorrespondenceOutputRequest,
    issue_count: u64,
) -> GatewayFormalCorrespondenceOutputValidationReport {
    GatewayFormalCorrespondenceOutputValidationReport {
        schema_version: GATEWAY_FORMAL_CORRESPONDENCE_OUTPUT_VALIDATION_SCHEMA_VERSION.to_owned(),
        bundle_id: request.bundle_id.clone(),
        certificate_digest: certificate.digest(),
        valid: issue_count == 0,
        issue_count,
        checked_files: gateway_formal_correspondence_declared_files(),
        claim_boundary: GATEWAY_FORMAL_CORRESPONDENCE_OUTPUT_CLAIM_BOUNDARY.to_owned(),
        creates_formal_proof: false,
        mutates_accepted_evidence_ledger: false,
        creates_level2_evidence: false,
        populates_score_axes: false,
        grants_authority: false,
    }
}

fn gateway_formal_correspondence_redaction_report() -> GatewayFormalCorrespondenceRedactionReport {
    GatewayFormalCorrespondenceRedactionReport {
        retains_credentials_or_secrets: false,
        retains_raw_prover_logs: false,
        retains_raw_solver_transcripts: false,
        retains_raw_external_repo_source: false,
        retains_proof_assistant_cache: false,
        retains_live_provider_responses: false,
        retains_accepted_evidence_ledger_json: false,
        retains_benchmark_outputs: false,
    }
}

fn gateway_formal_correspondence_output_manifest_for_files(
    certificate: &GatewayFormalCorrespondenceCertificate,
    request: &GatewayFormalCorrespondenceOutputRequest,
    files: &BTreeMap<String, Vec<u8>>,
) -> GatewayFormalCorrespondenceOutputManifest {
    let mut declared_file_digests = BTreeMap::new();
    for (logical_path, bytes) in files {
        declared_file_digests.insert(logical_path.clone(), hash_bytes(bytes));
    }
    GatewayFormalCorrespondenceOutputManifest {
        schema_version: GATEWAY_FORMAL_CORRESPONDENCE_OUTPUT_SCHEMA_VERSION.to_owned(),
        bundle_id: request.bundle_id.clone(),
        created_at_unix: request.created_at_unix,
        certificate_digest: certificate.digest(),
        validation_report_digest: hash_bytes(
            files
                .get("gateway-formal-correspondence/validation-report.json")
                .map(Vec::as_slice)
                .unwrap_or_default(),
        ),
        source_files_digest: hash_bytes(
            files
                .get("gateway-formal-correspondence/source-files.json")
                .map(Vec::as_slice)
                .unwrap_or_default(),
        ),
        source_anchors_digest: hash_bytes(
            files
                .get("gateway-formal-correspondence/source-anchors.json")
                .map(Vec::as_slice)
                .unwrap_or_default(),
        ),
        proof_obligations_digest: hash_bytes(
            files
                .get("gateway-formal-correspondence/proof-obligations.json")
                .map(Vec::as_slice)
                .unwrap_or_default(),
        ),
        assumptions_digest: hash_bytes(
            files
                .get("gateway-formal-correspondence/assumptions.md")
                .map(Vec::as_slice)
                .unwrap_or_default(),
        ),
        nonclaims_digest: hash_bytes(
            files
                .get("gateway-formal-correspondence/nonclaims.md")
                .map(Vec::as_slice)
                .unwrap_or_default(),
        ),
        redaction_report_digest: hash_bytes(
            files
                .get("gateway-formal-correspondence/redaction-report.json")
                .map(Vec::as_slice)
                .unwrap_or_default(),
        ),
        declared_files: gateway_formal_correspondence_declared_files(),
        declared_file_digests,
        claim_boundary: GATEWAY_FORMAL_CORRESPONDENCE_OUTPUT_CLAIM_BOUNDARY.to_owned(),
        creates_formal_proof: false,
        mutates_accepted_evidence_ledger: false,
        creates_level2_evidence: false,
        populates_score_axes: false,
        grants_authority: false,
        nonclaims: certificate.nonclaims.clone(),
    }
}

fn validate_gateway_formal_correspondence_bundle_semantics(
    files: &BTreeMap<String, Vec<u8>>,
) -> Result<GatewayFormalCorrespondenceOutputManifest, GatewayFormalCorrespondenceOutputError> {
    let manifest: GatewayFormalCorrespondenceOutputManifest =
        parse_gateway_formal_correspondence_declared_json(
            files,
            "gateway-formal-correspondence/manifest.json",
        )?;
    let certificate: GatewayFormalCorrespondenceCertificate =
        parse_gateway_formal_correspondence_declared_json(
            files,
            "gateway-formal-correspondence/certificate.json",
        )?;
    let validation = validate_gateway_formal_correspondence_certificate(&certificate);
    if !validation.valid {
        return Err(GatewayFormalCorrespondenceOutputError::InvalidCertificate(
            validation.issues,
        ));
    }

    let source_files: Vec<GatewayFormalSourceFileDigest> =
        parse_gateway_formal_correspondence_declared_json(
            files,
            "gateway-formal-correspondence/source-files.json",
        )?;
    if source_files != certificate.source_files {
        return Err(GatewayFormalCorrespondenceOutputError::ManifestSemanticMismatch);
    }

    let source_anchors: Vec<GatewayFormalSourceAnchor> =
        parse_gateway_formal_correspondence_declared_json(
            files,
            "gateway-formal-correspondence/source-anchors.json",
        )?;
    if source_anchors != certificate.source_anchors {
        return Err(GatewayFormalCorrespondenceOutputError::ManifestSemanticMismatch);
    }

    let proof_obligations: BTreeSet<GatewayFormalProofObligationId> =
        parse_gateway_formal_correspondence_declared_json(
            files,
            "gateway-formal-correspondence/proof-obligations.json",
        )?;
    if proof_obligations != certificate.proof_obligations {
        return Err(GatewayFormalCorrespondenceOutputError::ManifestSemanticMismatch);
    }

    if declared_gateway_formal_correspondence_bytes(
        files,
        "gateway-formal-correspondence/assumptions.md",
    )? != render_gateway_formal_correspondence_assumptions(&certificate).as_bytes()
    {
        return Err(GatewayFormalCorrespondenceOutputError::ManifestSemanticMismatch);
    }

    if declared_gateway_formal_correspondence_bytes(
        files,
        "gateway-formal-correspondence/nonclaims.md",
    )? != render_gateway_formal_correspondence_nonclaims(&certificate.nonclaims).as_bytes()
    {
        return Err(GatewayFormalCorrespondenceOutputError::NonclaimMismatch);
    }

    let redaction_report: GatewayFormalCorrespondenceRedactionReport =
        parse_gateway_formal_correspondence_declared_json(
            files,
            "gateway-formal-correspondence/redaction-report.json",
        )?;
    if redaction_report != gateway_formal_correspondence_redaction_report() {
        return Err(GatewayFormalCorrespondenceOutputError::RedactionReportMismatch);
    }

    let expected_request = GatewayFormalCorrespondenceOutputRequest {
        bundle_id: manifest.bundle_id.clone(),
        created_at_unix: manifest.created_at_unix,
        overwrite: false,
        protected_roots: Vec::new(),
    };
    let expected_validation =
        gateway_formal_correspondence_output_validation_report(&certificate, &expected_request, 0);
    let validation_report: GatewayFormalCorrespondenceOutputValidationReport =
        parse_gateway_formal_correspondence_declared_json(
            files,
            "gateway-formal-correspondence/validation-report.json",
        )?;
    if validation_report != expected_validation {
        return Err(GatewayFormalCorrespondenceOutputError::ValidationReportMismatch);
    }

    validate_gateway_formal_correspondence_manifest_semantics(&manifest, &certificate, files)?;
    Ok(manifest)
}

fn validate_gateway_formal_correspondence_manifest_semantics(
    manifest: &GatewayFormalCorrespondenceOutputManifest,
    certificate: &GatewayFormalCorrespondenceCertificate,
    files: &BTreeMap<String, Vec<u8>>,
) -> Result<(), GatewayFormalCorrespondenceOutputError> {
    let expected_digest_paths: BTreeSet<String> = GATEWAY_FORMAL_CORRESPONDENCE_DECLARED_FILES
        .iter()
        .filter(|path| **path != "gateway-formal-correspondence/manifest.json")
        .map(|path| (*path).to_owned())
        .collect();
    let actual_digest_paths: BTreeSet<String> =
        manifest.declared_file_digests.keys().cloned().collect();
    if manifest.schema_version != GATEWAY_FORMAL_CORRESPONDENCE_OUTPUT_SCHEMA_VERSION
        || manifest.certificate_digest != certificate.digest()
        || manifest.validation_report_digest
            != hash_bytes(declared_gateway_formal_correspondence_bytes(
                files,
                "gateway-formal-correspondence/validation-report.json",
            )?)
        || manifest.source_files_digest
            != hash_bytes(declared_gateway_formal_correspondence_bytes(
                files,
                "gateway-formal-correspondence/source-files.json",
            )?)
        || manifest.source_anchors_digest
            != hash_bytes(declared_gateway_formal_correspondence_bytes(
                files,
                "gateway-formal-correspondence/source-anchors.json",
            )?)
        || manifest.proof_obligations_digest
            != hash_bytes(declared_gateway_formal_correspondence_bytes(
                files,
                "gateway-formal-correspondence/proof-obligations.json",
            )?)
        || manifest.assumptions_digest
            != hash_bytes(declared_gateway_formal_correspondence_bytes(
                files,
                "gateway-formal-correspondence/assumptions.md",
            )?)
        || manifest.nonclaims_digest
            != hash_bytes(declared_gateway_formal_correspondence_bytes(
                files,
                "gateway-formal-correspondence/nonclaims.md",
            )?)
        || manifest.redaction_report_digest
            != hash_bytes(declared_gateway_formal_correspondence_bytes(
                files,
                "gateway-formal-correspondence/redaction-report.json",
            )?)
        || manifest.declared_files != gateway_formal_correspondence_declared_files()
        || actual_digest_paths != expected_digest_paths
        || manifest
            .declared_file_digests
            .values()
            .any(|digest| *digest == Hash([0; 32]))
        || manifest.claim_boundary != GATEWAY_FORMAL_CORRESPONDENCE_OUTPUT_CLAIM_BOUNDARY
        || manifest.creates_formal_proof
        || manifest.mutates_accepted_evidence_ledger
        || manifest.creates_level2_evidence
        || manifest.populates_score_axes
        || manifest.grants_authority
        || manifest.nonclaims != certificate.nonclaims
    {
        return Err(GatewayFormalCorrespondenceOutputError::ManifestSemanticMismatch);
    }
    for (logical_path, expected_digest) in &manifest.declared_file_digests {
        if hash_bytes(declared_gateway_formal_correspondence_bytes(
            files,
            logical_path,
        )?) != *expected_digest
        {
            return Err(GatewayFormalCorrespondenceOutputError::DigestMismatch(
                logical_path.clone(),
            ));
        }
    }
    Ok(())
}

fn render_gateway_formal_correspondence_assumptions(
    certificate: &GatewayFormalCorrespondenceCertificate,
) -> String {
    let mut out = String::from("# Gateway Formal Correspondence Assumptions\n\n");
    out.push_str("## Trusted Assumptions\n\n");
    for assumption in &certificate.trusted_assumptions {
        out.push_str("- ");
        out.push_str(assumption);
        out.push('\n');
    }
    out.push_str("\n## Modeled Replacements\n\n");
    for replacement in &certificate.modeled_replacements {
        out.push_str("- ");
        out.push_str(replacement);
        out.push('\n');
    }
    out.push_str("\n## Unsupported Rust Features\n\n");
    for feature in &certificate.unsupported_rust_features {
        out.push_str("- ");
        out.push_str(feature);
        out.push('\n');
    }
    out
}

fn render_gateway_formal_correspondence_nonclaims(nonclaims: &BTreeSet<NonClaimLabel>) -> String {
    let mut out = String::from("# Gateway Formal Correspondence Nonclaims\n\n");
    for nonclaim in nonclaims {
        out.push_str("- ");
        out.push_str(&nonclaim.0);
        out.push('\n');
    }
    out
}

fn declared_gateway_formal_correspondence_bytes<'a>(
    files: &'a BTreeMap<String, Vec<u8>>,
    logical_path: &str,
) -> Result<&'a [u8], GatewayFormalCorrespondenceOutputError> {
    files.get(logical_path).map(Vec::as_slice).ok_or_else(|| {
        GatewayFormalCorrespondenceOutputError::Io(format!("declared file missing: {logical_path}"))
    })
}

fn parse_gateway_formal_correspondence_declared_json<T: for<'de> Deserialize<'de>>(
    files: &BTreeMap<String, Vec<u8>>,
    logical_path: &str,
) -> Result<T, GatewayFormalCorrespondenceOutputError> {
    let bytes = declared_gateway_formal_correspondence_bytes(files, logical_path)?;
    let text = std::str::from_utf8(bytes).map_err(|_| {
        GatewayFormalCorrespondenceOutputError::MalformedDeclaredFile(logical_path.to_owned())
    })?;
    serde_json::from_str(text).map_err(|_| {
        GatewayFormalCorrespondenceOutputError::MalformedDeclaredFile(logical_path.to_owned())
    })
}

fn reject_undeclared_gateway_formal_correspondence_files(
    output_root: &Path,
) -> Result<(), GatewayFormalCorrespondenceOutputError> {
    let mut declared: BTreeSet<String> = GATEWAY_FORMAL_CORRESPONDENCE_DECLARED_FILES
        .iter()
        .chain(GATEWAY_FORMAL_CORRESPONDENCE_DECLARED_SIDECARS.iter())
        .map(|value| (*value).to_owned())
        .collect();
    let bundle_dir = output_root.join("gateway-formal-correspondence");
    for entry in fs::read_dir(&bundle_dir).map_err(gateway_formal_correspondence_io_error)? {
        let entry = entry.map_err(gateway_formal_correspondence_io_error)?;
        let logical_path = entry
            .path()
            .strip_prefix(output_root)
            .map_err(|error| GatewayFormalCorrespondenceOutputError::Io(error.to_string()))?
            .to_string_lossy()
            .replace('\\', "/");
        if !declared.remove(&logical_path) {
            return Err(GatewayFormalCorrespondenceOutputError::UndeclaredFile(
                logical_path,
            ));
        }
    }
    if let Some(missing) = declared.into_iter().next() {
        return Err(GatewayFormalCorrespondenceOutputError::Io(format!(
            "declared file missing: {missing}"
        )));
    }
    Ok(())
}

fn validate_gateway_formal_correspondence_output_root(
    output_root: &Path,
    protected_roots: &[PathBuf],
    overwrite: bool,
) -> Result<(), GatewayFormalCorrespondenceOutputError> {
    match validate_output_root(output_root, protected_roots, overwrite) {
        Ok(()) => Ok(()),
        Err(AdmissionJournalMaterializationError::EmptyOutputRoot) => {
            Err(GatewayFormalCorrespondenceOutputError::EmptyOutputRoot)
        }
        Err(AdmissionJournalMaterializationError::ProtectedOutputRoot) => {
            Err(GatewayFormalCorrespondenceOutputError::ProtectedOutputRoot)
        }
        Err(AdmissionJournalMaterializationError::OutputRootExistsWithoutOverwrite) => {
            Err(GatewayFormalCorrespondenceOutputError::OutputRootExistsWithoutOverwrite)
        }
        Err(AdmissionJournalMaterializationError::OutputRootIsFile) => {
            Err(GatewayFormalCorrespondenceOutputError::OutputRootIsFile)
        }
        Err(AdmissionJournalMaterializationError::OutputRootIsSymlink) => {
            Err(GatewayFormalCorrespondenceOutputError::OutputRootIsSymlink)
        }
        Err(AdmissionJournalMaterializationError::Io(error)) => {
            Err(GatewayFormalCorrespondenceOutputError::Io(error))
        }
        Err(other) => Err(GatewayFormalCorrespondenceOutputError::Io(format!(
            "{other:?}"
        ))),
    }
}

fn gateway_formal_correspondence_staging_root_for(
    output_root: &Path,
    bundle_id: &str,
) -> Result<PathBuf, GatewayFormalCorrespondenceOutputError> {
    let parent = output_root
        .parent()
        .ok_or(GatewayFormalCorrespondenceOutputError::EmptyOutputRoot)?;
    let name = output_root
        .file_name()
        .map(|value| value.to_string_lossy().into_owned())
        .ok_or(GatewayFormalCorrespondenceOutputError::EmptyOutputRoot)?;
    Ok(parent.join(format!(".{name}.{bundle_id}.staging")))
}

fn remove_gateway_formal_correspondence_dir_all_checked(
    path: &Path,
) -> Result<(), GatewayFormalCorrespondenceOutputError> {
    if !path.exists() {
        return Ok(());
    }
    if fs::symlink_metadata(path)
        .map_err(gateway_formal_correspondence_io_error)?
        .file_type()
        .is_symlink()
    {
        return Err(GatewayFormalCorrespondenceOutputError::OutputRootIsSymlink);
    }
    fs::remove_dir_all(path).map_err(gateway_formal_correspondence_io_error)
}

fn gateway_formal_correspondence_io_error(
    error: io::Error,
) -> GatewayFormalCorrespondenceOutputError {
    GatewayFormalCorrespondenceOutputError::Io(error.to_string())
}

fn gateway_formal_correspondence_serde_error(
    error: serde_json::Error,
) -> GatewayFormalCorrespondenceOutputError {
    GatewayFormalCorrespondenceOutputError::Serialization(error.to_string())
}

