    #[test]
    fn phase415_tiny_z3_policy_decision_builds_current_path_forbidden_record() {
        let Some((obligation_root, output_root, candidate)) =
            phase407_candidate_if_z3_available("phase415-decision-valid")
        else {
            return;
        };
        let preview_input = phase409_review_preview_input(
            "phase415-decision-preview",
            &candidate,
            GatewayFormalTinyDigestBackendZ3ReviewPreviewDecisionLabel::ReviewPreviewAcceptCandidateScope,
        );
        let preview =
            build_gateway_formal_tiny_digest_backend_z3_review_preview(&candidate, &preview_input)
                .expect("phase415 preview builds");
        let record_input = phase411_reviewed_record_input("phase415-record", &preview);
        let reviewed_record =
            build_gateway_formal_tiny_digest_backend_z3_reviewed_record(&preview, &record_input)
                .expect("phase415 reviewed record builds");
        let handoff_input = phase413_accepted_handoff_input("phase415-handoff", &reviewed_record);
        let handoff = build_gateway_formal_tiny_digest_backend_z3_accepted_handoff(
            &reviewed_record,
            &handoff_input,
        )
        .expect("phase415 handoff builds");
        let decision_input = phase415_policy_decision_input("phase415-decision", &handoff);
        let decision =
            build_gateway_formal_tiny_digest_backend_z3_policy_decision(&handoff, &decision_input)
                .expect("phase415 policy decision builds");

        assert_eq!(
            decision.state_slice,
            GATEWAY_FORMAL_TINY_DIGEST_BACKEND_Z3_POLICY_DECISION_STATE_SLICE
        );
        assert_eq!(
            decision.previous_promotion_state,
            "future_accepted_formal_evidence_handoff"
        );
        assert_eq!(
            decision.promotion_state,
            "accepted_formal_evidence_policy_decision"
        );
        assert_eq!(
            decision.next_required_state,
            "bounded_formal_evidence_policy_spec"
        );
        assert_eq!(decision.handoff_digest, handoff.digest());
        assert_eq!(decision.handoff_input_digest, handoff.handoff_input_digest);
        assert_eq!(
            decision.policy_decision,
            GatewayFormalTinyDigestBackendZ3FormalAcceptancePolicyDecision::AcceptedFormalEvidenceStillForbidden
        );
        assert_eq!(
            decision.policy_decision_statement,
            gateway_formal_tiny_digest_backend_z3_policy_decision_statement()
        );
        assert_eq!(
            decision.current_accepted_append_blockers,
            gateway_formal_tiny_digest_backend_z3_accepted_handoff_current_blockers()
        );
        assert_eq!(
            decision.claim_boundary,
            gateway_formal_tiny_digest_backend_z3_policy_decision_claim_boundary()
        );
        assert!(!decision.creates_accepted_evidence);
        assert!(!decision.changes_accepted_append_policy);
        assert!(!decision.creates_level2_evidence);
        assert!(!decision.populates_score_axes);
        assert!(!decision.proof_artifact_created);
        assert!(!decision.checker_transcript_created);
        assert!(!decision.solver_certificate_created);
        assert!(!decision.semantic_correctness_claimed);
        assert!(!decision.production_readiness_claimed);
        assert!(!decision.sota_claimed);
        assert!(!decision.breakthrough_claimed);
        assert!(!decision.full_security_claimed);
        assert!(!decision.grants_authority);

        fs::remove_dir_all(&output_root).expect("phase415 decision output cleanup succeeds");
        fs::remove_dir_all(&obligation_root)
            .expect("phase415 decision obligation cleanup succeeds");
    }

    #[test]
    fn phase415_tiny_z3_policy_decision_rejects_drift_and_bounded_approval() {
        let Some((obligation_root, output_root, candidate)) =
            phase407_candidate_if_z3_available("phase415-decision-drift")
        else {
            return;
        };
        let preview_input = phase409_review_preview_input(
            "phase415-drift-preview",
            &candidate,
            GatewayFormalTinyDigestBackendZ3ReviewPreviewDecisionLabel::ReviewPreviewAcceptCandidateScope,
        );
        let preview =
            build_gateway_formal_tiny_digest_backend_z3_review_preview(&candidate, &preview_input)
                .expect("phase415 drift preview builds");
        let record_input = phase411_reviewed_record_input("phase415-drift-record", &preview);
        let reviewed_record =
            build_gateway_formal_tiny_digest_backend_z3_reviewed_record(&preview, &record_input)
                .expect("phase415 drift record builds");
        let handoff_input =
            phase413_accepted_handoff_input("phase415-drift-handoff", &reviewed_record);
        let handoff = build_gateway_formal_tiny_digest_backend_z3_accepted_handoff(
            &reviewed_record,
            &handoff_input,
        )
        .expect("phase415 drift handoff builds");
        let decision_input = phase415_policy_decision_input("phase415-drift-decision", &handoff);

        let mut handoff_drift = decision_input.clone();
        handoff_drift.handoff_digest = Hash([13; 32]);
        let handoff_drift_validation =
            validate_gateway_formal_tiny_digest_backend_z3_policy_decision_input(
                &handoff,
                &handoff_drift,
            );
        assert!(handoff_drift_validation
            .issues
            .contains(&GatewayFormalTinyDigestBackendZ3PolicyDecisionIssue::HandoffDigestDrift));

        let mut policy_drift = decision_input.clone();
        policy_drift.accepted_append_policy_version = "changed-append-policy".to_owned();
        let policy_drift_validation =
            validate_gateway_formal_tiny_digest_backend_z3_policy_decision_input(
                &handoff,
                &policy_drift,
            );
        assert!(policy_drift_validation.issues.contains(
            &GatewayFormalTinyDigestBackendZ3PolicyDecisionIssue::AcceptedAppendPolicyVersionMismatch
        ));

        let mut approved = decision_input.clone();
        approved.policy_decision =
            GatewayFormalTinyDigestBackendZ3FormalAcceptancePolicyDecision::BoundedFormalEvidenceClassApproved;
        approved.bounded_formal_evidence_class_approved = true;
        let approved_validation =
            validate_gateway_formal_tiny_digest_backend_z3_policy_decision_input(
                &handoff, &approved,
            );
        assert!(approved_validation.issues.contains(
            &GatewayFormalTinyDigestBackendZ3PolicyDecisionIssue::PolicyDecisionNotForbidden
        ));
        assert!(approved_validation
            .issues
            .contains(&GatewayFormalTinyDigestBackendZ3PolicyDecisionIssue::PromotionAttempt));

        let mut blocker_drift = decision_input.clone();
        blocker_drift
            .current_accepted_append_blockers
            .remove("formal_evidence_acceptance_policy_unresolved");
        let blocker_validation =
            validate_gateway_formal_tiny_digest_backend_z3_policy_decision_input(
                &handoff,
                &blocker_drift,
            );
        assert!(blocker_validation.issues.contains(
            &GatewayFormalTinyDigestBackendZ3PolicyDecisionIssue::AcceptedAppendBlockerMismatch
        ));

        let mut statement_drift = decision_input.clone();
        statement_drift.policy_decision_statement =
            "tiny-Z3 accepted formal evidence is approved".to_owned();
        statement_drift.policy_decision_statement_digest = hash_tagged(
            "hsai-agent-admission:gateway-formal-tiny-digest-backend-z3-policy-decision-statement:v1",
            &statement_drift.policy_decision_statement,
        );
        let statement_validation =
            validate_gateway_formal_tiny_digest_backend_z3_policy_decision_input(
                &handoff,
                &statement_drift,
            );
        assert!(statement_validation.issues.contains(
            &GatewayFormalTinyDigestBackendZ3PolicyDecisionIssue::PolicyDecisionStatementMismatch
        ));

        let mut promoted_handoff = handoff.clone();
        promoted_handoff.creates_accepted_evidence = true;
        let handoff_state_validation =
            validate_gateway_formal_tiny_digest_backend_z3_policy_decision_input(
                &promoted_handoff,
                &decision_input,
            );
        assert!(handoff_state_validation
            .issues
            .contains(&GatewayFormalTinyDigestBackendZ3PolicyDecisionIssue::HandoffStateMismatch));

        fs::remove_dir_all(&output_root).expect("phase415 drift output cleanup succeeds");
        fs::remove_dir_all(&obligation_root).expect("phase415 drift obligation cleanup succeeds");
    }

