    fn phase529_z3_executable() -> Option<PathBuf> {
        if let Some(path) = std::env::var_os("HSAI_TEST_Z3").map(PathBuf::from) {
            if path.is_file() {
                return Some(path);
            }
        }
        [
            "/opt/homebrew/bin/z3",
            "/usr/local/bin/z3",
            "/usr/bin/z3",
            "/opt/local/bin/z3",
        ]
        .into_iter()
        .map(PathBuf::from)
        .find(|path| path.is_file())
    }

