    fn formal_evidence_local_audit_package_artifact_parts(
        name: &str,
    ) -> (
        PathBuf,
        PathBuf,
        PathBuf,
        PathBuf,
        GatewayFormalRealCommandLaneLocalAuditPackageSerializationPreview,
        GatewayFormalRealCommandLaneLocalSerializationPreviewReview,
    ) {
        let (
            phase323_root,
            phase327_root,
            execution_root,
            source_root,
            phase323_manifest,
            preflight,
            phase327_manifest,
            input,
        ) = real_command_lane_formal_evidence_candidate_parts(name);
        let candidate = build_gateway_formal_real_command_lane_formal_evidence_candidate(
            &phase323_manifest,
            &preflight,
            &phase327_manifest,
            &input,
        )
        .expect("phase353 candidate builds");
        let preview_input = formal_evidence_review_preview_input(
            &format!("{name}-review-preview"),
            &candidate,
            GatewayFormalRealCommandLaneReviewPreviewDecisionLabel::ReviewPreviewAcceptCandidateScope,
        );
        let preview =
            build_gateway_formal_real_command_lane_review_preview(&candidate, &preview_input)
                .expect("phase353 review preview builds");
        let record_input =
            formal_evidence_reviewed_record_input(&format!("{name}-review-record"), &preview);
        let reviewed_record =
            build_gateway_formal_real_command_lane_reviewed_record(&preview, &record_input)
                .expect("phase353 reviewed record builds");
        let handoff_input =
            formal_evidence_accepted_handoff_input(&format!("{name}-handoff"), &reviewed_record);
        let handoff = build_gateway_formal_real_command_lane_accepted_handoff(
            &reviewed_record,
            &handoff_input,
        )
        .expect("phase353 handoff builds");
        let decision_input =
            formal_evidence_policy_decision_input(&format!("{name}-decision"), &handoff);
        let policy_decision =
            build_gateway_formal_real_command_lane_policy_decision(&handoff, &decision_input)
                .expect("phase353 policy decision builds");
        let feasibility_input = formal_evidence_bounded_feasibility_input(
            &format!("{name}-feasibility"),
            &policy_decision,
        );
        let feasibility =
            build_gateway_formal_real_command_lane_bounded_formal_evidence_feasibility(
                &policy_decision,
                &feasibility_input,
            )
            .expect("phase353 feasibility builds");
        let class_policy_input = formal_evidence_local_non_accepted_class_policy_input(
            &format!("{name}-policy"),
            &feasibility,
        );
        let class_policy = build_gateway_formal_real_command_lane_local_non_accepted_class_policy(
            &feasibility,
            &class_policy_input,
        )
        .expect("phase353 class policy builds");
        let metadata_input = formal_evidence_local_reviewed_metadata_input(
            &format!("{name}-metadata"),
            &class_policy,
        );
        let metadata =
            build_gateway_formal_real_command_lane_local_reviewed_formal_evidence_metadata(
                &class_policy,
                &metadata_input,
            )
            .expect("phase353 metadata builds");
        let metadata_review_input = formal_evidence_local_metadata_review_input(
            &format!("{name}-metadata-review"),
            &metadata,
            GatewayFormalRealCommandLaneLocalMetadataReviewLabel::ReviewScopeAcceptable,
        );
        let metadata_review = build_gateway_formal_real_command_lane_local_metadata_review(
            &metadata,
            &metadata_review_input,
        )
        .expect("phase353 metadata review builds");
        let package_input = formal_evidence_local_review_audit_package_input(
            &format!("{name}-package"),
            &metadata_review,
        );
        let package = build_gateway_formal_real_command_lane_local_review_audit_package(
            &metadata_review,
            &package_input,
        )
        .expect("phase353 package builds");
        let serialization_input = formal_evidence_local_audit_package_serialization_preview_input(
            &format!("{name}-serialization"),
            &package,
        );
        let serialization_preview =
            build_gateway_formal_real_command_lane_local_audit_package_serialization_preview(
                &package,
                &serialization_input,
            )
            .expect("phase353 serialization preview builds");
        let review_input = formal_evidence_local_serialization_preview_review_input(
            &format!("{name}-serialization-review"),
            &serialization_preview,
            GatewayFormalRealCommandLaneLocalSerializationPreviewReviewLabel::MaterializationStillBlocked,
        );
        let review = build_gateway_formal_real_command_lane_local_serialization_preview_review(
            &serialization_preview,
            &review_input,
        )
        .expect("phase353 serialization review builds");
        (
            phase323_root,
            phase327_root,
            execution_root,
            source_root,
            serialization_preview,
            review,
        )
    }

    #[test]
    fn gateway_formal_real_command_lane_fixed_smt_process_executes_and_quarantines_unsat() {
        let (
            execution_root,
            source_root,
            source_manifest,
            execution_manifest,
            request,
            mut command,
            obligation,
            mut obligation_binding,
            mut transcript,
            stdout_summary,
            stderr_summary,
            solver_verdict,
            nonpromotion,
        ) = real_command_lane_valid_parts("real-command-phase326-exec");
        command.argv_template = vec![
            "--ignored".to_owned(),
            "--exact".to_owned(),
            "tests::phase326_fixed_smt_child_unsat".to_owned(),
            "--nocapture".to_owned(),
        ];
        command.argv_template_digest = hash_tagged(
            "hsai-agent-admission:gateway-formal-real-command-lane-argv-template:v1",
            &command.argv_template,
        );
        obligation_binding.command_descriptor_digest = command.digest();
        transcript.command_descriptor_digest = command.digest();
        let output_root = temp_output_root("real-command-phase326-exec-output");
        materialize_gateway_formal_real_command_lane_output_bundle(
            &output_root,
            &source_manifest,
            &execution_manifest,
            &request,
            &command,
            &obligation,
            &obligation_binding,
            &transcript,
            &stdout_summary,
            &stderr_summary,
            &solver_verdict,
            &nonpromotion,
            &real_command_lane_output_request(&output_root),
        )
        .expect("phase326 source bundle materializes");
        let manifest = read_gateway_formal_real_command_lane_output_bundle(&output_root)
            .expect("phase326 source bundle reads back");
        let fixed_executable = std::env::current_exe().expect("current test binary path exists");
        let executable_digest =
            hash_bytes(&fs::read(&fixed_executable).expect("current test binary reads"));
        let mut input = real_command_lane_execution_preflight_input(&manifest, &request, &command);
        input.executable_digest = executable_digest;
        let preflight = build_gateway_formal_real_command_lane_execution_preflight(
            &manifest, &request, &command, &input,
        );

        let output = run_gateway_formal_real_command_lane_fixed_smt_process(
            &preflight,
            &command,
            &fixed_executable,
        )
        .expect("phase326 fixed process executes");

        assert!(output.process_spawn_authorized);
        assert!(output.process_spawned);
        assert!(output.backend_executed);
        assert_eq!(output.process_exit_code_label, "exit_0");
        assert_eq!(
            output.solver_verdict_label,
            GatewayFormalRealCommandLaneSolverVerdictLabel::SolverUnsatWithoutCertificate
        );
        assert!(!output.proof_artifact_created);
        assert!(!output.checker_transcript_created);
        assert!(!output.solver_certificate_created);
        assert!(!output.creates_accepted_evidence);
        assert!(!output.creates_level2_evidence);
        assert!(!output.populates_score_axes);
        assert!(!output.semantic_correctness_claimed);
        assert!(!output.production_readiness_claimed);
        assert!(!output.sota_claimed);
        assert!(!output.breakthrough_claimed);
        assert!(!output.full_security_claimed);
        assert!(!output.grants_authority);
        assert!(!output.raw_logs_retained);
        assert!(!output.stdout_summary.raw_retained);
        assert!(output
            .stdout_summary
            .retained_text
            .contains("retained_sha256="));
        assert!(!output.stdout_summary.retained_text.contains("unsat"));

        let mut bad_preflight = preflight.clone();
        bad_preflight.executable_digest = Hash([9; 32]);
        assert_eq!(
            run_gateway_formal_real_command_lane_fixed_smt_process(
                &bad_preflight,
                &command,
                &fixed_executable,
            ),
            Err(GatewayFormalRealCommandLaneFixedSmtProcessError::ExecutableDigestMismatch)
        );

        fs::remove_dir_all(&output_root).expect("phase326 output cleanup succeeds");
        fs::remove_dir_all(&execution_root).expect("phase326 execution source cleanup succeeds");
        fs::remove_dir_all(&source_root).expect("phase326 adapter source cleanup succeeds");
    }

