    fn quarantine_bundle_path(output_root: &Path, logical_path: &str) -> PathBuf {
        output_root.join(logical_path)
    }

    fn write_quarantine_bytes_with_sidecar(output_root: &Path, logical_path: &str, bytes: &[u8]) {
        let path = quarantine_bundle_path(output_root, logical_path);
        fs::write(&path, bytes).expect("quarantine drift write succeeds");
        fs::write(
            sidecar_path(&path),
            hash_hex(hash_bytes(bytes)).into_bytes(),
        )
        .expect("quarantine sidecar update succeeds");
    }

    fn write_quarantine_json_with_sidecar<T: Serialize>(
        output_root: &Path,
        logical_path: &str,
        value: &T,
    ) {
        let bytes = serde_json::to_vec_pretty(value).expect("quarantine drift serializes");
        write_quarantine_bytes_with_sidecar(output_root, logical_path, &bytes);
    }

