    #[test]
    fn gateway_formal_backend_adapter_report_is_inert_metadata_only() {
        let certificate = gateway_formal_correspondence_certificate();
        let output_root = temp_output_root("gateway-formal-backend-adapter-valid");
        let output_manifest = materialize_gateway_formal_correspondence_bundle(
            &output_root,
            &certificate,
            &gateway_formal_correspondence_output_request("backend-adapter-valid", &output_root),
        )
        .expect("formal correspondence bundle materializes");
        let request = gateway_formal_backend_adapter_request(&certificate, &output_manifest);

        let report =
            build_gateway_formal_backend_adapter_report(&request, &certificate, &output_manifest);

        assert_eq!(
            report.schema_version,
            GATEWAY_FORMAL_BACKEND_ADAPTER_REPORT_SCHEMA_VERSION
        );
        assert_eq!(
            report.status,
            GatewayFormalBackendAdapterStatus::LocalMetadataOnly
        );
        assert_eq!(report.maturity, GatewayFormalBackendAdapterMaturity::NotRun);
        assert!(report.validation.valid, "{:?}", report.validation.issues);
        assert_eq!(report.request_digest, request.digest());
        assert_eq!(
            report.correspondence_certificate_digest,
            certificate.digest()
        );
        assert_eq!(report.output_manifest_digest, output_manifest.digest());
        assert_eq!(report.backend_kind, GatewayFormalBackendKind::RustToLean);
        assert!(!report.creates_formal_proof);
        assert!(!report.mutates_accepted_evidence_ledger);
        assert!(!report.creates_level2_evidence);
        assert!(!report.populates_score_axes);
        assert!(!report.grants_authority);
        assert!(report
            .nonclaims
            .contains(&NonClaimLabel("backend adapter metadata only".to_owned())));
        assert_ne!(report.digest(), Hash([0; 32]));
        fs::remove_dir_all(&output_root).expect("backend adapter valid cleanup succeeds");
    }

    #[test]
    fn gateway_formal_backend_adapter_rejects_digest_source_and_backend_drift() {
        let certificate = gateway_formal_correspondence_certificate();
        let output_root = temp_output_root("gateway-formal-backend-adapter-drift");
        let output_manifest = materialize_gateway_formal_correspondence_bundle(
            &output_root,
            &certificate,
            &gateway_formal_correspondence_output_request("backend-adapter-drift", &output_root),
        )
        .expect("formal correspondence bundle materializes");
        let mut request = gateway_formal_backend_adapter_request(&certificate, &output_manifest);
        request.correspondence_certificate_digest = Hash([109; 32]);
        request.output_manifest_digest = Hash([110; 32]);
        request.source_commit = "other-commit".to_owned();
        request.source_files.pop();
        request.source_anchors.pop();
        request
            .proof_obligations
            .remove(&GatewayFormalProofObligationId::P267ValidationAgreement);
        request.backend_kind = GatewayFormalBackendKind::Smt;
        request.tool_status.backend_kind = GatewayFormalBackendKind::RustToLean;
        request.tool_status.toolchain_lock_digest = Hash([0; 32]);
        request
            .model_assumptions
            .remove("report_data_binding is imported and must be proved or assumed explicitly");
        request
            .modeled_replacements
            .remove("report_data_binding modeled as length-prefixed SHA-256 transcript");
        request.unsupported_rust_features.clear();
        request.input_output_schema_digest = Hash([0; 32]);
        request.expected_proof_artifact_format.clear();
        request.expected_checker_transcript_format.clear();

        let validation = validate_gateway_formal_backend_adapter_request(
            &request,
            &certificate,
            &output_manifest,
        );

        assert!(!validation.valid);
        for expected in [
            GatewayFormalBackendAdapterIssue::CertificateDigestMismatch,
            GatewayFormalBackendAdapterIssue::OutputManifestDigestMismatch,
            GatewayFormalBackendAdapterIssue::SourceCommitMismatch,
            GatewayFormalBackendAdapterIssue::SourceFilesMismatch,
            GatewayFormalBackendAdapterIssue::SourceAnchorsMismatch,
            GatewayFormalBackendAdapterIssue::ProofObligationsMismatch,
            GatewayFormalBackendAdapterIssue::UnsupportedBackendKind,
            GatewayFormalBackendAdapterIssue::ToolBackendKindMismatch,
            GatewayFormalBackendAdapterIssue::MissingToolchainLockDigest,
            GatewayFormalBackendAdapterIssue::MissingModelAssumption(
                "report_data_binding is imported and must be proved or assumed explicitly"
                    .to_owned(),
            ),
            GatewayFormalBackendAdapterIssue::MissingModeledReplacement(
                "report_data_binding modeled as length-prefixed SHA-256 transcript".to_owned(),
            ),
            GatewayFormalBackendAdapterIssue::UnsupportedRustFeaturesMismatch,
            GatewayFormalBackendAdapterIssue::MissingInputOutputSchemaDigest,
            GatewayFormalBackendAdapterIssue::MissingExpectedProofArtifactFormat,
            GatewayFormalBackendAdapterIssue::MissingExpectedCheckerTranscriptFormat,
        ] {
            assert!(
                validation.issues.contains(&expected),
                "missing {expected:?}"
            );
        }
        fs::remove_dir_all(&output_root).expect("backend adapter drift cleanup succeeds");
    }

    #[test]
    fn gateway_formal_backend_adapter_rejects_execution_and_claim_escalation() {
        let certificate = gateway_formal_correspondence_certificate();
        let output_root = temp_output_root("gateway-formal-backend-adapter-escalation");
        let mut output_manifest = materialize_gateway_formal_correspondence_bundle(
            &output_root,
            &certificate,
            &gateway_formal_correspondence_output_request(
                "backend-adapter-escalation",
                &output_root,
            ),
        )
        .expect("formal correspondence bundle materializes");
        let mut request = gateway_formal_backend_adapter_request(&certificate, &output_manifest);
        request.tool_status.execution_status = GatewayFormalToolExecutionStatus::Executed;
        request.proof_artifact_digest = Some(Hash([111; 32]));
        request.checker_transcript_digest = Some(Hash([112; 32]));
        request.requested_maturity = GatewayFormalBackendAdapterMaturity::BackendCheckedCandidate;
        request.formal_backend_execution_requested = true;
        request.accepted_evidence_mutation_requested = true;
        request.level2_evidence_requested = true;
        request.score_axis_population_requested = true;
        request.production_readiness_claimed = true;
        request.semantic_correctness_claimed = true;
        request.sota_claimed = true;
        request.full_security_claimed = true;
        request.authority_grant_requested = true;
        request
            .claim_text
            .push("HSAI is SOTA and proves semantic correctness".to_owned());
        request
            .nonclaims
            .remove(&NonClaimLabel("not backend checked".to_owned()));
        output_manifest.creates_formal_proof = true;

        let report =
            build_gateway_formal_backend_adapter_report(&request, &certificate, &output_manifest);

        assert_eq!(report.status, GatewayFormalBackendAdapterStatus::Rejected);
        assert_eq!(report.maturity, GatewayFormalBackendAdapterMaturity::NotRun);
        assert!(!report.validation.valid);
        for expected in [
            GatewayFormalBackendAdapterIssue::OutputManifestEscalated,
            GatewayFormalBackendAdapterIssue::FormalBackendExecuted,
            GatewayFormalBackendAdapterIssue::ProofArtifactDigestSubmitted,
            GatewayFormalBackendAdapterIssue::CheckerTranscriptDigestSubmitted,
            GatewayFormalBackendAdapterIssue::MaturityEscalated,
            GatewayFormalBackendAdapterIssue::FormalBackendExecutionRequested,
            GatewayFormalBackendAdapterIssue::AcceptedEvidenceMutationRequested,
            GatewayFormalBackendAdapterIssue::Level2EvidenceRequested,
            GatewayFormalBackendAdapterIssue::ScoreAxisPopulationRequested,
            GatewayFormalBackendAdapterIssue::ProductionReadinessClaimed,
            GatewayFormalBackendAdapterIssue::SemanticCorrectnessClaimed,
            GatewayFormalBackendAdapterIssue::SotaClaimed,
            GatewayFormalBackendAdapterIssue::FullSecurityClaimed,
            GatewayFormalBackendAdapterIssue::AuthorityGrantRequested,
            GatewayFormalBackendAdapterIssue::ForbiddenClaimText("sota".to_owned()),
            GatewayFormalBackendAdapterIssue::ForbiddenClaimText("semantic correctness".to_owned()),
            GatewayFormalBackendAdapterIssue::MissingRequiredNonclaim(
                "not backend checked".to_owned(),
            ),
        ] {
            assert!(
                report.validation.issues.contains(&expected),
                "missing {expected:?}"
            );
        }
        fs::remove_dir_all(&output_root).expect("backend adapter escalation cleanup succeeds");
    }

