    #[test]
    fn gateway_formal_backend_run_artifact_rejects_execution_and_artifact_refs() {
        let certificate = gateway_formal_correspondence_certificate();
        let output_root = temp_output_root("gateway-formal-backend-run-artifact-escalation");
        let output_manifest = materialize_gateway_formal_correspondence_bundle(
            &output_root,
            &certificate,
            &gateway_formal_correspondence_output_request("backend-run-escalation", &output_root),
        )
        .expect("formal correspondence bundle materializes");
        let request = gateway_formal_backend_adapter_request(&certificate, &output_manifest);
        let adapter_report =
            build_gateway_formal_backend_adapter_report(&request, &certificate, &output_manifest);
        let mut metadata = build_gateway_formal_backend_run_artifact_metadata(
            "phase-276-backend-run",
            &request,
            &adapter_report,
        );
        metadata.execution_mode = GatewayFormalBackendRunExecutionMode::HermeticFixtureOnly;
        metadata.started_at_unix = Some(1_800_000_300);
        metadata.finished_at_unix = Some(1_800_000_301);
        metadata.exit_status = GatewayFormalBackendRunExitStatus::Succeeded;
        metadata.checker_status = GatewayFormalBackendRunCheckerStatus::Checked;
        metadata
            .proof_obligations_discharged
            .insert(GatewayFormalProofObligationId::P267ValidationAgreement);
        metadata
            .proof_obligations_not_discharged
            .insert(GatewayFormalProofObligationId::P267NonceSensitivity);
        metadata.candidate_proof_artifact_ref = Some(GatewayFormalBackendRunArtifactReference {
            logical_path: "gateway-formal-backend-run/candidate-proof-artifact.ref.json".to_owned(),
            digest: Hash([120; 32]),
            redacted: true,
            retains_raw_content: false,
        });
        metadata.candidate_checker_transcript_ref =
            Some(GatewayFormalBackendRunArtifactReference {
                logical_path: "../checker-transcript".to_owned(),
                digest: Hash([0; 32]),
                redacted: false,
                retains_raw_content: true,
            });
        metadata.candidate_tool_log_summary_digest = Some(Hash([121; 32]));
        metadata.creates_accepted_evidence = true;
        metadata.creates_level2_evidence = true;
        metadata.populates_score_axes = true;
        metadata.grants_authority = true;
        metadata.semantic_correctness_claimed = true;
        metadata.production_readiness_claimed = true;
        metadata.sota_claimed = true;
        metadata.full_security_claimed = true;
        metadata
            .claim_text
            .push("HSAI is SOTA and proves semantic correctness".to_owned());
        metadata
            .nonclaims
            .remove(&NonClaimLabel("backend not run".to_owned()));

        let validation = validate_gateway_formal_backend_run_artifact_metadata(
            &metadata,
            &request,
            &adapter_report,
        );

        assert!(!validation.valid);
        for expected in [
            GatewayFormalBackendRunArtifactIssue::ExecutionModeNotRunMismatch,
            GatewayFormalBackendRunArtifactIssue::TimestampSubmitted,
            GatewayFormalBackendRunArtifactIssue::ExitStatusNotRunMismatch,
            GatewayFormalBackendRunArtifactIssue::CheckerStatusNotRunMismatch,
            GatewayFormalBackendRunArtifactIssue::ProofObligationsDischargedBeforeRun,
            GatewayFormalBackendRunArtifactIssue::ProofObligationsNotDischargedBeforeRun,
            GatewayFormalBackendRunArtifactIssue::ProofArtifactReferenceSubmitted,
            GatewayFormalBackendRunArtifactIssue::CheckerTranscriptReferenceSubmitted,
            GatewayFormalBackendRunArtifactIssue::InvalidArtifactReference(
                "../checker-transcript".to_owned(),
            ),
            GatewayFormalBackendRunArtifactIssue::ArtifactReferenceMissingDigest(
                "../checker-transcript".to_owned(),
            ),
            GatewayFormalBackendRunArtifactIssue::ArtifactReferenceRetainsRawContent(
                "../checker-transcript".to_owned(),
            ),
            GatewayFormalBackendRunArtifactIssue::ToolLogSummarySubmitted,
            GatewayFormalBackendRunArtifactIssue::AcceptedEvidenceCreated,
            GatewayFormalBackendRunArtifactIssue::Level2EvidenceCreated,
            GatewayFormalBackendRunArtifactIssue::ScoreAxesPopulated,
            GatewayFormalBackendRunArtifactIssue::AuthorityGranted,
            GatewayFormalBackendRunArtifactIssue::SemanticCorrectnessClaimed,
            GatewayFormalBackendRunArtifactIssue::ProductionReadinessClaimed,
            GatewayFormalBackendRunArtifactIssue::SotaClaimed,
            GatewayFormalBackendRunArtifactIssue::FullSecurityClaimed,
            GatewayFormalBackendRunArtifactIssue::ForbiddenClaimText("sota".to_owned()),
            GatewayFormalBackendRunArtifactIssue::ForbiddenClaimText(
                "semantic correctness".to_owned(),
            ),
            GatewayFormalBackendRunArtifactIssue::MissingRequiredNonclaim(
                "backend not run".to_owned(),
            ),
        ] {
            assert!(
                validation.issues.contains(&expected),
                "missing {expected:?}"
            );
        }
        fs::remove_dir_all(&output_root).expect("backend run artifact escalation cleanup succeeds");
    }

