    #[test]
    fn gateway_formal_backend_transcript_rejects_execution_and_claim_escalation() {
        let (
            preflight_request,
            preflight_report,
            preflight_manifest,
            preflight_root,
            run_root,
            correspondence_root,
        ) = gateway_formal_backend_transcript_fixture("transcript-escalation");
        let mut metadata = build_gateway_formal_backend_execution_transcript_metadata(
            "phase-285-transcript",
            &preflight_request,
            &preflight_report,
            &preflight_manifest,
        );

        metadata.execution_status =
            GatewayFormalBackendTranscriptExecutionStatus::ExecutedCandidate;
        metadata.started_at_unix = Some(1_800_001_000);
        metadata.finished_at_unix = Some(1_800_001_001);
        metadata.exit_status = GatewayFormalBackendRunExitStatus::Succeeded;
        metadata.checker_status = GatewayFormalBackendTranscriptCheckerStatus::Checked;
        metadata.redacted_stdout_summary_digest = Some(Hash([7; 32]));
        metadata.redacted_stderr_summary_digest = Some(Hash([8; 32]));
        metadata.proof_artifact_ref = Some(GatewayFormalBackendTranscriptReference {
            logical_path: "accepted-evidence/proof.json".to_owned(),
            digest: Hash([0; 32]),
            redacted: false,
            retains_raw_content: true,
        });
        metadata.checker_transcript_ref = Some(GatewayFormalBackendTranscriptReference {
            logical_path: "gateway-formal-backend-transcript/checker.json".to_owned(),
            digest: Hash([9; 32]),
            redacted: false,
            retains_raw_content: true,
        });
        metadata
            .proof_obligations_requested
            .insert(GatewayFormalProofObligationId::P267DeterministicConstructor);
        metadata
            .proof_obligations_discharged
            .insert(GatewayFormalProofObligationId::P267NonceSensitivity);
        metadata
            .proof_obligations_not_discharged
            .insert(GatewayFormalProofObligationId::P267ValidationAgreement);
        metadata
            .verifier_trust_roots
            .insert("future-checker-root".to_owned());
        metadata.redaction_report.retains_raw_solver_traces = true;
        metadata.backend_executed = true;
        metadata.proof_artifact_created = true;
        metadata.checker_transcript_created = true;
        metadata.checker_succeeded = true;
        metadata.creates_accepted_evidence = true;
        metadata.creates_level2_evidence = true;
        metadata.populates_score_axes = true;
        metadata.grants_authority = true;
        metadata.semantic_correctness_claimed = true;
        metadata.production_readiness_claimed = true;
        metadata.sota_claimed = true;
        metadata.full_security_claimed = true;
        metadata.claim_text = vec![
            "HSAI is SOTA and proves semantic correctness.".to_owned(),
            "HSAI is fully secure and production ready.".to_owned(),
        ];
        metadata.nonclaims.remove(&NonClaimLabel(
            "checker success is not semantic correctness".to_owned(),
        ));

        let validation = validate_gateway_formal_backend_execution_transcript_metadata(
            &metadata,
            &preflight_request,
            &preflight_report,
            &preflight_manifest,
        );

        assert!(!validation.valid);
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendTranscriptIssue::ExecutionStatusEscalated));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendTranscriptIssue::TimestampSubmitted));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendTranscriptIssue::ExitStatusEscalated));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendTranscriptIssue::CheckerStatusEscalated));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendTranscriptIssue::StdoutSummarySubmitted));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendTranscriptIssue::StderrSummarySubmitted));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendTranscriptIssue::ProofArtifactReferenceSubmitted));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendTranscriptIssue::CheckerTranscriptReferenceSubmitted));
        assert!(validation.issues.iter().any(|issue| matches!(
            issue,
            GatewayFormalBackendTranscriptIssue::InvalidTranscriptReference(path)
                if path == "accepted-evidence/proof.json"
        )));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendTranscriptIssue::ProofObligationsRequestedMismatch));
        assert!(validation.issues.contains(
            &GatewayFormalBackendTranscriptIssue::ProofObligationsDischargedBeforeExecution
        ));
        assert!(validation.issues.contains(
            &GatewayFormalBackendTranscriptIssue::ProofObligationsNotDischargedBeforeExecution
        ));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendTranscriptIssue::VerifierTrustRootSubmitted));
        assert!(validation.issues.contains(
            &GatewayFormalBackendTranscriptIssue::RedactionReportRetainsForbiddenMaterial
        ));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendTranscriptIssue::BackendExecuted));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendTranscriptIssue::ProofArtifactCreated));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendTranscriptIssue::CheckerTranscriptCreated));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendTranscriptIssue::CheckerSucceeded));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendTranscriptIssue::AcceptedEvidenceCreated));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendTranscriptIssue::Level2EvidenceCreated));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendTranscriptIssue::ScoreAxesPopulated));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendTranscriptIssue::AuthorityGranted));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendTranscriptIssue::SemanticCorrectnessClaimed));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendTranscriptIssue::ProductionReadinessClaimed));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendTranscriptIssue::SotaClaimed));
        assert!(validation
            .issues
            .contains(&GatewayFormalBackendTranscriptIssue::FullSecurityClaimed));
        assert!(validation.issues.iter().any(|issue| matches!(
            issue,
            GatewayFormalBackendTranscriptIssue::ForbiddenClaimText(fragment)
                if fragment == "sota"
        )));
        assert!(validation.issues.contains(
            &GatewayFormalBackendTranscriptIssue::MissingRequiredNonclaim(
                "checker success is not semantic correctness".to_owned()
            )
        ));

        fs::remove_dir_all(&preflight_root)
            .expect("transcript escalation preflight cleanup succeeds");
        fs::remove_dir_all(&run_root).expect("transcript escalation run cleanup succeeds");
        fs::remove_dir_all(&correspondence_root)
            .expect("transcript escalation correspondence cleanup succeeds");
    }

