        fs::remove_file(sidecar_path(
            &missing_root.join("gateway-formal-backend-transcript/manifest.json"),
        ))
        .expect("manifest sidecar removal succeeds");
        assert!(matches!(
            read_gateway_formal_backend_transcript_output_bundle(&missing_root),
            Err(GatewayFormalBackendTranscriptOutputError::Io(_))
        ));

        let (
            _metadata,
            _manifest,
            malformed_root,
            malformed_preflight_root,
            malformed_run_root,
            malformed_correspondence_root,
        ) = gateway_formal_backend_transcript_output_bundle_fixture(
            "transcript-output-malformed-json",
        );
        let malformed_path =
            malformed_root.join("gateway-formal-backend-transcript/transcript-metadata.json");
        fs::write(&malformed_path, b"{not-json")
            .expect("malformed transcript metadata write succeeds");
        fs::write(
            sidecar_path(&malformed_path),
            hash_hex(hash_bytes(b"{not-json")).into_bytes(),
        )
        .expect("malformed transcript metadata sidecar update succeeds");
        assert_eq!(
            read_gateway_formal_backend_transcript_output_bundle(&malformed_root),
            Err(
                GatewayFormalBackendTranscriptOutputError::MalformedDeclaredFile(
                    "gateway-formal-backend-transcript/transcript-metadata.json".to_owned()
                )
            )
        );

        fs::remove_dir_all(&stale_root).expect("stale sidecar root cleanup succeeds");
        fs::remove_dir_all(&stale_preflight_root)
            .expect("stale sidecar preflight cleanup succeeds");
        fs::remove_dir_all(&stale_run_root).expect("stale sidecar run cleanup succeeds");
        fs::remove_dir_all(&stale_correspondence_root)
            .expect("stale sidecar correspondence cleanup succeeds");
        fs::remove_dir_all(&missing_root).expect("missing sidecar root cleanup succeeds");
        fs::remove_dir_all(&missing_preflight_root)
