    #[test]
    fn gateway_formal_backend_execution_quarantine_validation_summary_is_local_and_deterministic() {
        let (
            _metadata,
            manifest,
            output_root,
            authorization_root,
            transcript_root,
            preflight_root,
            run_root,
            correspondence_root,
        ) = gateway_formal_backend_execution_quarantine_output_bundle_fixture(
            "quarantine-validation-summary-valid",
        );

        let summary_a = build_gateway_formal_backend_execution_quarantine_validation_summary(
            "quarantine-validation-summary-valid",
            1_800_001_200,
            &manifest,
        );
        let summary_b = build_gateway_formal_backend_execution_quarantine_validation_summary(
            "quarantine-validation-summary-valid",
            1_800_001_200,
            &manifest,
        );
        let validation = validate_gateway_formal_backend_execution_quarantine_validation_summary(
            &summary_a, &manifest,
        );

        assert_eq!(summary_a, summary_b);
        assert_eq!(summary_a.digest(), summary_b.digest());
        assert!(validation.valid);
        assert!(validation.issues.is_empty());
        assert_eq!(
            summary_a.quarantine_output_manifest_digest,
            manifest.digest()
        );
        assert_eq!(
            summary_a.quarantine_artifact_digest,
            manifest.quarantine_artifact_digest
        );
        assert_eq!(summary_a.declared_files_checked, manifest.declared_files);
        assert!(summary_a.readback_validation_passed);
        assert!(summary_a.local_regression_only);
        assert!(summary_a.no_backend_executed);
        assert!(!summary_a.proof_artifact_promoted);
        assert!(!summary_a.checker_transcript_promoted);
        assert!(!summary_a.accepted_evidence_mutation);
        assert!(!summary_a.creates_level2_evidence);
        assert!(!summary_a.populates_score_axes);
        assert!(!summary_a.semantic_correctness_claimed);
        assert!(!summary_a.production_readiness_claimed);
        assert!(!summary_a.sota_claimed);
        assert!(!summary_a.breakthrough_claimed);
        assert!(!summary_a.full_security_claimed);
        assert!(!summary_a.grants_authority);
        assert_eq!(
            summary_a.claim_boundary,
            gateway_formal_backend_execution_quarantine_validation_summary_claim_boundary()
        );

        cleanup_quarantine_output_fixture(
            &output_root,
            &authorization_root,
            &transcript_root,
            &preflight_root,
            &run_root,
            &correspondence_root,
        );
    }

    #[test]
    fn gateway_formal_backend_execution_quarantine_validation_summary_rejects_identity_digest_and_coverage_drift(
    ) {
        let (
            _metadata,
            manifest,
            output_root,
            authorization_root,
            transcript_root,
            preflight_root,
            run_root,
            correspondence_root,
        ) = gateway_formal_backend_execution_quarantine_output_bundle_fixture(
            "quarantine-validation-summary-drift",
        );
        let mut summary = build_gateway_formal_backend_execution_quarantine_validation_summary(
            "quarantine-validation-summary-drift",
            1_800_001_201,
            &manifest,
        );
        summary.schema_version = "wrong".to_owned();
        summary.state_slice = "wrong".to_owned();
        summary.summary_id = "../bad".to_owned();
        summary.quarantine_output_manifest_digest = Hash([0; 32]);
        summary.quarantine_artifact_digest = Hash([0; 32]);
        summary.declared_files_checked.clear();
        summary.sidecars_checked.clear();
        summary.readback_validation_passed = false;
        summary
            .drift_coverage_labels
            .remove("authorization-binding-drift-rejection");
        summary
            .drift_coverage_labels
            .insert("unknown-drift-label".to_owned());

        let validation = validate_gateway_formal_backend_execution_quarantine_validation_summary(
            &summary, &manifest,
        );

        assert!(!validation.valid);
        assert!(validation.issues.contains(
            &GatewayFormalBackendExecutionQuarantineValidationSummaryIssue::InvalidSchemaVersion
        ));
        assert!(validation.issues.contains(
            &GatewayFormalBackendExecutionQuarantineValidationSummaryIssue::StateSliceMismatch
        ));
        assert!(validation.issues.contains(
            &GatewayFormalBackendExecutionQuarantineValidationSummaryIssue::InvalidSummaryId
        ));
        assert!(validation.issues.contains(
            &GatewayFormalBackendExecutionQuarantineValidationSummaryIssue::ManifestDigestMismatch
        ));
        assert!(validation.issues.contains(
            &GatewayFormalBackendExecutionQuarantineValidationSummaryIssue::QuarantineArtifactDigestMismatch
        ));
        assert!(validation.issues.contains(
            &GatewayFormalBackendExecutionQuarantineValidationSummaryIssue::DeclaredFilesMismatch
        ));
        assert!(validation.issues.contains(
            &GatewayFormalBackendExecutionQuarantineValidationSummaryIssue::SidecarsMismatch
        ));
        assert!(validation.issues.contains(
            &GatewayFormalBackendExecutionQuarantineValidationSummaryIssue::ReadbackValidationFailed
        ));
        assert!(validation.issues.contains(
            &GatewayFormalBackendExecutionQuarantineValidationSummaryIssue::MissingCoverageLabel(
                "authorization-binding-drift-rejection".to_owned()
            )
        ));
        assert!(validation.issues.contains(
            &GatewayFormalBackendExecutionQuarantineValidationSummaryIssue::UnknownCoverageLabel(
                "unknown-drift-label".to_owned()
            )
        ));

        cleanup_quarantine_output_fixture(
            &output_root,
            &authorization_root,
            &transcript_root,
            &preflight_root,
            &run_root,
            &correspondence_root,
        );
    }

