    #[test]
    fn gateway_formal_backend_hermetic_descriptor_report_output_bundle_rejects_readback_drift() {
        let (descriptor, report) = gateway_formal_backend_hermetic_descriptor_report_fixture(
            "hermetic-descriptor-report-output-drift",
        );

        let stale_root =
            temp_output_root("gateway-formal-backend-hermetic-descriptor-report-output-stale");
        materialize_gateway_formal_backend_hermetic_descriptor_report_output_bundle(
            &stale_root,
            &descriptor,
            &report,
            &gateway_formal_backend_hermetic_descriptor_report_output_request(
                "hermetic-descriptor-report-output-stale",
                &stale_root,
            ),
        )
        .expect("stale hermetic descriptor report output materializes");
        let descriptor_path =
            stale_root.join("gateway-formal-backend-hermetic-descriptor-report/descriptor.json");
        fs::write(sidecar_path(&descriptor_path), b"stale")
            .expect("hermetic descriptor stale sidecar writes");
        assert_eq!(
            read_gateway_formal_backend_hermetic_descriptor_report_output_bundle(&stale_root),
            Err(
                GatewayFormalBackendHermeticDescriptorReportOutputError::DigestMismatch(
                    "gateway-formal-backend-hermetic-descriptor-report/descriptor.json".to_owned()
                )
            )
        );

        let validation_root =
            temp_output_root("gateway-formal-backend-hermetic-descriptor-report-output-validation");
        materialize_gateway_formal_backend_hermetic_descriptor_report_output_bundle(
            &validation_root,
            &descriptor,
            &report,
            &gateway_formal_backend_hermetic_descriptor_report_output_request(
                "hermetic-descriptor-report-output-validation",
                &validation_root,
            ),
        )
        .expect("validation hermetic descriptor report output materializes");
        let mut validation = report.validation.clone();
        validation.valid = false;
        write_validation_summary_json_with_sidecar(
            &validation_root,
            "gateway-formal-backend-hermetic-descriptor-report/validation.json",
            &validation,
        );
        assert_eq!(
            read_gateway_formal_backend_hermetic_descriptor_report_output_bundle(&validation_root),
            Err(GatewayFormalBackendHermeticDescriptorReportOutputError::ValidationMismatch)
        );

        let command_root =
            temp_output_root("gateway-formal-backend-hermetic-descriptor-report-output-command");
        materialize_gateway_formal_backend_hermetic_descriptor_report_output_bundle(
            &command_root,
            &descriptor,
            &report,
            &gateway_formal_backend_hermetic_descriptor_report_output_request(
                "hermetic-descriptor-report-output-command",
                &command_root,
            ),
        )
        .expect("command hermetic descriptor report output materializes");
        let command_path = command_root
            .join("gateway-formal-backend-hermetic-descriptor-report/command-contract.json");
        let mut command_contract: GatewayFormalBackendHermeticDescriptorReportCommandContract =
            serde_json::from_slice(&fs::read(&command_path).expect("command contract reads"))
                .expect("command contract parses");
        command_contract.no_spawn = false;
        write_validation_summary_json_with_sidecar(
            &command_root,
            "gateway-formal-backend-hermetic-descriptor-report/command-contract.json",
            &command_contract,
        );
        assert_eq!(
            read_gateway_formal_backend_hermetic_descriptor_report_output_bundle(&command_root),
            Err(GatewayFormalBackendHermeticDescriptorReportOutputError::CommandContractMismatch)
        );

        let manifest_root =
            temp_output_root("gateway-formal-backend-hermetic-descriptor-report-output-manifest");
        materialize_gateway_formal_backend_hermetic_descriptor_report_output_bundle(
            &manifest_root,
            &descriptor,
            &report,
            &gateway_formal_backend_hermetic_descriptor_report_output_request(
                "hermetic-descriptor-report-output-manifest",
                &manifest_root,
            ),
        )
        .expect("manifest hermetic descriptor report output materializes");
        let manifest_path =
            manifest_root.join("gateway-formal-backend-hermetic-descriptor-report/manifest.json");
        let mut manifest: GatewayFormalBackendHermeticDescriptorReportOutputManifest =
            serde_json::from_slice(&fs::read(&manifest_path).expect("manifest reads"))
                .expect("manifest parses");
        manifest.creates_level2_evidence = true;
        write_validation_summary_json_with_sidecar(
            &manifest_root,
            "gateway-formal-backend-hermetic-descriptor-report/manifest.json",
            &manifest,
        );
        assert_eq!(
            read_gateway_formal_backend_hermetic_descriptor_report_output_bundle(&manifest_root),
            Err(GatewayFormalBackendHermeticDescriptorReportOutputError::ManifestSemanticMismatch)
        );

        cleanup_validation_summary_output_fixture(&stale_root);
        cleanup_validation_summary_output_fixture(&validation_root);
        cleanup_validation_summary_output_fixture(&command_root);
        cleanup_validation_summary_output_fixture(&manifest_root);
    }

